INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13885, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正在汲取了经验。", "corrected_sentence": "我们正在汲取经验。", "error_description": "“汲取”后的“了”与“正在”矛盾：“正在”表示动作进行中，不能与表示完成的“了”同用。应去掉“了”，说“正在汲取经验”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13885, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他汲取了过经验。", "corrected_sentence": "他汲取过经验。", "error_description": "“汲取”的体标错位：“了”与“过”不能这样连用，应去掉“了”，说“汲取过经验”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94806ba5-fdd3-4ab9-a20c-1bf54e573444') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
