INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13886, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指在创作或思考过程中突然产生的巧妙想法或创作冲动。", "primary_collocate": null, "pronunciation": "líng gǎn", "ipa": "liŋ˧˥ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这种从自然智慧中汲取灵感的跨学科探索，进一步凸显了保护昆虫多样性的深远意义。", "target_word": "灵感", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "画家在海边散步时，突然有了新的灵感。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家常常从生活中找到写作的灵感。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听完这首歌，他的创作灵感来了。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师的灵感来自一片落叶。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有灵感的时候，她就出去走走。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位诗人的灵感总是在夜里出现。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，读书能给我们带来灵感。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿起笔，把脑子里的灵感写了下来。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的画给了设计师很多灵感。", "target_word": "灵感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "创作灵感", "label": "复合"}], "register": "中性", "sense_fingerprint": "创作或思考时突然出现的巧妙想法或冲动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f0f8b3d-3b38-41b9-91fd-9b8b797a5035') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13886, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "噪音", "is_correct": false, "explanation": "语义：“汲取”的对象应是有益的东西，“噪音”与智慧无关，句子不通。"}, {"text": "灵感", "is_correct": true, "explanation": "正确：“汲取灵感”指从事物中获得创作上的启发，与“自然智慧”“跨学科探索”的语境相符。"}, {"text": "烟雾", "is_correct": false, "explanation": "搭配：“汲取”常接养分、经验、知识等，不与“烟雾”搭配。"}, {"text": "废墟", "is_correct": false, "explanation": "语义：废墟是毁坏后的遗迹，与“从自然智慧中汲取”的积极含义相反。"}], "explanations": {"噪音": "语义：“汲取”的对象应是有益的东西，“噪音”与智慧无关，句子不通。", "灵感": "正确：“汲取灵感”指从事物中获得创作上的启发，与“自然智慧”“跨学科探索”的语境相符。", "烟雾": "搭配：“汲取”常接养分、经验、知识等，不与“烟雾”搭配。", "废墟": "语义：废墟是毁坏后的遗迹，与“从自然智慧中汲取”的积极含义相反。"}, "sentence_index": 0, "correct_answer": "灵感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他认真制定了一个灵感，准备明天开始执行。", "explanation": "这里应该用〈计划〉。“制定”和“执行”用于计划、方案，“灵感”指突然产生的想法，不能被制定或执行。"}, {"text": "这位老人的灵感很善良。", "explanation": "这里应该用〈心地〉。“善良”形容人的品性，“心地善良”是固定说法；“灵感”指创作时突然产生的想法，不能这样形容。"}, {"text": "这个灵感很重，我拿不动。", "explanation": "这里应该用〈东西〉。“重”和“拿不动”指有形实体的重量，“灵感”是抽象的想法，没有重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "语义：“工资”是报酬，不会“总是在夜里出现”，与诗人创作的语境不合。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“出现”不与“体重”搭配，句子所说的是诗人的创作，而非身体指标。"}, {"text": "灵感", "is_correct": true, "explanation": "正确：“诗人的灵感”指创作时突然冒出的想法，“总是在夜里出现”符合语境。"}, {"text": "账单", "is_correct": false, "explanation": "语义：“账单”与诗人的创作无关，“在夜里出现”也不通顺。"}], "explanations": {"工资": "语义：“工资”是报酬，不会“总是在夜里出现”，与诗人创作的语境不合。", "体重": "搭配：“出现”不与“体重”搭配，句子所说的是诗人的创作，而非身体指标。", "灵感": "正确：“诗人的灵感”指创作时突然冒出的想法，“总是在夜里出现”符合语境。", "账单": "语义：“账单”与诗人的创作无关，“在夜里出现”也不通顺。"}, "sentence_index": 6, "correct_answer": "灵感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他读完那本书，把灵感还给了图书馆。", "explanation": "这里应该用〈资料〉。“还”用于归还借来的东西，“灵感”是自己突然产生的想法，不能被归还。"}, {"text": "他的灵感很敏捷。", "explanation": "这里应该用〈思维〉。“敏捷”形容思考的速度，“灵感”不能用来这样形容。"}, {"text": "他和家人的灵感很疏远。", "explanation": "这里应该用〈感情〉。“疏远”指人与人之间的关系，“灵感”不能用来指人际关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在海边坐了很久，一条灵感也没有。", "corrected_sentence": "她在海边坐了很久，一点灵感也没有。", "error_description": "错误：“灵感”前的量词用了“条”。“条”用于细长的东西，灵感应用“点”（或“丝”“股”）计量。正确应为“一点灵感”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年就有了过这样的灵感。", "corrected_sentence": "他去年就有过这样的灵感。", "error_description": "错误：“有过”表示经历过，句中又加了“了”，形成“有了过”的重复。正确应为“有过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54c86b3-c290-4d8b-95c6-0bc26c161b05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
