INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19861, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从别处到说话人所在的位置。", "primary_collocate": null, "pronunciation": "lái", "ipa": "lai̯˧˥", "syllable_count": 1, "sentences": [{"text": "明天我朋友要来我家吃饭。", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么这么晚才来？", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师还没来，大家先坐下吧。", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在楼下等你，你快点来。", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天来过我们学校。", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈来了，快去开门。", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个月我姐姐会来北京看我。", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你明天早上八点来办公室。", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面有人敲门，你去看看是谁来了。", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你来我这儿，我给你看一张照片。", "target_word": "来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "来了", "label": "体标"}, {"form": "来过", "label": "体标"}, {"form": "來", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：从别处到说话人所在的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40c6bb68-9edb-4a24-ad31-cf0cde640a3d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19861, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "来", "is_correct": true, "explanation": "正确。“来”表示从别处到说话人所在的位置。"}, {"text": "蓝", "is_correct": false, "explanation": "lán 与 lái 韵母不同，lán 意思是蓝色。"}, {"text": "狼", "is_correct": false, "explanation": "láng 与 lái 韵母不同，láng 意思是狼。"}, {"text": "赖", "is_correct": false, "explanation": "lài（第四声）与 lái（第二声）声调不同，lài 意思是抵赖。"}, {"text": "白", "is_correct": false, "explanation": "bái 与 lái 声母不同，bái 意思是白色。"}], "explanations": {"来": "正确。“来”表示从别处到说话人所在的位置。", "蓝": "lán 与 lái 韵母不同，lán 意思是蓝色。", "狼": "láng 与 lái 韵母不同，láng 意思是狼。", "赖": "lài（第四声）与 lái（第二声）声调不同，lài 意思是抵赖。", "白": "bái 与 lái 声母不同，bái 意思是白色。"}, "sentence_index": null, "correct_answer": "来"}, "level_3": {"options": [{"text": "来", "is_correct": true, "explanation": "正确。“朋友要来我家吃饭”表示朋友从别处到说话人家。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象是衣物或身体，不能说洗“我家”吃饭。"}, {"text": "画", "is_correct": false, "explanation": "语义：“画”的对象是图画，与“吃饭”的句意无关。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“我家”作地点，句子不成立。"}], "explanations": {"来": "正确。“朋友要来我家吃饭”表示朋友从别处到说话人家。", "洗": "语义：“洗”的对象是衣物或身体，不能说洗“我家”吃饭。", "画": "语义：“画”的对象是图画，与“吃饭”的句意无关。", "唱": "搭配：“唱”不能带“我家”作地点，句子不成立。"}, "sentence_index": 0, "correct_answer": "来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我现在在北京，妈妈明天来上海买菜。", "explanation": "这里应该用〈去〉。说话人在北京，妈妈去上海买菜要用「去」，「来」以说话人所在处为目标。"}, {"text": "我在北京，下周我来老家过年。", "explanation": "这里应该用〈回〉。老家是说话人自己的家，回去过年要用「回」。"}, {"text": "我在北京，他明天来上海开会。", "explanation": "这里应该用〈去〉。说话人在北京，他前往上海开会要用「去」，不能用「来」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19861, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "来", "is_correct": true, "explanation": "正确。“来”表示从别处到说话人所在的位置。"}, {"text": "篮", "is_correct": false, "explanation": "lán 与 lái 韵母不同，lán 意思是篮子。"}, {"text": "才", "is_correct": false, "explanation": "cái 与 lái 声母不同，cái 意思是才、刚刚。"}, {"text": "排", "is_correct": false, "explanation": "pái 与 lái 声母不同，pái 意思是排列、排队。"}], "explanations": {"来": "正确。“来”表示从别处到说话人所在的位置。", "篮": "lán 与 lái 韵母不同，lán 意思是篮子。", "才": "cái 与 lái 声母不同，cái 意思是才、刚刚。", "排": "pái 与 lái 声母不同，pái 意思是排列、排队。"}, "sentence_index": null, "correct_answer": "来"}, "level_3": {"options": [{"text": "来", "is_correct": true, "explanation": "正确。“姐姐会来北京看我”表示姐姐从别处到北京、到说话人所在的地方。"}, {"text": "住", "is_correct": false, "explanation": "配价：“住”后要用“在”引出处所，“住北京看我”不成立。"}, {"text": "逛", "is_correct": false, "explanation": "语义：“逛”指随意走动，与“来北京看我”的语境不合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”与“来北京看我”的动作无关，句子不成立。"}], "explanations": {"来": "正确。“姐姐会来北京看我”表示姐姐从别处到北京、到说话人所在的地方。", "住": "配价：“住”后要用“在”引出处所，“住北京看我”不成立。", "逛": "语义：“逛”指随意走动，与“来北京看我”的语境不合。", "吃": "搭配：“吃”与“来北京看我”的动作无关，句子不成立。"}, "sentence_index": 6, "correct_answer": "来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在上海，明天我来北京出差。", "explanation": "这里应该用〈去〉。说话人在上海，要到北京出差是离开说话人所在地，要用「去」，「来」以说话人所在处为目标。"}, {"text": "我在上海，妈妈明天来北京开会。", "explanation": "这里应该用〈去〉。说话人在上海，妈妈到北京不是到说话人这里，要用「去」。"}, {"text": "我在家，晚上我来宿舍睡觉。", "explanation": "这里应该用〈去〉。说话人在家，去宿舍睡觉要用「去」，「来」以说话人所在处为目标。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19861, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从外面走来进了。", "corrected_sentence": "他从外面走进来了。", "error_description": "错误：趋向补语「进来」的两个成分语序颠倒，「来」必须放在「进」的后面。正确是「走进来了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19861, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她昨天没来了上课。", "corrected_sentence": "她昨天没有来上课。", "error_description": "错误：「没」否定过去的动作后不能再加「了」，「没来了」不成立。正确是「没来上课」，应说「她昨天没有来上课」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4eacca5e-114b-458c-b73b-212c17bea824') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
