INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19862, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用语言表达思想、感情或意见。", "primary_collocate": null, "pronunciation": "shuō", "ipa": "ʂwo˥", "syllable_count": 1, "sentences": [{"text": "他说他明天不能来开会。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说得很清楚，大家都听懂了。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么意见，可以直接说。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说天气冷，让我多穿一件衣服。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想对你说一句谢谢。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说过会帮我，可是没有来。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说着说着，突然哭了起来。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把你的想法说给大家听听。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说汉语说得又快又好。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟不喜欢说自己的心事。", "target_word": "说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "说了", "label": "体标"}, {"form": "说过", "label": "体标"}, {"form": "说着", "label": "体标"}, {"form": "说说", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用话语表达想法、感情或意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6062633-d150-4b42-8c9e-91408b62d40d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19862, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "说", "is_correct": true, "explanation": "正确：“说”读 shuō（第一声），意思是用话语表达。"}, {"text": "桌", "is_correct": false, "explanation": "zhuō 与 shuō 声母不同（zh 与 sh），意思是桌子。"}, {"text": "书", "is_correct": false, "explanation": "shū 与 shuō 韵母不同（少了 o），意思是书。"}, {"text": "树", "is_correct": false, "explanation": "shù（第四声）与 shuō（第一声）韵母与声调都不同，意思是树。"}], "explanations": {"说": "正确：“说”读 shuō（第一声），意思是用话语表达。", "桌": "zhuō 与 shuō 声母不同（zh 与 sh），意思是桌子。", "书": "shū 与 shuō 韵母不同（少了 o），意思是书。", "树": "shù（第四声）与 shuō（第一声）韵母与声调都不同，意思是树。"}, "sentence_index": null, "correct_answer": "说"}, "level_3": {"options": [{"text": "跑", "is_correct": false, "explanation": "配价：“跑”是不及物动词，不能带小句宾语，无法接“他明天不能来开会”。"}, {"text": "说", "is_correct": true, "explanation": "正确：“说”表示用话语表达，与“他明天不能来开会”的内容相符。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要求食物作宾语，不能引出一个小句。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指用声音演唱，无法表达“他明天不能来开会”的内容。"}], "explanations": {"跑": "配价：“跑”是不及物动词，不能带小句宾语，无法接“他明天不能来开会”。", "说": "正确：“说”表示用话语表达，与“他明天不能来开会”的内容相符。", "吃": "配价：“吃”要求食物作宾语，不能引出一个小句。", "唱": "语义：“唱”指用声音演唱，无法表达“他明天不能来开会”的内容。"}, "sentence_index": 0, "correct_answer": "说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用点头说同意，大家都笑了。", "explanation": "这里应该用〈表示〉。“说”指用语言讲，用点头表达意思要用“表示”。"}, {"text": "她用画说了心里的感情。", "explanation": "这里应该用〈表达〉。“说”只用于口头讲出，用画表达感情要用“表达”。"}, {"text": "她在说歌，声音很好听。", "explanation": "这里应该用〈唱〉。“说”是用语言讲话，唱歌要用“唱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19862, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "说", "is_correct": true, "explanation": "正确：“说”读 shuō（第一声），意思是用话语表达。"}, {"text": "叔", "is_correct": false, "explanation": "shū（第一声）与 shuō（第一声）只差韵母末尾的 o，意思是叔叔。"}, {"text": "桌", "is_correct": false, "explanation": "zhuō 与 shuō 声母不同（zh 与 sh），意思是桌子。"}, {"text": "数", "is_correct": false, "explanation": "shǔ（第三声）与 shuō（第一声）韵母与声调都不同，意思是数数。"}], "explanations": {"说": "正确：“说”读 shuō（第一声），意思是用话语表达。", "叔": "shū（第一声）与 shuō（第一声）只差韵母末尾的 o，意思是叔叔。", "桌": "zhuō 与 shuō 声母不同（zh 与 sh），意思是桌子。", "数": "shǔ（第三声）与 shuō（第一声）韵母与声调都不同，意思是数数。"}, "sentence_index": null, "correct_answer": "说"}, "level_3": {"options": [{"text": "喜欢", "is_correct": false, "explanation": "体貌：“喜欢”是状态动词，不能用“……着……着”表示持续动作。"}, {"text": "说", "is_correct": true, "explanation": "正确：“说着说着”表示边说边做某事，与句意相符。"}, {"text": "知道", "is_correct": false, "explanation": "体貌：“知道”是状态动词，不能说“知道着知道着”。"}, {"text": "姓", "is_correct": false, "explanation": "配价：“姓”后要接姓氏，“姓着姓着”不能表示这个意思。"}], "explanations": {"喜欢": "体貌：“喜欢”是状态动词，不能用“……着……着”表示持续动作。", "说": "正确：“说着说着”表示边说边做某事，与句意相符。", "知道": "体貌：“知道”是状态动词，不能说“知道着知道着”。", "姓": "配价：“姓”后要接姓氏，“姓着姓着”不能表示这个意思。"}, "sentence_index": 6, "correct_answer": "说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给朋友说了一封信。", "explanation": "这里应该用〈写〉。“说”是用语言讲，写信要用“写”。"}, {"text": "他在认真说地板，每个角落都很干净。", "explanation": "这里应该用〈擦〉。“说”是用语言讲，把地板弄干净要用“擦”。"}, {"text": "他每天说绳，身体很好。", "explanation": "这里应该用〈跳〉。“说”是用语言讲，跳绳要用“跳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想对妈妈说一个辛苦了。", "corrected_sentence": "我想对妈妈说一句辛苦了。", "error_description": "量词误用：说的话应用量词“句”，不能用“个”；正确为“说一句辛苦了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说地很好，大家都很喜欢听。", "corrected_sentence": "他说得很好，大家都很喜欢听。", "error_description": "补语前应用“得”，不能用“地”；“地”用在动词前作状语，“说得很好”中“得”引出补语“很好”，应说“说得很好”，不能说“说地很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19863, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "真话", "is_correct": true, "explanation": "“真话”与“假话”构成反义，指真实的言语。"}, {"text": "书", "is_correct": false, "explanation": "“书”指书籍，与“假话”没有反义关系。"}, {"text": "车", "is_correct": false, "explanation": "“车”指交通工具，与“假话”没有反义关系。"}, {"text": "花", "is_correct": false, "explanation": "“花”指植物，与“假话”没有反义关系。"}], "correct_answer": "真话", "explanations": {"真话": "“真话”与“假话”构成反义，指真实的言语。", "书": "“书”指书籍，与“假话”没有反义关系。", "车": "“车”指交通工具，与“假话”没有反义关系。", "花": "“花”指植物，与“假话”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19863, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "实话", "is_correct": true, "explanation": "“实话”与“假话”构成反义，指真实的言语。"}, {"text": "石头", "is_correct": false, "explanation": "“石头”指矿物，与“假话”没有反义关系。"}, {"text": "山", "is_correct": false, "explanation": "“山”指地形，与“假话”没有反义关系。"}, {"text": "鱼", "is_correct": false, "explanation": "“鱼”指动物，与“假话”没有反义关系。"}], "correct_answer": "实话", "explanations": {"实话": "“实话”与“假话”构成反义，指真实的言语。", "石头": "“石头”指矿物，与“假话”没有反义关系。", "山": "“山”指地形，与“假话”没有反义关系。", "鱼": "“鱼”指动物，与“假话”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19863, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指不真实、虚假的言语，即谎言。", "primary_collocate": null, "pronunciation": "jiǎ huà", "ipa": "tɕja˨˩ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "他说假话的时候，不敢看我的眼睛。", "target_word": "假话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，小孩子不应该说假话。", "target_word": "假话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她听出来这是一句假话。", "target_word": "假话", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "假话说多了，就没有人再相信你。", "target_word": "假话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他怕妈妈生气，就对她说了假话。", "target_word": "假话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子从来不说假话，大家都喜欢他。", "target_word": "假话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你别听他的，他说的全是假话。", "target_word": "假话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友之间应该说真话，不要说假话。", "target_word": "假话", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他为了面子，在会上说了一句假话，后来很后悔。", "target_word": "假话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官问他是不是在说假话，他低下了头。", "target_word": "假话", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一句假话", "label": "量词"}, {"form": "假話", "label": "繁体"}], "register": "口语", "sense_fingerprint": "不真实的话，谎言", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb066d7-2d45-41ad-9000-ae004e838c44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19863, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "假话", "is_correct": true, "explanation": "正确答案。“假话”读 jiǎ huà，指不真实的言语，即本词。"}, {"text": "傻话", "is_correct": false, "explanation": "shǎ（傻）与 jiǎ 声母不同（sh 与 j），意思是糊涂的话。"}, {"text": "讲话", "is_correct": false, "explanation": "jiǎng（讲）与 jiǎ 只差韵尾 ng，意思是说话。"}, {"text": "假花", "is_correct": false, "explanation": "huā（花）与 huà 声调不同（第一声与第四声），意思是假的花。"}], "explanations": {"假话": "正确答案。“假话”读 jiǎ huà，指不真实的言语，即本词。", "傻话": "shǎ（傻）与 jiǎ 声母不同（sh 与 j），意思是糊涂的话。", "讲话": "jiǎng（讲）与 jiǎ 只差韵尾 ng，意思是说话。", "假花": "huā（花）与 huà 声调不同（第一声与第四声），意思是假的花。"}, "sentence_index": null, "correct_answer": "假话"}, "level_3": {"options": [{"text": "假话", "is_correct": true, "explanation": "“假话”指虚假的言语，可以被“说”，句意通顺。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“说”不搭配“歌”，唱歌才用“唱”，句子不通。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“饭”指食物，不能用“说”来表示，句子不通。"}, {"text": "菜", "is_correct": false, "explanation": "语义：“菜”指食物，不能用“说”来表示，句子不通。"}], "explanations": {"假话": "“假话”指虚假的言语，可以被“说”，句意通顺。", "歌": "搭配：“说”不搭配“歌”，唱歌才用“唱”，句子不通。", "饭": "语义：“饭”指食物，不能用“说”来表示，句子不通。", "菜": "语义：“菜”指食物，不能用“说”来表示，句子不通。"}, "sentence_index": 0, "correct_answer": "假话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店卖的假话很多，买的时候要小心。", "explanation": "这里应该用〈假货〉。“假话”指虚假的言语，不能指卖的商品，要说“假货”。"}, {"text": "他每天早上都吃两碗假话。", "explanation": "这里应该用〈饭〉。“假话”指虚假的言语，不能吃。"}, {"text": "这个消息很假话，你别信。", "explanation": "这里应该用形容词〈虚假〉。“假话”是名词，指虚假的言语，不能直接作谓语形容消息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19863, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "假话", "is_correct": true, "explanation": "“假话”指虚假的言语，与“全是”搭配，句意通顺。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，不能作为“说”的内容，句子不通。"}, {"text": "车", "is_correct": false, "explanation": "语义：“车”指交通工具，不能用来说话，句子不通。"}, {"text": "树", "is_correct": false, "explanation": "语义：“树”指植物，不能作为“说”的内容，句子不通。"}], "explanations": {"假话": "“假话”指虚假的言语，与“全是”搭配，句意通顺。", "桌子": "语义：“桌子”是家具，不能作为“说”的内容，句子不通。", "车": "语义：“车”指交通工具，不能用来说话，句子不通。", "树": "语义：“树”指植物，不能作为“说”的内容，句子不通。"}, "sentence_index": 6, "correct_answer": "假话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂专门生产假话，销往各地。", "explanation": "这里应该用〈假货〉。“假话”指虚假的言语，不能指生产的商品，要说“假货”。"}, {"text": "她把假话放进冰箱里了。", "explanation": "这里应该用〈剩菜〉。“假话”指虚假的言语，不能放进冰箱。"}, {"text": "他很假话，大家都不喜欢他。", "explanation": "这里应该用形容词〈虚伪〉。“假话”是名词，指虚假的言语，不能作谓语评价人的性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19863, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这个人从来不假话。", "corrected_sentence": "他这个人从来不说假话。", "error_description": "缺少动词：“假话”是名词，不能直接受“不”否定，应说“不说假话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19863, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候说过一块假话。", "corrected_sentence": "他小时候说过一句假话。", "error_description": "量词错误：“假话”以“句”计量，“块”用于块状物，不能用于话语，应说“一句假话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
