INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19865, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用眼睛观察或阅读。", "primary_collocate": null, "pronunciation": "kàn", "ipa": "kʰan˥˩", "syllable_count": 1, "sentences": [{"text": "我每天晚上看一个小时的书。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸早上喝茶，看报纸。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生仔细看了看他的眼睛。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在地铁上看着手机里的新闻。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们先看课文，再回答问题。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书我已经看过两遍了。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看地图，找去公园的路。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈正在看孩子写的作文。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人看了看机器，说没有问题。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先看说明书，再用这台机器。", "target_word": "看", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看了", "label": "完成体"}, {"form": "看过", "label": "经历体"}, {"form": "看着", "label": "持续体"}, {"form": "看看", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用眼睛阅读文字或仔细观察", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 说明书 (Zipf 3.81), 再用 (Zipf 3.69), 这台 (Zipf 3.53)']::text[], 'c06c8ddc-088c-4454-b9ef-23726f1668db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19865, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "看", "is_correct": true, "explanation": "正确答案：看 kàn，表示用眼睛阅读文字或仔细观察。"}, {"text": "砍", "is_correct": false, "explanation": "砍 kǎn（第三声）与 kàn（第四声）声调不同，意思是用刀斧砍伐。"}, {"text": "抗", "is_correct": false, "explanation": "抗 kàng 与 kàn 韵母不同（ang 与 an），意思是抵抗。"}, {"text": "刊", "is_correct": false, "explanation": "刊 kān（第一声）与 kàn（第四声）声调不同，意思是刊登、刊物。"}], "explanations": {"看": "正确答案：看 kàn，表示用眼睛阅读文字或仔细观察。", "砍": "砍 kǎn（第三声）与 kàn（第四声）声调不同，意思是用刀斧砍伐。", "抗": "抗 kàng 与 kàn 韵母不同（ang 与 an），意思是抵抗。", "刊": "刊 kān（第一声）与 kàn（第四声）声调不同，意思是刊登、刊物。"}, "sentence_index": null, "correct_answer": "看"}, "level_3": {"options": [{"text": "看", "is_correct": true, "explanation": "正确：“看”表示阅读，符合“看一个小时的书”的句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与“书”无关，读起来不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象一般是歌曲，不能说“唱书”。"}, {"text": "拔", "is_correct": false, "explanation": "语义：“拔”表示拔出，与阅读的行为不符。"}], "explanations": {"看": "正确：“看”表示阅读，符合“看一个小时的书”的句意。", "吃": "语义：“吃”指进食，与“书”无关，读起来不通。", "唱": "搭配：“唱”的对象一般是歌曲，不能说“唱书”。", "拔": "语义：“拔”表示拔出，与阅读的行为不符。"}, "sentence_index": 0, "correct_answer": "看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天看广播里的新闻。", "explanation": "这里应该用〈听〉。广播是用耳朵接收的，用“看”不对。"}, {"text": "你先看一下汤的味道，再决定要不要加盐。", "explanation": "这里应该用〈尝〉。“看”用眼睛，判断味道要用舌头，应说“尝一下汤的味道”。"}, {"text": "我用手看了看桌子的温度。", "explanation": "这里应该用〈感觉〉。“看”用眼睛，“温度”要靠皮肤感受，应说“用手感觉桌子的温度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19865, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "看", "is_correct": true, "explanation": "正确答案：看 kàn，表示用眼睛阅读文字或仔细观察。"}, {"text": "坎", "is_correct": false, "explanation": "坎 kǎn（第三声）与 kàn（第四声）声调不同，意思是坑、坎坷。"}, {"text": "叹", "is_correct": false, "explanation": "叹 tàn 与 kàn 声母不同（t 与 k），意思是叹息。"}, {"text": "侃", "is_correct": false, "explanation": "侃 kǎn（第三声）与 kàn（第四声）声调不同，意思是闲谈。"}], "explanations": {"看": "正确答案：看 kàn，表示用眼睛阅读文字或仔细观察。", "坎": "坎 kǎn（第三声）与 kàn（第四声）声调不同，意思是坑、坎坷。", "叹": "叹 tàn 与 kàn 声母不同（t 与 k），意思是叹息。", "侃": "侃 kǎn（第三声）与 kàn（第四声）声调不同，意思是闲谈。"}, "sentence_index": null, "correct_answer": "看"}, "level_3": {"options": [{"text": "看", "is_correct": true, "explanation": "正确：“看”表示查看地图，符合找路的语境。"}, {"text": "听", "is_correct": false, "explanation": "搭配：“听”的对象是声音，不能用于地图。"}, {"text": "闻", "is_correct": false, "explanation": "搭配：“闻”用于气味，不能用于地图。"}, {"text": "吞", "is_correct": false, "explanation": "语义：“吞”表示咽下，与查看地图找路的情境不符。"}], "explanations": {"看": "正确：“看”表示查看地图，符合找路的语境。", "听": "搭配：“听”的对象是声音，不能用于地图。", "闻": "搭配：“闻”用于气味，不能用于地图。", "吞": "语义：“吞”表示咽下，与查看地图找路的情境不符。"}, "sentence_index": 6, "correct_answer": "看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用手看了看孩子的额头。", "explanation": "这里应该用〈摸〉。“看”要用眼睛，用手接触要用〈摸〉。"}, {"text": "妈妈在厨房里看一下饭香。", "explanation": "这里应该用〈闻〉。“看”用眼睛，“饭香”要用鼻子感受，应说“闻一闻饭香”。"}, {"text": "他看了一口茶。", "explanation": "这里应该用〈喝〉。“看”用眼睛，“一口茶”要用嘴喝，应说“喝了一口茶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19865, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天晚上看了着一个小时的漫画。", "corrected_sentence": "我每天晚上看一个小时的漫画。", "error_description": "错误在于“看”后多加了“了着”。“了”表示完成，“着”表示持续，两者不能同时用在“看”上。正确说法是“看一个小时的漫画”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19865, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他看清楚的地图，找回家的路。", "corrected_sentence": "他看清楚了地图，找回家的路。", "error_description": "错误在于“了”写成了“的”。“看清楚了地图”中“了”表示动作已完成，不能用“的”；正确说法是“看清楚了地图”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
