INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19867, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示事情发生或结束得早，或强调事情刚刚发生。", "primary_collocate": null, "pronunciation": "cái", "ipa": "tsʰaɪ̯˧˥", "syllable_count": 1, "sentences": [{"text": "我才到家，雨就下起来了。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他才吃完饭，朋友就来了。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈才出门，电话就响了。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们才认识一个月，他就搬走了。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影才开始，她就睡着了。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她才买的新手机，今天就丢了。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师才说完，学生们就笑了。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我才洗完澡，又出汗了。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟才起床，就问有没有早饭。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他才进门，手机就响了。", "target_word": "才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "才+动作，强调刚刚发生，后面常接就", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 洗完 (Zipf 3.05), 澡 (Zipf 3.68), 出汗 (Zipf 3.34)']::text[], 'c06c8ddc-088c-4454-b9ef-23726f1668db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19867, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "才", "is_correct": true, "explanation": "正确答案：才 cái，强调事情刚刚发生。"}, {"text": "菜", "is_correct": false, "explanation": "菜 cài（第四声）与 cái（第二声）声调不同，意思是菜肴。"}, {"text": "彩", "is_correct": false, "explanation": "彩 cǎi（第三声）与 cái（第二声）声调不同，意思是颜色、彩色。"}, {"text": "猜", "is_correct": false, "explanation": "猜 cāi（第一声）与 cái（第二声）声调不同，意思是猜测。"}, {"text": "来", "is_correct": false, "explanation": "来 lái 与 cái 声母不同（l 与 c），意思是来到。"}], "explanations": {"才": "正确答案：才 cái，强调事情刚刚发生。", "菜": "菜 cài（第四声）与 cái（第二声）声调不同，意思是菜肴。", "彩": "彩 cǎi（第三声）与 cái（第二声）声调不同，意思是颜色、彩色。", "猜": "猜 cāi（第一声）与 cái（第二声）声调不同，意思是猜测。", "来": "来 lái 与 cái 声母不同（l 与 c），意思是来到。"}, "sentence_index": null, "correct_answer": "才"}, "level_3": {"options": [{"text": "才", "is_correct": true, "explanation": "正确：“才”强调刚刚到家，符合“雨就下起来了”的语境。"}, {"text": "正", "is_correct": false, "explanation": "体貌：“正”表示动作正在进行，与“到家”这种瞬间完成的动作矛盾。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，句中没有前后对立的意思，读起来不通。"}, {"text": "又", "is_correct": false, "explanation": "语义：“又”表示重复，句中没有先前到家的情况，与“刚刚到家”的意思不符。"}], "explanations": {"才": "正确：“才”强调刚刚到家，符合“雨就下起来了”的语境。", "正": "体貌：“正”表示动作正在进行，与“到家”这种瞬间完成的动作矛盾。", "却": "语义：“却”表示转折，句中没有前后对立的意思，读起来不通。", "又": "语义：“又”表示重复，句中没有先前到家的情况，与“刚刚到家”的意思不符。"}, "sentence_index": 0, "correct_answer": "才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我等了他两个小时，他才来。", "explanation": "这里的“才”表示事情发生得晚（等了很久），不是“刚刚发生”的意思。"}, {"text": "这个苹果才两块钱，很便宜。", "explanation": "这里的“才”表示“仅仅”（数量少），不是“刚刚发生”的意思。"}, {"text": "他想了三个小时，才想出办法。", "explanation": "这里的“才”表示事情发生得晚（耗时长），与“早或快”的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19867, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "才", "is_correct": true, "explanation": "正确答案：才 cái，强调事情刚刚发生。"}, {"text": "采", "is_correct": false, "explanation": "采 cǎi（第三声）与 cái（第二声）声调不同，意思是采摘。"}, {"text": "踩", "is_correct": false, "explanation": "踩 cǎi（第三声）与 cái（第二声）声调不同，意思是脚下用力按压。"}, {"text": "柴", "is_correct": false, "explanation": "柴 chái 与 cái 声母不同（ch 与 c），意思是柴火。"}], "explanations": {"才": "正确答案：才 cái，强调事情刚刚发生。", "采": "采 cǎi（第三声）与 cái（第二声）声调不同，意思是采摘。", "踩": "踩 cǎi（第三声）与 cái（第二声）声调不同，意思是脚下用力按压。", "柴": "柴 chái 与 cái 声母不同（ch 与 c），意思是柴火。"}, "sentence_index": null, "correct_answer": "才"}, "level_3": {"options": [{"text": "才", "is_correct": true, "explanation": "正确：“才”强调老师刚说完，学生就笑了，符合句意。"}, {"text": "始终", "is_correct": false, "explanation": "体貌：“始终”表示一直持续，与“说完”的结束义矛盾。"}, {"text": "一直", "is_correct": false, "explanation": "体貌：“一直”表示持续不断，与“说完”的结束义矛盾。"}, {"text": "竟", "is_correct": false, "explanation": "语义：“竟”表示出乎意料，句中没有出乎意料的意思，读起来不通。"}], "explanations": {"才": "正确：“才”强调老师刚说完，学生就笑了，符合句意。", "始终": "体貌：“始终”表示一直持续，与“说完”的结束义矛盾。", "一直": "体貌：“一直”表示持续不断，与“说完”的结束义矛盾。", "竟": "语义：“竟”表示出乎意料，句中没有出乎意料的意思，读起来不通。"}, "sentence_index": 6, "correct_answer": "才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书才十块钱，我买了三本。", "explanation": "这里的“才”表示“仅仅”（数量少），不是事情发生得早或快。"}, {"text": "我才不怕他，还留在这里等他。", "explanation": "这里的“才不”是强调否定的语气，表示坚决不怕，不表示事情发生得早或快。"}, {"text": "你说的才对，我说错了。", "explanation": "这里的“才”用来强调肯定的语气，不表示事情刚刚发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19867, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下才车，雨就下起来了。", "corrected_sentence": "我才下车，雨就下起来了。", "error_description": "错误在于“才”的位置。“才”插在离合词“下车”中间，不通。“才”应放在整个动词前面，强调刚刚发生，写作“我才下车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19867, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹写才完作业，就跑出去玩了。", "corrected_sentence": "妹妹才写完作业，就跑出去玩了。", "error_description": "错误在于“才”的位置。“才”插在“写”和“完”之间，拆开了结果补语“写完”，不通。正确说法是“妹妹才写完作业，就跑出去玩了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ffe4f77-182f-438f-8c01-903bcfaf66b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
