INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19873, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指用户输入账号和密码以进入计算机系统、网站或应用程序的过程。", "primary_collocate": null, "pronunciation": "dēng lù", "ipa": "təŋ⁵⁵ lu⁵¹", "syllable_count": 2, "sentences": [{"text": "为什么不让那个人登录？", "target_word": "登录", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "我忘了密码，不能登录。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先输入账号，再登录。", "target_word": "登录", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天早上都登录邮箱。", "target_word": "登录", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个网站要先登录才能买东西。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你用手机号码就可以登录。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的电脑登录不了学校的网站。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "登录以后，你能看到自己的信息。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她正在登录银行的手机软件。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "密码错了三次，他就不能再登录了。", "target_word": "登录", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "登录了", "label": "体标"}, {"form": "登录过", "label": "体标"}, {"form": "登录名", "label": "复合"}, {"form": "登录密码", "label": "复合"}, {"form": "登錄", "label": "繁体"}], "register": "中性", "sense_fingerprint": "输入账号和密码，进入电脑系统、网站或应用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fa5d8e-2296-45e3-ab90-df9c0be39312') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19873, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "登录", "is_correct": true, "explanation": "正确：“登录”指输入账号和密码进入系统，句中“不让那个人登录”即不让他进入系统。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：“生锈”是金属氧化的结果，人不会生锈，“不让那个人生锈”句意荒谬。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：“凝固”指液体变稠变硬，不用于人，“不让那个人凝固”句意荒谬。"}, {"text": "发电", "is_correct": false, "explanation": "语义：“发电”是设备或电站的功能，人不能发电，“不让那个人发电”句意荒谬。"}], "explanations": {"登录": "正确：“登录”指输入账号和密码进入系统，句中“不让那个人登录”即不让他进入系统。", "生锈": "语义：“生锈”是金属氧化的结果，人不会生锈，“不让那个人生锈”句意荒谬。", "凝固": "语义：“凝固”指液体变稠变硬，不用于人，“不让那个人凝固”句意荒谬。", "发电": "语义：“发电”是设备或电站的功能，人不能发电，“不让那个人发电”句意荒谬。"}, "sentence_index": 0, "correct_answer": "登录"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都登录公司。", "explanation": "这里应该用〈进入〉。“登录”指输入账号和密码进入网站或系统，不能用来说走进公司这样的实体场所。"}, {"text": "台风昨天晚上登录了上海。", "explanation": "这里应该用〈登陆〉。“登陆”指台风、军队等从海上到达陆地，与“登录”同音；“登录”指输入账号和密码进入网站或系统。"}, {"text": "宇航员终于登录了月球。", "explanation": "这里应该用〈登上〉。“登上”指到达某处，宇航员登上月球；“登录”指输入账号和密码进入网站或系统，不能用于月球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19873, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "登录", "is_correct": true, "explanation": "正确：“登录”能与“不了”搭配，表示无法进入学校的网站，句意通顺。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”指在户外行走，电脑不能散步，“散步不了学校的网站”句意荒谬。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：“结婚”的主体是人，电脑不能结婚，句子与常识冲突。"}, {"text": "驾临", "is_correct": false, "explanation": "语域：“驾临”是敬辞，只用于尊贵的客人到访，用在“我的电脑”这类语境中语域不合。"}], "explanations": {"登录": "正确：“登录”能与“不了”搭配，表示无法进入学校的网站，句意通顺。", "散步": "语义：“散步”指在户外行走，电脑不能散步，“散步不了学校的网站”句意荒谬。", "结婚": "语义：“结婚”的主体是人，电脑不能结婚，句子与常识冲突。", "驾临": "语域：“驾临”是敬辞，只用于尊贵的客人到访，用在“我的电脑”这类语境中语域不合。"}, "sentence_index": 6, "correct_answer": "登录"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她们明天去登录，看日出。", "explanation": "这里应该用〈登山〉。“登山”指攀登山峰，“登录”指输入账号进入系统，不能用于爬山。"}, {"text": "他登录了那个文件。", "explanation": "这里应该用〈打开〉。“登录”用于进入网站或系统，文件要用“打开”，不能说“登录文件”。"}, {"text": "他终于登录了珠峰，大家都为他鼓掌。", "explanation": "这里应该用〈登顶〉。“登顶”指攀登到山顶，“登录”指输入账号进入系统，不能用于山峰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19873, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他顺利登录了了系统。", "corrected_sentence": "他顺利登录了系统。", "error_description": "错误：“了”重复。“登录”后只需一个“了”，应为“登录了系统”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19873, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每天都把登录学习平台。", "corrected_sentence": "我每天都登录学习平台。", "error_description": "错误：多出“把”。“把”字句需要“把+名词+动词”结构，“把登录学习平台”不成立，应删去“把”，为“我每天都登录学习平台。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19874, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无", "is_correct": true, "explanation": "无：与“有”（具有某种性质）相对，表示不具备。"}, {"text": "跑", "is_correct": false, "explanation": "跑：动词，表示奔跑，与“有”（具有）没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱：动词，表示歌唱，与“有”（具有）没有反义关系。"}, {"text": "吃", "is_correct": false, "explanation": "吃：动词，表示进食，与“有”（具有）没有反义关系。"}], "correct_answer": "无", "explanations": {"无": "无：与“有”（具有某种性质）相对，表示不具备。", "跑": "跑：动词，表示奔跑，与“有”（具有）没有反义关系。", "唱": "唱：动词，表示歌唱，与“有”（具有）没有反义关系。", "吃": "吃：动词，表示进食，与“有”（具有）没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19874, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无", "is_correct": true, "explanation": "无：与“有”（具有某种性质）相对，表示不具备。"}, {"text": "看", "is_correct": false, "explanation": "看：动词，表示观看，与“有”（具有）没有反义关系。"}, {"text": "走", "is_correct": false, "explanation": "走：动词，表示行走，与“有”（具有）没有反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "笑：动词，表示发笑，与“有”（具有）没有反义关系。"}], "correct_answer": "无", "explanations": {"无": "无：与“有”（具有某种性质）相对，表示不具备。", "看": "看：动词，表示观看，与“有”（具有）没有反义关系。", "走": "走：动词，表示行走，与“有”（具有）没有反义关系。", "笑": "笑：动词，表示发笑，与“有”（具有）没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19874, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "表示领有、具有，与“无”相对。", "primary_collocate": null, "pronunciation": "yǒu", "ipa": "jou̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "他有耐心，从不生气。", "target_word": "有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学汉语要有信心。", "target_word": "有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她当老师多年，很有经验。", "target_word": "有", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子有音乐才能。", "target_word": "有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这道题我有把握做对。", "target_word": "有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很有勇气，敢说真话。", "target_word": "有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "多喝水对身体有好处。", "target_word": "有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你说得有道理，我同意。", "target_word": "有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "当班长就要有责任心。", "target_word": "有", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她有能力做好这件事。", "target_word": "有", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "没有", "label": "否定式"}, {"form": "有过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词，表示具有某种性质、能力或情感，如有耐心、有信心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06ef7b24-878b-4d84-b099-4f00efa873d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19874, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有", "is_correct": true, "explanation": "有（yǒu）：表示具有某种性质、能力或情感，即本题的正确答案。"}, {"text": "由", "is_correct": false, "explanation": "由（yóu，第二声）与有（yǒu，第三声）声调不同，意思是“由于，经由”。"}, {"text": "柚", "is_correct": false, "explanation": "柚（yòu，第四声）与有（yǒu，第三声）声调不同，意思是“柚子”。"}, {"text": "诱", "is_correct": false, "explanation": "诱（yòu，第四声）与有（yǒu，第三声）声调不同，意思是“引诱”。"}, {"text": "优", "is_correct": false, "explanation": "优（yōu，第一声）与有（yǒu，第三声）声调不同，意思是“优秀”。"}], "explanations": {"有": "有（yǒu）：表示具有某种性质、能力或情感，即本题的正确答案。", "由": "由（yóu，第二声）与有（yǒu，第三声）声调不同，意思是“由于，经由”。", "柚": "柚（yòu，第四声）与有（yǒu，第三声）声调不同，意思是“柚子”。", "诱": "诱（yòu，第四声）与有（yǒu，第三声）声调不同，意思是“引诱”。", "优": "优（yōu，第一声）与有（yǒu，第三声）声调不同，意思是“优秀”。"}, "sentence_index": null, "correct_answer": "有"}, "level_3": {"options": [{"text": "有", "is_correct": true, "explanation": "有：表示具有，与“耐心”搭配，符合“从不生气”的性格描述。"}, {"text": "失去", "is_correct": false, "explanation": "语义：“失去”表示丧失，与“从不生气”的性格描述相矛盾。"}, {"text": "放弃", "is_correct": false, "explanation": "搭配：“放弃”多与理想、机会等搭配，一般不说放弃耐心。"}, {"text": "耗尽", "is_correct": false, "explanation": "语义：“耗尽”表示用完，耐心耗尽常会引起发火，与“从不生气”矛盾。"}], "explanations": {"有": "有：表示具有，与“耐心”搭配，符合“从不生气”的性格描述。", "失去": "语义：“失去”表示丧失，与“从不生气”的性格描述相矛盾。", "放弃": "搭配：“放弃”多与理想、机会等搭配，一般不说放弃耐心。", "耗尽": "语义：“耗尽”表示用完，耐心耗尽常会引起发火，与“从不生气”矛盾。"}, "sentence_index": 0, "correct_answer": "有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天有了一个澡。", "explanation": "这里应该用〈洗〉。“有”表示领有或具有，不能表示洗澡这个动作；应说“我今天洗了一个澡”。"}, {"text": "今天有星期六。", "explanation": "这里应该用〈是〉。“有”表示领有或具有，不能用来说明今天是星期几。"}, {"text": "她有了三年班长。", "explanation": "这里应该用〈当〉。“当”表示担任职务，“有”不能用来说担任班长的经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19874, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "有", "is_correct": true, "explanation": "有（yǒu）：表示具有某种性质、能力或情感，即本题的正确答案。"}, {"text": "油", "is_correct": false, "explanation": "油（yóu，第二声）与有（yǒu，第三声）声调不同，意思是“油脂”。"}, {"text": "右", "is_correct": false, "explanation": "右（yòu，第四声）与有（yǒu，第三声）声调不同，意思是“右边”。"}, {"text": "忧", "is_correct": false, "explanation": "忧（yōu，第一声）与有（yǒu，第三声）声调不同，意思是“忧愁”。"}, {"text": "咬", "is_correct": false, "explanation": "咬（yǎo）与有（yǒu）韵母不同（ao 与 ou），声调相同，意思是“咬”。"}], "explanations": {"有": "有（yǒu）：表示具有某种性质、能力或情感，即本题的正确答案。", "油": "油（yóu，第二声）与有（yǒu，第三声）声调不同，意思是“油脂”。", "右": "右（yòu，第四声）与有（yǒu，第三声）声调不同，意思是“右边”。", "忧": "忧（yōu，第一声）与有（yǒu，第三声）声调不同，意思是“忧愁”。", "咬": "咬（yǎo）与有（yǒu）韵母不同（ao 与 ou），声调相同，意思是“咬”。"}, "sentence_index": null, "correct_answer": "有"}, "level_3": {"options": [{"text": "有", "is_correct": true, "explanation": "有：表示具有，与“好处”搭配，符合“多喝水对身体有好处”的常识。"}, {"text": "减少", "is_correct": false, "explanation": "语义：“减少”表示缩减，“减少好处”与“多喝水对身体”的积极语境相反。"}, {"text": "丧失", "is_correct": false, "explanation": "语义：“丧失”表示失去，“对身体丧失好处”与前文的积极语境矛盾。"}, {"text": "做", "is_correct": false, "explanation": "搭配：“做”不能与“好处”搭配，“对身体做好处”不通。"}], "explanations": {"有": "有：表示具有，与“好处”搭配，符合“多喝水对身体有好处”的常识。", "减少": "语义：“减少”表示缩减，“减少好处”与“多喝水对身体”的积极语境相反。", "丧失": "语义：“丧失”表示失去，“对身体丧失好处”与前文的积极语境矛盾。", "做": "搭配：“做”不能与“好处”搭配，“对身体做好处”不通。"}, "sentence_index": 6, "correct_answer": "有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三乘二有六。", "explanation": "这里应该用〈等于〉。“有”表示领有或具有，不能用来表示算式的结果；应说“三乘二等于六”。"}, {"text": "我家有北京。", "explanation": "这里应该用〈在〉。“在”表示位置，“有”表示领有，不能说家在某个地方。"}, {"text": "这只猫有咪咪。", "explanation": "这里应该用〈叫〉。“叫”用于说明名字，“有”不能用来表示猫的名字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不有责任心。", "corrected_sentence": "他没有责任心。", "error_description": "错误：“他不有责任心”。正确：“他没有责任心”。“有”的否定要用“没有”，不能用“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有很能力做好这件事。", "corrected_sentence": "她很有能力做好这件事。", "error_description": "错误：“她有很能力”。正确：“她很有能力”。“很”应放在“有”之前，构成“很有能力”，不能放在“有”和“能力”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19875, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "义务", "is_correct": true, "explanation": "正确：“权利”指可以做的事，“义务”指必须做的事，二者构成反义关系。"}, {"text": "房间", "is_correct": false, "explanation": "与“权利”没有反义关系，二者不是对立的概念。"}, {"text": "天气", "is_correct": false, "explanation": "与“权利”没有反义关系，二者语义无对立。"}, {"text": "学校", "is_correct": false, "explanation": "与“权利”没有反义关系，二者不构成对立。"}], "correct_answer": "义务", "explanations": {"义务": "正确：“权利”指可以做的事，“义务”指必须做的事，二者构成反义关系。", "房间": "与“权利”没有反义关系，二者不是对立的概念。", "天气": "与“权利”没有反义关系，二者语义无对立。", "学校": "与“权利”没有反义关系，二者不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19875, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "义务", "is_correct": true, "explanation": "正确：“权利”与“义务”是一对反义词，分别指可以做的事和必须做的事。"}, {"text": "桌子", "is_correct": false, "explanation": "与“权利”没有反义关系，二者不构成对立。"}, {"text": "汽车", "is_correct": false, "explanation": "与“权利”没有反义关系，二者语义无对立。"}, {"text": "公园", "is_correct": false, "explanation": "与“权利”没有反义关系，二者不构成对立。"}], "correct_answer": "义务", "explanations": {"义务": "正确：“权利”与“义务”是一对反义词，分别指可以做的事和必须做的事。", "桌子": "与“权利”没有反义关系，二者不构成对立。", "汽车": "与“权利”没有反义关系，二者语义无对立。", "公园": "与“权利”没有反义关系，二者不构成对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19875, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指法律或道德上允许人们做某事或拥有某物的资格。", "primary_collocate": null, "pronunciation": "quán lì", "ipa": "tɕʰɥɛn³⁵ li⁵¹", "syllable_count": 2, "sentences": [{"text": "用户有权利知道这些。", "target_word": "权利", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "每个公民都有选举的权利。", "target_word": "权利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子有受教育的权利。", "target_word": "权利", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你没有权利看别人的信。", "target_word": "权利", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "法律保护我们的权利。", "target_word": "权利", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工人有休息的权利。", "target_word": "权利", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买了票的人有权利进去。", "target_word": "权利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他放弃了投票的权利。", "target_word": "权利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板不能不给工人休假，这是工人的权利。", "target_word": "权利", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个人都有说话的权利，请让他说完。", "target_word": "权利", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项权利", "label": "量词"}, {"form": "權利", "label": "繁体"}, {"form": "权利人", "label": "复合"}], "register": "中性", "sense_fingerprint": "法律或道德上允许人做某事、拥有某物的资格（有权利、享有权利、保护权利）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fa5d8e-2296-45e3-ab90-df9c0be39312') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19875, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "权利", "is_correct": true, "explanation": "正确：“用户有权利知道这些”表示法律或道德允许用户知道这些信息，语义通顺。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是物件，“用户有手机知道这些”句意不通，无法表达“知道这些”的资格。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是人可以拥有的东西，与“用户有……知道这些”的语义不合。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”是物件，“用户有房子知道这些”句意不通，无法表达“知道这些”的资格。"}], "explanations": {"权利": "正确：“用户有权利知道这些”表示法律或道德允许用户知道这些信息，语义通顺。", "手机": "语义：“手机”是物件，“用户有手机知道这些”句意不通，无法表达“知道这些”的资格。", "天气": "语义：“天气”不是人可以拥有的东西，与“用户有……知道这些”的语义不合。", "房子": "语义：“房子”是物件，“用户有房子知道这些”句意不通，无法表达“知道这些”的资格。"}, "sentence_index": 0, "correct_answer": "权利"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你有权利遵守学校的规定。", "explanation": "这里应该用〈义务〉。“权利”指法律或道德允许做的事，遵守规定是必须履行的责任，应说“义务”。"}, {"text": "市长有权利任命官员。", "explanation": "这里应该用〈权力〉。“权力”指支配、命令别人的力量，任命官员属于权力；“权利”指法律或道德允许的资格。"}, {"text": "公司今年的权利很高。", "explanation": "这里应该用〈利润〉。“利润”指收入减去成本后的盈余，“权利”指法律或道德允许的资格，不能用来说公司的盈利。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19875, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "权利", "is_correct": true, "explanation": "正确：“买了票的人有权利进去”表示买票者有资格进入，语义通顺。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“饭”不能作为进入场所的资格，“买了票的人有饭进去”句意荒谬。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是可以凭借进入的东西，句意不通。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”不是可以拥有并凭借进入的资格，“有脚步进去”不通。"}], "explanations": {"权利": "正确：“买了票的人有权利进去”表示买票者有资格进入，语义通顺。", "饭": "语义：“饭”不能作为进入场所的资格，“买了票的人有饭进去”句意荒谬。", "颜色": "语义：“颜色”不是可以凭借进入的东西，句意不通。", "脚步": "语义：“脚步”不是可以拥有并凭借进入的资格，“有脚步进去”不通。"}, "sentence_index": 6, "correct_answer": "权利"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的权利很重，压得他喘不过气。", "explanation": "这里应该用〈责任〉。“责任”可以“重”，压得人喘不过气；“权利”不能说“重”。"}, {"text": "他对这件事负有权利。", "explanation": "这里应该用〈责任〉。“负有”后面接“责任”，不能接“权利”。"}, {"text": "他担任了公司的权利。", "explanation": "这里应该用〈职务〉。“担任”的对象是职务、职位，“权利”不能被担任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19875, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他享有一把重要的权利。", "corrected_sentence": "他享有一项重要的权利。", "error_description": "量词错误：“权利”的量词应为“项”，不能用“把”，“把”用于有柄的器具。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19875, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生有提问的权利人，老师应该耐心回答。", "corrected_sentence": "学生有提问的权利，老师应该耐心回答。", "error_description": "复合词误用：“权利人”指权利的持有者，这里表示“权利”本身，应说“提问的权利”，不能用“权利人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
