INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19876, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示总括全部，相当于“全”“完全”。", "primary_collocate": null, "pronunciation": "dōu", "ipa": "tou̯˥", "syllable_count": 1, "sentences": [{"text": "我们班的同学都是中国人。", "target_word": "都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天都跑步。", "target_word": "都", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这些书我都看过。", "target_word": "都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都到了，我们走吧。", "target_word": "都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你说的话我都记着。", "target_word": "都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的水果都很新鲜。", "target_word": "都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们都在公园里玩。", "target_word": "都", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这几个菜我都喜欢吃。", "target_word": "都", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们两个人都没来。", "target_word": "都", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每个人都想去北京。", "target_word": "都", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，总括前面提到的人或事物，表示全部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06ef7b24-878b-4d84-b099-4f00efa873d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19876, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "都", "is_correct": true, "explanation": "都（dōu）：副词，总括全部，即本题的正确答案。"}, {"text": "陡", "is_correct": false, "explanation": "陡（dǒu，第三声）与都（dōu，第一声）声调不同，意思是“陡峭”。"}, {"text": "刀", "is_correct": false, "explanation": "刀（dāo）与都（dōu）韵母不同（ao 与 ou），声调相同，意思是“刀”。"}, {"text": "逗", "is_correct": false, "explanation": "逗（dòu，第四声）与都（dōu，第一声）声调不同，意思是“逗引”。"}, {"text": "偷", "is_correct": false, "explanation": "偷（tōu）与都（dōu）声母不同（t 与 d），声调相同，意思是“偷”。"}], "explanations": {"都": "都（dōu）：副词，总括全部，即本题的正确答案。", "陡": "陡（dǒu，第三声）与都（dōu，第一声）声调不同，意思是“陡峭”。", "刀": "刀（dāo）与都（dōu）韵母不同（ao 与 ou），声调相同，意思是“刀”。", "逗": "逗（dòu，第四声）与都（dōu，第一声）声调不同，意思是“逗引”。", "偷": "偷（tōu）与都（dōu）声母不同（t 与 d），声调相同，意思是“偷”。"}, "sentence_index": null, "correct_answer": "都"}, "level_3": {"options": [{"text": "都", "is_correct": true, "explanation": "都：副词，总括全部，符合“我们班的同学都是中国人”的语境。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示仅仅、限定范围，“我们班的同学只是中国人”与整体陈述不合。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”修饰形容词，不能放在“是＋名词”前，“同学太是中国人”不通。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”不能修饰“是中国人”，“同学很是中国人”不通。"}], "explanations": {"都": "都：副词，总括全部，符合“我们班的同学都是中国人”的语境。", "只": "语义：“只”表示仅仅、限定范围，“我们班的同学只是中国人”与整体陈述不合。", "太": "搭配：“太”修饰形容词，不能放在“是＋名词”前，“同学太是中国人”不通。", "很": "搭配：“很”不能修饰“是中国人”，“同学很是中国人”不通。"}, "sentence_index": 0, "correct_answer": "都"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人都去了北京。", "explanation": "这里应该用〈就〉。“都”表示总括全体，只有一个人时不能用；应说“他一个人就去了北京”。"}, {"text": "她晚上十点都回家。", "explanation": "这里应该用〈才〉。“都”表示全部，不能表示回家得晚；应说“晚上十点才回家”。"}, {"text": "他很早都来了。", "explanation": "这里应该用〈就〉。“就”表示时间早，“都”不能表达这种意思；应说“很早就来了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19876, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "都", "is_correct": true, "explanation": "都（dōu）：副词，总括全部，即本题的正确答案。"}, {"text": "豆", "is_correct": false, "explanation": "豆（dòu，第四声）与都（dōu，第一声）声调不同，意思是“豆子”。"}, {"text": "抖", "is_correct": false, "explanation": "抖（dǒu，第三声）与都（dōu，第一声）声调不同，意思是“抖动”。"}, {"text": "斗", "is_correct": false, "explanation": "斗（dòu，第四声）与都（dōu，第一声）声调不同，意思是“争斗”。"}], "explanations": {"都": "都（dōu）：副词，总括全部，即本题的正确答案。", "豆": "豆（dòu，第四声）与都（dōu，第一声）声调不同，意思是“豆子”。", "抖": "抖（dǒu，第三声）与都（dōu，第一声）声调不同，意思是“抖动”。", "斗": "斗（dòu，第四声）与都（dōu，第一声）声调不同，意思是“争斗”。"}, "sentence_index": null, "correct_answer": "都"}, "level_3": {"options": [{"text": "都", "is_correct": true, "explanation": "都：副词，总括全部，符合“孩子们都在公园里玩”的语境。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”是程度副词，修饰形容词或心理动词，不能修饰“在公园里玩”这类动作短语，“孩子们非常在公园里玩”不通。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”表示程度高，只修饰形容词等，“孩子们十分在公园里玩”不通。"}, {"text": "挺", "is_correct": false, "explanation": "搭配：“挺”是程度副词，常说“挺好”，不能修饰动作短语，“孩子们挺在公园里玩”不通。"}], "explanations": {"都": "都：副词，总括全部，符合“孩子们都在公园里玩”的语境。", "非常": "搭配：“非常”是程度副词，修饰形容词或心理动词，不能修饰“在公园里玩”这类动作短语，“孩子们非常在公园里玩”不通。", "十分": "搭配：“十分”表示程度高，只修饰形容词等，“孩子们十分在公园里玩”不通。", "挺": "搭配：“挺”是程度副词，常说“挺好”，不能修饰动作短语，“孩子们挺在公园里玩”不通。"}, "sentence_index": 6, "correct_answer": "都"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我是学生，他都是学生。", "explanation": "这里应该用〈也〉。“都”总括前面的多个人或事物，“他”只有一个人；表示同样情况要用“也”。"}, {"text": "我喜欢猫，我妹妹都喜欢猫。", "explanation": "这里应该用〈也〉。“我妹妹”只是一个人，不能用“都”总括；表示相同要用“也”。"}, {"text": "这件事只有他一个人都知道。", "explanation": "这里应该用〈才〉。“只有……才”表示唯一条件，“一个人”不能用“都”总括。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们几个人都喜欢都这部电影。", "corrected_sentence": "我们几个人都喜欢这部电影。", "error_description": "错误：“我们几个人都喜欢都这部电影”。正确：“我们几个人都喜欢这部电影”。“都”已放在主语之后、动词之前总括全体，宾语前不能再加“都”，多用了一个“都”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个学生都喜欢这个老师。", "corrected_sentence": "这些学生都喜欢这个老师。", "error_description": "错误：“这个学生都喜欢这个老师”。正确：“这些学生都喜欢这个老师”。“都”总括前面的多个人或事物，主语只有一个学生时不能用“都”，应改为复数的“这些学生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
