INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19878, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，用在动词、形容词前表示否定。", "primary_collocate": null, "pronunciation": "bù", "ipa": "pu˥˩", "syllable_count": 1, "sentences": [{"text": "我不喝咖啡，只喝茶。", "target_word": "不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天很冷，他不出门。", "target_word": "不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个菜不咸，也不酸。", "target_word": "不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不知道他的名字。", "target_word": "不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟不吃肉，只吃菜。", "target_word": "不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她不高，但是跑得很快。", "target_word": "不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不想回家，想再玩一会儿。", "target_word": "不", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不来，我们先开始吧。", "target_word": "不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书不便宜，也不新。", "target_word": "不", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她不懂中文，我们只好写字。", "target_word": "不", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不是", "label": "复合"}, {"form": "不会", "label": "复合"}], "register": "通用", "sense_fingerprint": "不：副词，放在动词或形容词前表示否定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebfe7736-19f5-4660-8550-caa3fb9fd6f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19878, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不", "is_correct": true, "explanation": "正确。“不”（bù，第四声）是否定副词，表示否定。"}, {"text": "度", "is_correct": false, "explanation": "度（dù，第四声）与 bù 声母不同（d 与 b），意思是程度。"}, {"text": "路", "is_correct": false, "explanation": "路（lù，第四声）与 bù 声母不同（l 与 b），意思是道路。"}, {"text": "护", "is_correct": false, "explanation": "护（hù，第四声）与 bù 声母不同（h 与 b），意思是保护。"}, {"text": "故", "is_correct": false, "explanation": "故（gù，第四声）与 bù 声母不同（g 与 b），意思是缘故、旧的。"}], "explanations": {"不": "正确。“不”（bù，第四声）是否定副词，表示否定。", "度": "度（dù，第四声）与 bù 声母不同（d 与 b），意思是程度。", "路": "路（lù，第四声）与 bù 声母不同（l 与 b），意思是道路。", "护": "护（hù，第四声）与 bù 声母不同（h 与 b），意思是保护。", "故": "故（gù，第四声）与 bù 声母不同（g 与 b），意思是缘故、旧的。"}, "sentence_index": null, "correct_answer": "不"}, "level_3": {"options": [{"text": "不", "is_correct": true, "explanation": "正确。“我不喝咖啡”表示否定，与后句“只喝茶”形成对比。"}, {"text": "也", "is_correct": false, "explanation": "语义：“也”表示同样，与“只喝茶”的排他语义矛盾。"}, {"text": "都", "is_correct": false, "explanation": "语义：“都”表示全部，与“只喝茶”的排他语义矛盾。"}, {"text": "又", "is_correct": false, "explanation": "搭配：“又”表示重复，前文没有喝咖啡的情况，此处不合适。"}], "explanations": {"不": "正确。“我不喝咖啡”表示否定，与后句“只喝茶”形成对比。", "也": "语义：“也”表示同样，与“只喝茶”的排他语义矛盾。", "都": "语义：“都”表示全部，与“只喝茶”的排他语义矛盾。", "又": "搭配：“又”表示重复，前文没有喝咖啡的情况，此处不合适。"}, "sentence_index": 0, "correct_answer": "不"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天不去，因为我生病了。", "explanation": "这里应该用〈没〉。〈不〉多表示意愿或习惯，过去没有去的具体事情要用〈没〉，应说“我昨天没去，因为我生病了”。"}, {"text": "我不考好，所以很难过。", "explanation": "这里应该用〈没〉。已经发生的结果是没考好，要用〈没〉；〈不〉多表示不愿意，不能说“不考好”。"}, {"text": "我不做完作业，所以不能出去玩。", "explanation": "这里应该用〈没〉。作业是否完成是已经发生的事实，要用〈没〉，应说“没做完作业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19878, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不", "is_correct": true, "explanation": "正确。“不”（bù）是否定副词，表示否定。"}, {"text": "木", "is_correct": false, "explanation": "木（mù，第四声）与 bù 声母不同（m 与 b），意思是树木。"}, {"text": "怒", "is_correct": false, "explanation": "怒（nù，第四声）与 bù 声母不同（n 与 b），意思是愤怒。"}, {"text": "补", "is_correct": false, "explanation": "补（bǔ，第三声）与 bù 声调不同，意思是补充。"}, {"text": "幕", "is_correct": false, "explanation": "幕（mù，第四声）与 bù 声母不同（m 与 b），意思是幕布。"}], "explanations": {"不": "正确。“不”（bù）是否定副词，表示否定。", "木": "木（mù，第四声）与 bù 声母不同（m 与 b），意思是树木。", "怒": "怒（nù，第四声）与 bù 声母不同（n 与 b），意思是愤怒。", "补": "补（bǔ，第三声）与 bù 声调不同，意思是补充。", "幕": "幕（mù，第四声）与 bù 声母不同（m 与 b），意思是幕布。"}, "sentence_index": null, "correct_answer": "不"}, "level_3": {"options": [{"text": "不", "is_correct": true, "explanation": "正确。“我不想回家”表示否定，与后句“想再玩一会儿”相符。"}, {"text": "就", "is_correct": false, "explanation": "语义：“就”表示只想，与后句“想再玩一会儿”矛盾。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示仅仅，与后句“想再玩一会儿”矛盾。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”多与已发生的动作或变化搭配，与心理动词“想”不合。"}], "explanations": {"不": "正确。“我不想回家”表示否定，与后句“想再玩一会儿”相符。", "就": "语义：“就”表示只想，与后句“想再玩一会儿”矛盾。", "只": "语义：“只”表示仅仅，与后句“想再玩一会儿”矛盾。", "已经": "搭配：“已经”多与已发生的动作或变化搭配，与心理动词“想”不合。"}, "sentence_index": 6, "correct_answer": "不"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请不在教室里大声说话。", "explanation": "这里应该用〈别〉或〈不要〉。劝阻、禁止要用〈别〉，〈不〉只陈述否定，“请不在教室里”不通。"}, {"text": "我昨天不看见他，所以没有打招呼。", "explanation": "这里应该用〈没〉。“看见”是不受意志控制的感知，过去没有发生的事实要用〈没〉，应说“我昨天没看见他”。"}, {"text": "他不朋友很多，所以很少出去玩。", "explanation": "这里的〈不〉放错了位置。〈不〉应放在谓词前，应说“他朋友不多，所以很少出去玩”，不能插在主语“他”与“朋友”之间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不去过北京，这是第一次去。", "corrected_sentence": "我没去过北京，这是第一次去。", "error_description": "否定词错误：说明没有过某种经历，要用“没”，应为“没去过北京”，不能说“不去过北京”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家不有电视，我们常去朋友家看。", "corrected_sentence": "我家没有电视，我们常去朋友家看。", "error_description": "否定词错误：表示领有的否定要用“没有”，应为“没有电视”，不能说“不有电视”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
