INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19879, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改变，使事物发生变化。", "primary_collocate": null, "pronunciation": "gǎi", "ipa": "kai˨˩˦", "syllable_count": 1, "sentences": [{"text": "我们会听用户的建议，把软件改得更好。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把房间的颜色改成了蓝色。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想改一下旅行的时间。", "target_word": "改", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天下雨，我们改去看电影吧。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今年改做生意了。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生让他改吃清淡的饭菜。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把会议改到下午三点了。", "target_word": "改", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她家的房子改成了一家小书店。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司改了上班的时间，早上九点开始。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路太堵，我们改走小路吧。", "target_word": "改", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "改了", "label": "体标"}, {"form": "改过", "label": "体标"}, {"form": "改改", "label": "重叠"}, {"form": "改变", "label": "复合"}, {"form": "改进", "label": "复合"}], "register": "中性", "sense_fingerprint": "把原来的样子、时间、做法换成另一种（改成、改到、改做）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fa5d8e-2296-45e3-ab90-df9c0be39312') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19879, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "改", "is_correct": true, "explanation": "正确：改（gǎi），意思是改变、更改，即把原来的样子换成别的。"}, {"text": "海", "is_correct": false, "explanation": "hǎi（第三声）与 gǎi 声母不同（h 与 g），意思是大海。"}, {"text": "买", "is_correct": false, "explanation": "mǎi（第三声）与 gǎi 声母不同（m 与 g），意思是购买。"}, {"text": "感", "is_correct": false, "explanation": "gǎn（第三声）与 gǎi 韵母不同（an 与 ai），意思是感觉。"}, {"text": "搞", "is_correct": false, "explanation": "gǎo（第三声）与 gǎi 韵母不同（ao 与 ai），意思是做、干。"}, {"text": "该", "is_correct": false, "explanation": "gāi（第一声）与 gǎi 声调不同，意思是应当、该当。"}], "explanations": {"改": "正确：改（gǎi），意思是改变、更改，即把原来的样子换成别的。", "海": "hǎi（第三声）与 gǎi 声母不同（h 与 g），意思是大海。", "买": "mǎi（第三声）与 gǎi 声母不同（m 与 g），意思是购买。", "感": "gǎn（第三声）与 gǎi 韵母不同（an 与 ai），意思是感觉。", "搞": "gǎo（第三声）与 gǎi 韵母不同（ao 与 ai），意思是做、干。", "该": "gāi（第一声）与 gǎi 声调不同，意思是应当、该当。"}, "sentence_index": null, "correct_answer": "改"}, "level_3": {"options": [{"text": "改", "is_correct": true, "explanation": "正确：“改得更好”指改进得更好，符合“听用户的建议”的语境。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“哭”指流泪出声，与改进做法无关，“哭得更好”在此语境中说不通。"}, {"text": "吵", "is_correct": false, "explanation": "语义：“吵”指争吵、声音嘈杂，与改进做法无关，“吵得更好”说不通。"}, {"text": "咳", "is_correct": false, "explanation": "语义：“咳”指咳嗽，与改进做法无关，“咳得更好”说不通。"}], "explanations": {"改": "正确：“改得更好”指改进得更好，符合“听用户的建议”的语境。", "哭": "语义：“哭”指流泪出声，与改进做法无关，“哭得更好”在此语境中说不通。", "吵": "语义：“吵”指争吵、声音嘈杂，与改进做法无关，“吵得更好”说不通。", "咳": "语义：“咳”指咳嗽，与改进做法无关，“咳得更好”说不通。"}, "sentence_index": 0, "correct_answer": "改"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵树改得很高了。", "explanation": "这里应该用〈长〉。树自己生长变高是自然变化，不是有人有意把它换成另一种样子；“改”要求有人主动改变事物。"}, {"text": "他的儿子改成了大人。", "explanation": "这里应该用〈长成〉。孩子自然长大要说“长成”，“改”指人有意地把事物换成另一种样子，不能用来说人长大。"}, {"text": "他的体重改了三公斤。", "explanation": "这里应该用〈增加〉。体重增减是数量变化，不说“改了三公斤”；“改”指有意地把事物换成另一种样子或做法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19879, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "改", "is_correct": true, "explanation": "正确：改（gǎi），意思是改变、更改，即把原来的样子换成别的。"}, {"text": "百", "is_correct": false, "explanation": "bǎi（第三声）与 gǎi 声母不同（b 与 g），意思是一百。"}, {"text": "奶", "is_correct": false, "explanation": "nǎi（第三声）与 gǎi 声母不同（n 与 g），意思是牛奶。"}, {"text": "盖", "is_correct": false, "explanation": "gài（第四声）与 gǎi 声调不同，意思是覆盖、盖住。"}, {"text": "凯", "is_correct": false, "explanation": "kǎi（第三声）与 gǎi 声母不同（k 与 g），意思是凯旋、胜利。"}], "explanations": {"改": "正确：改（gǎi），意思是改变、更改，即把原来的样子换成别的。", "百": "bǎi（第三声）与 gǎi 声母不同（b 与 g），意思是一百。", "奶": "nǎi（第三声）与 gǎi 声母不同（n 与 g），意思是牛奶。", "盖": "gài（第四声）与 gǎi 声调不同，意思是覆盖、盖住。", "凯": "kǎi（第三声）与 gǎi 声母不同（k 与 g），意思是凯旋、胜利。"}, "sentence_index": null, "correct_answer": "改"}, "level_3": {"options": [{"text": "改", "is_correct": true, "explanation": "正确：“改到下午三点”指把会议的时间改成下午三点，符合语境。"}, {"text": "送", "is_correct": false, "explanation": "语义：“送”指递送物品，“送到下午三点”不能用于会议时间。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，“把会议吃到下午三点”说不通。"}, {"text": "坐", "is_correct": false, "explanation": "配价：“坐”是不及物动词，不能带“会议”作受事，不能说“把会议坐到”。"}], "explanations": {"改": "正确：“改到下午三点”指把会议的时间改成下午三点，符合语境。", "送": "语义：“送”指递送物品，“送到下午三点”不能用于会议时间。", "吃": "语义：“吃”指进食，“把会议吃到下午三点”说不通。", "坐": "配价：“坐”是不及物动词，不能带“会议”作受事，不能说“把会议坐到”。"}, "sentence_index": 6, "correct_answer": "改"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气改得很冷了。", "explanation": "这里应该用〈变〉。天气自然转冷不需要人去改，要用“变”；“改”指人有意地改变事物。"}, {"text": "这个孩子一年改高了五厘米。", "explanation": "这里应该用〈长〉。孩子身体自然长高是生长，不是有人有意把事物换成另一种样子，不能用“改”。"}, {"text": "工人改了一个大坑。", "explanation": "这里应该用〈挖〉。挖坑是造出空洞的动作，“改”指对原有事物做变动，不能用来说挖出一个坑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19879, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把窗帘改了蓝色。", "corrected_sentence": "他把窗帘改成了蓝色。", "error_description": "错误形式：“改了蓝色”；正确形式：“改成了蓝色”。“改”后要用“成”引出变成的结果，不能直接接结果词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19879, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天我们把会议改到了下午三点。", "corrected_sentence": "明天我们把会议改到下午三点。", "error_description": "“了”用错：“明天”表示将来，动作尚未发生，“改到”后不能加“了”，应说“明天我们把会议改到下午三点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b63040f2-b408-47a7-9224-16854b1fd9d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
