INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19880, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示允许、指使或容许他人做某事。", "primary_collocate": null, "pronunciation": "ràng", "ipa": "ɻɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "妈妈不让我晚上出去玩。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸让我自己决定。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生不让他喝酒。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请让我看一看你的书。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她不让孩子玩手机。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里不让停车。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让我们进教室。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别让我一个人去，好吗？", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司让他在家工作。", "target_word": "让", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你让我想一想，明天告诉你。", "target_word": "让", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "让了", "label": "完成体"}, {"form": "不让", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "动词：允许、容许别人做某事，常与“不”连用表示不许", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ebfe7736-19f5-4660-8550-caa3fb9fd6f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19880, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "让", "is_correct": true, "explanation": "正确。“让”（ràng，第四声）表示允许或指使。"}, {"text": "浪", "is_correct": false, "explanation": "浪（làng，第四声）与 ràng 声母不同（l 与 r），意思是波浪。"}, {"text": "荡", "is_correct": false, "explanation": "荡（dàng，第四声）与 ràng 声母不同（d 与 r），意思是摇荡。"}, {"text": "嚷", "is_correct": false, "explanation": "嚷（rǎng，第三声）与 ràng 声调不同，意思是大声喊叫。"}], "explanations": {"让": "正确。“让”（ràng，第四声）表示允许或指使。", "浪": "浪（làng，第四声）与 ràng 声母不同（l 与 r），意思是波浪。", "荡": "荡（dàng，第四声）与 ràng 声母不同（d 与 r），意思是摇荡。", "嚷": "嚷（rǎng，第三声）与 ràng 声调不同，意思是大声喊叫。"}, "sentence_index": null, "correct_answer": "让"}, "level_3": {"options": [{"text": "让", "is_correct": true, "explanation": "正确。“妈妈不让我晚上出去玩”表示不允许，与句意相符。"}, {"text": "拿", "is_correct": false, "explanation": "语义：“拿”表示手持、取得，与“出去玩”搭配不通，句子不成立。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”要求后接被处置的对象和动词结构，此处结构不成立。"}, {"text": "使", "is_correct": false, "explanation": "语域：“使”属于书面语，口语中不这样说“妈妈不使我晚上出去玩”。"}], "explanations": {"让": "正确。“妈妈不让我晚上出去玩”表示不允许，与句意相符。", "拿": "语义：“拿”表示手持、取得，与“出去玩”搭配不通，句子不成立。", "把": "配价：“把”要求后接被处置的对象和动词结构，此处结构不成立。", "使": "语域：“使”属于书面语，口语中不这样说“妈妈不使我晚上出去玩”。"}, "sentence_index": 0, "correct_answer": "让"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请让我一杯水。", "explanation": "这里应该用〈给〉。〈让〉表示允许或指使，不表示“给予”，应说“请给我一杯水”。"}, {"text": "他让我的名字是小明。", "explanation": "这里应该用〈叫〉。〈让〉没有“称呼”的意思，应说“他叫我小明”。"}, {"text": "妈妈让去超市买菜。", "explanation": "这里缺少被允许或被指使的人。〈让〉后面要接一个人，应说“妈妈让我去超市买菜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19880, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "让", "is_correct": true, "explanation": "正确。“让”（ràng，第四声）表示允许或指使。"}, {"text": "趟", "is_correct": false, "explanation": "趟（tàng，第四声）与 ràng 声母不同（t 与 r），意思是一次、一回。"}, {"text": "傍", "is_correct": false, "explanation": "傍（bàng，第四声）与 ràng 声母不同（b 与 r），意思是靠近，如“傍晚”。"}, {"text": "瓤", "is_correct": false, "explanation": "瓤（ráng，第二声）与 ràng 声调不同，意思是瓜果的肉。"}], "explanations": {"让": "正确。“让”（ràng，第四声）表示允许或指使。", "趟": "趟（tàng，第四声）与 ràng 声母不同（t 与 r），意思是一次、一回。", "傍": "傍（bàng，第四声）与 ràng 声母不同（b 与 r），意思是靠近，如“傍晚”。", "瓤": "瓤（ráng，第二声）与 ràng 声调不同，意思是瓜果的肉。"}, "sentence_index": null, "correct_answer": "让"}, "level_3": {"options": [{"text": "让", "is_correct": true, "explanation": "正确。“老师让我们进教室”表示指使，与句意相符。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”的宾语是文字或作品，不能接“我们进教室”这样的兼语结构，句子不成立。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮料，“老师喝我们进教室”不成立。"}, {"text": "给", "is_correct": false, "explanation": "配价：“给”需要接受者和动作的组合结构，此处“给我们进教室”不成立。"}], "explanations": {"让": "正确。“老师让我们进教室”表示指使，与句意相符。", "写": "配价：“写”的宾语是文字或作品，不能接“我们进教室”这样的兼语结构，句子不成立。", "喝": "语义：“喝”的对象是饮料，“老师喝我们进教室”不成立。", "给": "配价：“给”需要接受者和动作的组合结构，此处“给我们进教室”不成立。"}, "sentence_index": 6, "correct_answer": "让"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师让进教室。", "explanation": "这里缺少被指使的人。〈让〉后面要接一个人，应说“老师让我们进教室”。"}, {"text": "请让我一张票。", "explanation": "这里应该用〈给〉。〈让〉表示允许或指使，不表示“给予”，应说“请给我一张票”。"}, {"text": "我让你的名字是小红。", "explanation": "这里应该用〈叫〉。〈让〉没有“称呼”的意思，应说“我叫你小红”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师让不我们在教室里吃东西。", "corrected_sentence": "老师不让我们在教室里吃东西。", "error_description": "语序错误：否定词“不”应放在“让”前面，应为“不让我们”，不能说“让不我们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈让先我吃饭，然后再写作业。", "corrected_sentence": "妈妈让我先吃饭，然后再写作业。", "error_description": "语序错误：“让”后面应先接被允许的人“我”，再接动词，应为“让我先吃饭”，不能说“让先我吃饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02226a68-658a-4356-821b-8a8997342f34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
