INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19883, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能识别特定个人的各种信息，如姓名、身份证号、住址、电话号码等。", "primary_collocate": null, "pronunciation": "gè rén xìn xī", "ipa": "kɤ˥˩ ɻən˧˥ ɕin˥˩ ɕi˥", "syllable_count": 4, "sentences": [{"text": "用户使用服务时，会提供很多个人信息。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "注册时，网站会要求你填写姓名和电话等个人信息。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行不会通过短信向客户索要个人信息。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把身份证号等个人信息发给陌生人。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司必须保护客户的个人信息，不能随便卖给别人。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机丢了以后，他担心里面的个人信息会泄露。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办理这项业务时，需要核对您的个人信息。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在表格里填了姓名、住址等个人信息。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察提醒市民，网上不要随便公开个人信息。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骗子用偷来的个人信息申请了贷款。", "target_word": "个人信息", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "能识别某个人的信息，如姓名、身份证号、住址、电话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d3e40a-5887-46ae-a092-87880ccdc4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19883, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "语义：「心情」是内心的感受，不是用户会提供给服务方的资料，与「提供很多」的语境不符。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：「雨水」是自然现象，不是用户使用服务时提供的资料，与语境不符。"}, {"text": "个人信息", "is_correct": true, "explanation": "正确。「提供个人信息」指用户在使用服务时提交身份、联系等资料。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」是商品的属性，用户在使用服务时不会把价格当作个人资料提供。"}], "explanations": {"心情": "语义：「心情」是内心的感受，不是用户会提供给服务方的资料，与「提供很多」的语境不符。", "雨水": "语义：「雨水」是自然现象，不是用户使用服务时提供的资料，与语境不符。", "个人信息": "正确。「提供个人信息」指用户在使用服务时提交身份、联系等资料。", "价格": "语义：「价格」是商品的属性，用户在使用服务时不会把价格当作个人资料提供。"}, "sentence_index": 0, "correct_answer": "个人信息"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把个人信息放进锅里煮了。", "explanation": "这里应该用〈饺子〉。个人信息指姓名、电话等资料，不能放进锅里煮。"}, {"text": "商店在街上发放个人信息。", "explanation": "这里应该用〈广告〉。个人信息是关于某个人的资料，不能像广告一样拿到街上发放。"}, {"text": "他每天早上都要浇一遍个人信息。", "explanation": "这里应该用〈花〉。个人信息是关于某个人的资料，不能像植物一样用“浇”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19883, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感受", "is_correct": false, "explanation": "语义：「感受」是主观体验，无法像身份资料一样进行核对。"}, {"text": "气味", "is_correct": false, "explanation": "语义：「气味」不是可以核对的个人资料，与办理业务的语境不符。"}, {"text": "个人信息", "is_correct": true, "explanation": "正确。「核对个人信息」指核实身份、联系等资料，符合办理业务的语境。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：「核对」一般不与「脾气」搭配，脾气也不是办理业务时需要核实的内容。"}], "explanations": {"感受": "语义：「感受」是主观体验，无法像身份资料一样进行核对。", "气味": "语义：「气味」不是可以核对的个人资料，与办理业务的语境不符。", "个人信息": "正确。「核对个人信息」指核实身份、联系等资料，符合办理业务的语境。", "脾气": "搭配：「核对」一般不与「脾气」搭配，脾气也不是办理业务时需要核实的内容。"}, "sentence_index": 6, "correct_answer": "个人信息"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的个人信息很好吃，我都尝了一遍。", "explanation": "这里应该用〈食物〉。个人信息指姓名、住址等资料，不能用“好吃”来形容。"}, {"text": "他连续跑了一个小时的个人信息。", "explanation": "这里应该用〈路程〉。个人信息是资料，不能用“跑”来表示行走的距离。"}, {"text": "老人给孩子讲个人信息。", "explanation": "这里应该用〈故事〉。个人信息是资料，不能用来讲述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19883, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他复印了一本个人信息。", "corrected_sentence": "他复印了一份个人信息。", "error_description": "量词错误：「个人信息」应搭配「份」，「本」用于书籍，不能用来修饰个人信息。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19883, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们会保护了你的个人信息。", "corrected_sentence": "我们会保护你的个人信息。", "error_description": "体标错误：「会」表示将来，不能与完成体「了」同用，应去掉「了」，写作「我们会保护你的个人信息」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
