INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19887, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示承接关系，相当于‘于是’、‘便’，用于连接前后两个动作或情况。", "primary_collocate": null, "pronunciation": "jiù", "ipa": "tɕjoʊ̯⁵¹", "syllable_count": 1, "sentences": [{"text": "他一回家就开始做饭。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我吃完饭就去学校。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一看见妈妈就笑了。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下了课，我们就去操场玩。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他听完电话就出门了。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说完，大家就安静了。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一到北京就给你打电话。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子一累就想睡觉。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗完手，我们就吃饭。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天一黑，街上的灯就亮了。", "target_word": "就", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "承接前一动作，引出紧接着的后一动作或情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47c36c6a-10d1-484f-a144-0a730fa56e1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19887, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "就", "is_correct": true, "explanation": "就（第四声）是本词，表示承接前后两个动作。"}, {"text": "九", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是数字“九”。"}, {"text": "久", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是“时间长”。"}, {"text": "酒", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是“酒水”。"}, {"text": "袖", "is_correct": false, "explanation": "xiù 与 jiù 声母不同（x 与 j），意思是“衣袖”。"}], "explanations": {"就": "就（第四声）是本词，表示承接前后两个动作。", "九": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是数字“九”。", "久": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是“时间长”。", "酒": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是“酒水”。", "袖": "xiù 与 jiù 声母不同（x 与 j），意思是“衣袖”。"}, "sentence_index": null, "correct_answer": "就"}, "level_3": {"options": [{"text": "就", "is_correct": true, "explanation": "就：与“一…就…”搭配，表示前一动作一发生，后一动作紧接着发生。"}, {"text": "才", "is_correct": false, "explanation": "语义：才表示“晚、仅此时”，与“一…就”的紧接关系相反。"}, {"text": "还", "is_correct": false, "explanation": "搭配：“一…还…”不构成承接句，不能引出紧接的动作。"}, {"text": "却", "is_correct": false, "explanation": "语义：却表示转折，与“一…就”的承接关系不符。"}], "explanations": {"就": "就：与“一…就…”搭配，表示前一动作一发生，后一动作紧接着发生。", "才": "语义：才表示“晚、仅此时”，与“一…就”的紧接关系相反。", "还": "搭配：“一…还…”不构成承接句，不能引出紧接的动作。", "却": "语义：却表示转折，与“一…就”的承接关系不符。"}, "sentence_index": 0, "correct_answer": "就"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事就是我的错，和你没有关系。", "explanation": "此处的“就是”表示“正是”，强调肯定，不表示承接先后动作。"}, {"text": "这个班就有十个学生。", "explanation": "此处的“就”表示“仅仅”，限定数量，不表示承接先后动作。"}, {"text": "他就着热水吃药。", "explanation": "此处的“就”表示“借着、凭借”，与“就着某物”搭配，不表示承接先后动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19887, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "就", "is_correct": true, "explanation": "就（第四声）是本词，表示承接前后两个动作。"}, {"text": "秀", "is_correct": false, "explanation": "xiù（第四声）与 jiù（第四声）声母不同（x 与 j），意思是“优秀、秀丽”。"}, {"text": "绣", "is_correct": false, "explanation": "xiù（第四声）与 jiù 声母不同（x 与 j），意思是“刺绣”。"}, {"text": "韭", "is_correct": false, "explanation": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是“韭菜”。"}], "explanations": {"就": "就（第四声）是本词，表示承接前后两个动作。", "秀": "xiù（第四声）与 jiù（第四声）声母不同（x 与 j），意思是“优秀、秀丽”。", "绣": "xiù（第四声）与 jiù 声母不同（x 与 j），意思是“刺绣”。", "韭": "jiǔ（第三声）与 jiù（第四声）声调不同，意思是“韭菜”。"}, "sentence_index": null, "correct_answer": "就"}, "level_3": {"options": [{"text": "就", "is_correct": true, "explanation": "就：与“一…就…”搭配，表示到达北京后紧接着打电话。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”不与“一…就”搭配，句意变成“只打电话”，与承接不符。"}, {"text": "刚", "is_correct": false, "explanation": "语义：刚表示“刚刚”，与“一到就”的紧接关系冲突。"}, {"text": "再", "is_correct": false, "explanation": "语义：再表示之后又一次，与“一到北京就”的紧接关系不符。"}], "explanations": {"就": "就：与“一…就…”搭配，表示到达北京后紧接着打电话。", "只": "搭配：“只”不与“一…就”搭配，句意变成“只打电话”，与承接不符。", "刚": "语义：刚表示“刚刚”，与“一到就”的紧接关系冲突。", "再": "语义：再表示之后又一次，与“一到北京就”的紧接关系不符。"}, "sentence_index": 6, "correct_answer": "就"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服就五十块钱。", "explanation": "此处的“就”表示“仅仅、只”，限定数量，不表示承接先后动作。"}, {"text": "他家就在学校旁边。", "explanation": "此处的“就”表示“正是、恰好”，强调确定，不表示承接先后动作。"}, {"text": "火车马上就要开了。", "explanation": "此处的“就要”表示即将发生，不表示承接前一动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19887, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈一下班去就超市买菜。", "corrected_sentence": "妈妈一下班就去超市买菜。", "error_description": "“就”位置错误：“就”应放在紧接的后一动作之前，应说“一下班就去超市买菜”，不能放在动词“去”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19887, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一到家就了给你打电话。", "corrected_sentence": "我一到家就给你打电话。", "error_description": "“了”位置错误：“就”后不能直接加“了”，应说“我一到家就给你打电话”，“了”不能插在“就”和动词之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '571872f6-9807-451a-bc7d-5a66fa6060b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
