INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19888, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过行动创造或产生某事物。", "primary_collocate": null, "pronunciation": "zuò chū", "ipa": "tswo˥˩ tʂʰu˥", "syllable_count": 2, "sentences": [{"text": "如果用户不明白说明内容，他们就无法做出正确选择。", "target_word": "做出", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "如果系统做出重要决定，比如自动拒绝一个申请，用户应知道主要原因，并有机会申诉。", "target_word": "做出", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他想了很久，终于做出了决定。", "target_word": "做出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问他一道难题，他很快做出了正确的推断。", "target_word": "做出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到坏消息，他没有做出任何反应。", "target_word": "做出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位科学家为国家做出了很大的贡献。", "target_word": "做出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生看了检查结果，很快做出判断。", "target_word": "做出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他向朋友做出承诺，下次不会迟到。", "target_word": "做出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面对两份工作，你要做出自己的选择。", "target_word": "做出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明做出一个鬼脸，把弟弟逗笑了。", "target_word": "做出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "做出了", "label": "完成体"}, {"form": "做出过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "做出+抽象结果（决定、选择、反应、贡献等），通过行动产生某事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d3e40a-5887-46ae-a092-87880ccdc4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19888, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认为", "is_correct": false, "explanation": "搭配：“认为”后接观点或判断，不能说“认为正确选择”。"}, {"text": "做出", "is_correct": true, "explanation": "正确答案：“无法做出正确选择”表示不能作出选择，符合句意。"}, {"text": "发出", "is_correct": false, "explanation": "搭配：“发出”的对象是声音、信号等，不能说“发出正确选择”。"}, {"text": "认识", "is_correct": false, "explanation": "语义：“认识”指辨认或了解人和事物，与“做选择”的语境不符。"}], "explanations": {"认为": "搭配：“认为”后接观点或判断，不能说“认为正确选择”。", "做出": "正确答案：“无法做出正确选择”表示不能作出选择，符合句意。", "发出": "搭配：“发出”的对象是声音、信号等，不能说“发出正确选择”。", "认识": "语义：“认识”指辨认或了解人和事物，与“做选择”的语境不符。"}, "sentence_index": 0, "correct_answer": "做出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师做出了一个问题。", "explanation": "这里应该用〈提出〉。“做出”指做成具体成果，问题应该用“提出”。"}, {"text": "天做出了一场雨。", "explanation": "这里应该用〈下〉。“做出”指人做成的事物，雨要用“下”。"}, {"text": "他做出了真相。", "explanation": "这里应该用〈说出〉。“做出”指做成事物，真相要用“说出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拿出", "is_correct": false, "explanation": "搭配：“拿出”多指把具体物品取出，不能说“拿出判断”。"}, {"text": "做出", "is_correct": true, "explanation": "正确答案：“很快做出判断”表示迅速得出判断，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与“很快得出判断”的语境相反。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“判断”搭配。"}], "explanations": {"拿出": "搭配：“拿出”多指把具体物品取出，不能说“拿出判断”。", "做出": "正确答案：“很快做出判断”表示迅速得出判断，符合句意。", "扔": "语义：“扔”表示丢弃，与“很快得出判断”的语境相反。", "吃": "搭配：“吃”不能与“判断”搭配。"}, "sentence_index": 6, "correct_answer": "做出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场争论做出了很多问题。", "explanation": "这里应该用〈产生〉。“做出”指人有意做成的成果，争论引起的问题要用“产生”。"}, {"text": "他们之间做出了深厚的感情。", "explanation": "这里应该用〈形成〉。“做出”不用于感情，深厚的感情要用“形成”。"}, {"text": "他做出了一份奖学金。", "explanation": "这里应该用〈获得〉。“做出”不能与奖学金搭配，获得奖学金要用“获得”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他做出了一条决定。", "corrected_sentence": "他做出了一个决定。", "error_description": "量词错误：“条”用于消息、河流、裤子等，不能修饰“决定”；应为“他做出了一个决定。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很快做出着一个选择。", "corrected_sentence": "他很快做出了一个选择。", "error_description": "错误：“做出”是结果动词，后面不能接“着”。完成的动作要用“了”，应为“他很快做出了一个选择”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19889, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "错误", "is_correct": true, "explanation": "错误：与「正确」互为反义，指不符合事实或道理。"}, {"text": "安静", "is_correct": false, "explanation": "无反义关系：「安静」与「正确」意义无关，不是反义词。"}, {"text": "高兴", "is_correct": false, "explanation": "无反义关系：「高兴」指心情愉快，与「正确」不构成反义。"}, {"text": "雪白", "is_correct": false, "explanation": "无反义关系：「雪白」指颜色，与「正确」不构成反义。"}], "correct_answer": "错误", "explanations": {"错误": "错误：与「正确」互为反义，指不符合事实或道理。", "安静": "无反义关系：「安静」与「正确」意义无关，不是反义词。", "高兴": "无反义关系：「高兴」指心情愉快，与「正确」不构成反义。", "雪白": "无反义关系：「雪白」指颜色，与「正确」不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19889, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "错误", "is_correct": true, "explanation": "错误：与「正确」互为反义，指不符合事实或道理。"}, {"text": "甜", "is_correct": false, "explanation": "无反义关系：「甜」指味道，与「正确」不构成反义。"}, {"text": "冷", "is_correct": false, "explanation": "无反义关系：「冷」指温度，与「正确」不构成反义。"}, {"text": "深", "is_correct": false, "explanation": "无反义关系：「深」指程度或距离，与「正确」不构成反义。"}], "correct_answer": "错误", "explanations": {"错误": "错误：与「正确」互为反义，指不符合事实或道理。", "甜": "无反义关系：「甜」指味道，与「正确」不构成反义。", "冷": "无反义关系：「冷」指温度，与「正确」不构成反义。", "深": "无反义关系：「深」指程度或距离，与「正确」不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19889, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "符合事实或道理。", "primary_collocate": null, "pronunciation": "zhèng què", "ipa": "ʈʂɤŋ˥˩ tɕʰɥɛ˥˩", "syllable_count": 2, "sentences": [{"text": "如果用户不明白说明内容，他们就无法做出正确选择。", "target_word": "正确", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这个结论符合事实，所以是正确的。", "target_word": "正确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要想学好汉语，必须用正确的方法。", "target_word": "正确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的想法符合道理，是正确的。", "target_word": "正确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生给了我正确的建议。", "target_word": "正确", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "科学家用实验来证明这个想法是否正确。", "target_word": "正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该有正确的生活习惯。", "target_word": "正确", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "地图上的方向很正确，我们没有走错路。", "target_word": "正确", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告里的数字都正确。", "target_word": "正确", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说他对这件事的看法很正确。", "target_word": "正确", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不正确", "label": "否定式"}, {"form": "正确性", "label": "派生"}], "register": "中性", "sense_fingerprint": "形容想法、方法、结论等符合事实或道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d3e40a-5887-46ae-a092-87880ccdc4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19889, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正确", "is_correct": true, "explanation": "正确：符合事实或道理，修饰「选择」，表示选得对，符合句意。"}, {"text": "高兴", "is_correct": false, "explanation": "搭配：「高兴」形容人的情绪，不能修饰「选择」。"}, {"text": "安静", "is_correct": false, "explanation": "语义：「安静」指没有声音或动作，不能用来说选择的对错。"}, {"text": "雪白", "is_correct": false, "explanation": "体貌：「雪白」形容颜色或外观，不能修饰「选择」。"}], "explanations": {"正确": "正确：符合事实或道理，修饰「选择」，表示选得对，符合句意。", "高兴": "搭配：「高兴」形容人的情绪，不能修饰「选择」。", "安静": "语义：「安静」指没有声音或动作，不能用来说选择的对错。", "雪白": "体貌：「雪白」形容颜色或外观，不能修饰「选择」。"}, "sentence_index": 0, "correct_answer": "正确"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件毛衣很正确，我很喜欢。", "explanation": "这里应该用〈合适〉。正确说的是对错，不用来形容衣服穿着是否合身。"}, {"text": "这顿饭很正确，味道也很好。", "explanation": "这里应该用〈好吃〉。正确只判断对错，不用来评价饭菜的味道。"}, {"text": "她唱歌的声音很正确，大家都爱听。", "explanation": "这里应该用〈好听〉。正确只判断对错，不用来评价声音是否悦耳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19889, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正确", "is_correct": true, "explanation": "正确：修饰「生活习惯」，指符合道理的习惯，符合句意。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：「瘦」形容人的体形，不能修饰「生活习惯」。"}, {"text": "硬", "is_correct": false, "explanation": "语义：「硬」指质地坚实，不能用来描述抽象的习惯。"}, {"text": "晴朗", "is_correct": false, "explanation": "语义：「晴朗」形容天气，不能用于「生活习惯」。"}], "explanations": {"正确": "正确：修饰「生活习惯」，指符合道理的习惯，符合句意。", "瘦": "体貌：「瘦」形容人的体形，不能修饰「生活习惯」。", "硬": "语义：「硬」指质地坚实，不能用来描述抽象的习惯。", "晴朗": "语义：「晴朗」形容天气，不能用于「生活习惯」。"}, "sentence_index": 6, "correct_answer": "正确"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的风景很正确。", "explanation": "这里应该用〈美丽〉。正确只判断对错、真假，不能用来评价风景的美丑。"}, {"text": "他的头发很正确。", "explanation": "这里应该用〈整齐〉。正确只判断对错，不用来形容外表的整洁程度。"}, {"text": "他的脾气很正确。", "explanation": "这里应该用〈好〉。正确只判断对错，不能用来形容脾气的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19889, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你的做法很正确性，老师很满意。", "corrected_sentence": "你的做法很正确，老师很满意。", "error_description": "错误形式：「正确性」；正确形式：「正确」。「正确性」是名词，不能用程度副词「很」修饰，这里应该用形容词「正确」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19889, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个答案没正确，请再看看。", "corrected_sentence": "这个答案不正确，请再看看。", "error_description": "错误形式：「没正确」；正确形式：「不正确」。否定形容词要用「不」，「没」不能用来否定形容词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
