INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19891, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示确定、必然或坚决的态度。", "primary_collocate": null, "pronunciation": "yí dìng", "ipa": "i˧˥ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "明天的会议一定准时开始。", "target_word": "一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天你一定要早点儿来。", "target_word": "一定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别担心，我一定会帮你的。", "target_word": "一定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他这么努力，一定能通过考试。", "target_word": "一定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你一定要记住这件事。", "target_word": "一定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "灯亮着，他一定在家。", "target_word": "一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我这次一定要把作业写完。", "target_word": "一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一定去，你放心吧。", "target_word": "一定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今年夏天我一定去海边玩。", "target_word": "一定", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "听说那家饭馆很好吃，我们一定要试试。", "target_word": "一定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不一定", "label": "否定式"}], "register": "中性", "sense_fingerprint": "副词，表示坚决的态度或必然的推断：一定要、一定会、一定能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85d3e40a-5887-46ae-a092-87880ccdc4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19891, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一定", "is_correct": true, "explanation": "一定：表示确定，修饰「准时开始」，符合句意。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：「已经」表示动作已经发生，与「明天」的将来时间矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "语义：「从来」表示一向如此，不能与将来的「明天」搭配。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示不常发生，与确定准时开始的会议不符。"}], "explanations": {"一定": "一定：表示确定，修饰「准时开始」，符合句意。", "已经": "搭配：「已经」表示动作已经发生，与「明天」的将来时间矛盾。", "从来": "语义：「从来」表示一向如此，不能与将来的「明天」搭配。", "偶尔": "语义：「偶尔」表示不常发生，与确定准时开始的会议不符。"}, "sentence_index": 0, "correct_answer": "一定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一定知道这件事，但是他并不确定。", "explanation": "这里应该用〈也许〉。一定表示确定，与后半句表示不确定的语气矛盾。"}, {"text": "他一定会来，不过我也说不准。", "explanation": "这里应该用〈可能〉。一定表示确定，与后半句「说不准」的不确定语气矛盾。"}, {"text": "她也许一定会来。", "explanation": "这里应该去掉〈也许〉。一定表示确定，与表示推测的「也许」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19891, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一定", "is_correct": true, "explanation": "一定：表示坚决的态度，修饰「要」，符合句意。"}, {"text": "总是", "is_correct": false, "explanation": "语义：「总是」表示经常，与「这次」的一次性不符。"}, {"text": "好像", "is_correct": false, "explanation": "语义：「好像」表示似乎、带有推测，与「要把作业写完」所表达的决心不符。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：「竟然」表示出乎意料，与句中说明决心的语气不符。"}], "explanations": {"一定": "一定：表示坚决的态度，修饰「要」，符合句意。", "总是": "语义：「总是」表示经常，与「这次」的一次性不符。", "好像": "语义：「好像」表示似乎、带有推测，与「要把作业写完」所表达的决心不符。", "竟然": "语义：「竟然」表示出乎意料，与句中说明决心的语气不符。"}, "sentence_index": 6, "correct_answer": "一定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一定可能去那家饭馆。", "explanation": "这里应该去掉〈一定〉。一定表示确定，与表示推测的「可能」矛盾。"}, {"text": "我还没决定，我们一定去那家饭馆。", "explanation": "这里应该用〈也许〉。还没决定时不能用表示确定的一定。"}, {"text": "我们一定大概去那家饭馆。", "explanation": "这里应该用〈大概〉。一定表示确定，与表示推测的「大概」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19891, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他看起来很一定很累。", "corrected_sentence": "他看起来一定很累。", "error_description": "错误形式：「很一定很累」；正确形式：「一定很累」。副词「一定」要放在「很」之前修饰形容词，「很」不能放在「一定」前面，句中也不能重复使用「很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19891, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天我一定去了。", "corrected_sentence": "明天我一定去。", "error_description": "错误形式：「一定去了」；正确形式：「一定去」。句中有「明天」表示将来，不能用「了」表示已经完成；「一定」表示对将来的确定。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '308fac2f-75d3-4b72-bab7-3881ffc7e4ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
