INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19894, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "快速地、粗略地阅读。", "primary_collocate": null, "pronunciation": "liú lǎn", "ipa": "ljoʊ˧˥ lan˨˩˦", "syllable_count": 2, "sentences": [{"text": "我今天先浏览了新闻，再去上课。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先浏览了一遍目录，再决定读哪章。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上浏览新闻网站。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先浏览全文，再回答问题。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只是随便浏览一下，没有仔细看。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在图书馆里浏览着最新的杂志。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们快速浏览这篇文章。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我浏览过这本书，但没有读完。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢在睡前浏览网页。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前，我浏览了一遍笔记。", "target_word": "浏览", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "浏览了", "label": "体标"}, {"form": "浏览过", "label": "体标"}, {"form": "浏览着", "label": "体标"}, {"form": "浏览器", "label": "复合"}, {"form": "瀏覽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "快速粗略地阅读", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34a0e51c-73da-4535-940d-e3dbc7c8f001') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19894, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浏览", "is_correct": true, "explanation": "正确：“浏览新闻”指快速粗略地看，与“先……再去上课”的语境相符。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理针对损坏的器物，不能用于新闻，句意不通。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：哭泣是情绪动作，不能作用于新闻，句意不通。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植是栽培作物，不能用于新闻，句意不通。"}], "explanations": {"浏览": "正确：“浏览新闻”指快速粗略地看，与“先……再去上课”的语境相符。", "修理": "语义：修理针对损坏的器物，不能用于新闻，句意不通。", "哭泣": "语义：哭泣是情绪动作，不能作用于新闻，句意不通。", "种植": "语义：种植是栽培作物，不能用于新闻，句意不通。"}, "sentence_index": 0, "correct_answer": "浏览"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生们认真浏览课文，一句一句地分析。", "explanation": "这里应该用〈研读〉。浏览是快速粗略地看，与“认真”“一句一句地分析”的深入读法矛盾。"}, {"text": "老师要求我们浏览这首诗，逐字琢磨。", "explanation": "这里应该用〈精读〉。浏览只是快速看一遍，不能与“逐字琢磨”搭配。"}, {"text": "他一字一句地浏览那封信，想弄清每个细节。", "explanation": "这里应该用〈细读〉。浏览强调快速粗略，与“一字一句”和“弄清每个细节”的细致读法矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19894, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浏览", "is_correct": true, "explanation": "正确：“快速浏览这篇文章”符合“快速粗略地阅读”的含义。"}, {"text": "钻研", "is_correct": false, "explanation": "语义：“钻研”指深入研究，与“快速”的要求相反。"}, {"text": "推敲", "is_correct": false, "explanation": "语义：“推敲”指反复斟酌，与“快速”矛盾。"}, {"text": "咀嚼", "is_correct": false, "explanation": "搭配：“咀嚼”多用于食物或比喻性的细细品味，不与“快速”搭配。"}], "explanations": {"浏览": "正确：“快速浏览这篇文章”符合“快速粗略地阅读”的含义。", "钻研": "语义：“钻研”指深入研究，与“快速”的要求相反。", "推敲": "语义：“推敲”指反复斟酌，与“快速”矛盾。", "咀嚼": "搭配：“咀嚼”多用于食物或比喻性的细细品味，不与“快速”搭配。"}, "sentence_index": 6, "correct_answer": "浏览"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天晚上浏览一杯牛奶，然后睡觉。", "explanation": "浏览的对象应是文字、页面等信息，“一杯牛奶”不能被浏览，这里应该用〈喝〉。"}, {"text": "她浏览了一下那盆花，然后浇了水。", "explanation": "浏览的对象应是文字、页面等信息，“花”不能被浏览，这里应该用〈欣赏〉。"}, {"text": "我浏览了一下这块石头，想把它搬走。", "explanation": "“石头”不是可以快速阅读的信息，不能用“浏览”，这里应该用〈观察〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19894, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他浏览很快，半小时就看完了。", "corrected_sentence": "他浏览得很快，半小时就看完了。", "error_description": "错误：“浏览很快”，缺少连接状态补语的“得”；正确：“浏览得很快”。动词后接形容词表示状态时要用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19894, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她边吃饭边浏览过新闻。", "corrected_sentence": "她边吃饭边浏览着新闻。", "error_description": "体标错误：“过”表示曾经的经历，与“边吃饭边”描述的同时进行的动作不符，应用“着”，说“浏览着新闻”表示动作持续。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19895, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "接受", "is_correct": true, "explanation": "正确：“接受”与“拒绝”互为反义，指对他人的请求或建议表示同意。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指双方交换意见，与“拒绝”不构成反义关系。"}, {"text": "提醒", "is_correct": false, "explanation": "“提醒”指让人注意某事，与“拒绝”不构成反义关系。"}, {"text": "询问", "is_correct": false, "explanation": "“询问”指提出问题以求了解，与“拒绝”不构成反义关系。"}], "correct_answer": "接受", "explanations": {"接受": "正确：“接受”与“拒绝”互为反义，指对他人的请求或建议表示同意。", "讨论": "“讨论”指双方交换意见，与“拒绝”不构成反义关系。", "提醒": "“提醒”指让人注意某事，与“拒绝”不构成反义关系。", "询问": "“询问”指提出问题以求了解，与“拒绝”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19895, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "接受", "is_correct": true, "explanation": "正确：“接受”与“拒绝”互为反义，指对他人的请求或建议表示同意。"}, {"text": "解释", "is_correct": false, "explanation": "“解释”指说明道理或原因，与“拒绝”不构成反义关系。"}, {"text": "赞美", "is_correct": false, "explanation": "“赞美”指称赞他人，与“拒绝”不构成反义关系。"}, {"text": "准备", "is_correct": false, "explanation": "“准备”指事先做好安排，与“拒绝”不构成反义关系。"}], "correct_answer": "接受", "explanations": {"接受": "正确：“接受”与“拒绝”互为反义，指对他人的请求或建议表示同意。", "解释": "“解释”指说明道理或原因，与“拒绝”不构成反义关系。", "赞美": "“赞美”指称赞他人，与“拒绝”不构成反义关系。", "准备": "“准备”指事先做好安排，与“拒绝”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19895, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示不接受他人的请求、建议或给予的东西。", "primary_collocate": null, "pronunciation": "jù jué", "ipa": "tɕy˥˩ tɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "网站拒绝了我的注册申请，我想知道原因。", "target_word": "拒绝", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "公司拒绝了他的加薪要求。", "target_word": "拒绝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板拒绝了我的请假申请。", "target_word": "拒绝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拒绝大家的建议，还是按自己的想法做。", "target_word": "拒绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行拒绝给他贷款，因为他没有稳定的工作。", "target_word": "拒绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方拒绝了我们的合作邀请。", "target_word": "拒绝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生的建议很有道理，你不应该拒绝。", "target_word": "拒绝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校拒绝了他的入学申请，他很难过。", "target_word": "拒绝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她拒绝回答记者提出的问题。", "target_word": "拒绝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理拒绝了这个方案，因为成本太高。", "target_word": "拒绝", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "拒绝了", "label": "完成体"}, {"form": "拒绝过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "不接受别人的请求、建议或要求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34a0e51c-73da-4535-940d-e3dbc7c8f001') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19895, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拒绝", "is_correct": true, "explanation": "正确：网站不接受我的注册申请，与“我想知道原因”的语境相符。"}, {"text": "原谅", "is_correct": false, "explanation": "搭配：“原谅”的对象是人或过错，不能说原谅一个申请。"}, {"text": "微笑", "is_correct": false, "explanation": "配价：“微笑”是不及物动词，后面不能带“申请”作宾语。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”针对帮助或善意，网站对申请不能说感谢，句意不通。"}], "explanations": {"拒绝": "正确：网站不接受我的注册申请，与“我想知道原因”的语境相符。", "原谅": "搭配：“原谅”的对象是人或过错，不能说原谅一个申请。", "微笑": "配价：“微笑”是不及物动词，后面不能带“申请”作宾语。", "感谢": "语义：“感谢”针对帮助或善意，网站对申请不能说感谢，句意不通。"}, "sentence_index": 0, "correct_answer": "拒绝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我拒绝了老师的建议，立刻照做。", "explanation": "这里应该用〈听从〉。拒绝表示不接受，与“立刻照做”矛盾。"}, {"text": "他拒绝了我的请求，立刻把资料发给了我。", "explanation": "这里应该用〈答应〉。拒绝表示不接受请求，与“立刻把资料发给了我”的配合行为矛盾。"}, {"text": "组长拒绝了我的意见，马上修改了报告。", "explanation": "这里应该用〈采纳〉。拒绝意见后又按意见修改报告，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19895, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拒绝", "is_correct": true, "explanation": "正确：“你不应该拒绝”承接“医生的建议很有道理”，表示不应不接受建议。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”与“建议很有道理”的语境无关，不能用来回应建议。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：建议有道理时应接受它，说“不应该感谢”与前句逻辑相反，句意不通。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：前句强调建议有道理，应劝人接受；“不应该夸奖”与此逻辑不符。"}], "explanations": {"拒绝": "正确：“你不应该拒绝”承接“医生的建议很有道理”，表示不应不接受建议。", "咳嗽": "语义：“咳嗽”与“建议很有道理”的语境无关，不能用来回应建议。", "感谢": "语义：建议有道理时应接受它，说“不应该感谢”与前句逻辑相反，句意不通。", "夸奖": "语义：前句强调建议有道理，应劝人接受；“不应该夸奖”与此逻辑不符。"}, "sentence_index": 6, "correct_answer": "拒绝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我拒绝了今天的天气，所以带着伞出门了。", "explanation": "这里是把“拒绝”当成“不理会、不在乎”来用，但“拒绝”只用于别人提出的请求、建议或给予的东西，“天气”不能被拒绝。"}, {"text": "老师拒绝了这堂课的时间，所以提前下课了。", "explanation": "这里是把“拒绝”当成“取消、更改”来用，但“拒绝”只用于别人提出的请求、建议或给予的东西，“时间”不能被拒绝。"}, {"text": "妈妈拒绝了房间里的温度，于是开了空调。", "explanation": "这里是把“拒绝”当成“调节、降低”来用，但“拒绝”只用于别人提出的请求、建议或给予的东西，“温度”不能被拒绝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19895, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他拒绝很委婉，没让我难堪。", "corrected_sentence": "他拒绝得很委婉，没让我难堪。", "error_description": "错误：“拒绝很委婉”，缺少连接状态补语的“得”；正确：“拒绝得很委婉”。动词后接形容词表示状态时要用“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19895, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她没有拒绝了我的建议，我很意外。", "corrected_sentence": "她没有拒绝我的建议，我很意外。", "error_description": "错误：“没有”与“了”同时使用，“拒绝”后多了“了”。正确：否定已发生的动作只用“没有”，应说“没有拒绝我的建议”，不说“没有拒绝了我的建议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
