INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19897, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指当事人对法院的判决或行政机关的决定不服，向原机关或上级机关提出重新处理的要求。", "primary_collocate": null, "pronunciation": "shēn sù", "ipa": "ʂən˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "如果系统做出重要决定，比如自动拒绝一个申请，用户应知道主要原因，并有机会申诉。", "target_word": "申诉", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他对判决不服，决定向上级法院申诉。", "target_word": "申诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位店主不服市场监管部门的决定，准备申诉。", "target_word": "申诉", "complexity_tier": "T3", "furigana": "zhè wèi diànzhǔ bù fú shìchǎng jiānguǎn bùmén de juédìng, zhǔnbèi shēnsù", "sentence_source": "generated"}, {"text": "她为儿子的案子申诉了三年。", "target_word": "申诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "纳税人不服税务机关的决定，可以申诉。", "target_word": "申诉", "complexity_tier": "T3", "furigana": "nàshuìrén bù fú shuìwù jīguān de juédìng, kěyǐ shēnsù", "sentence_source": "generated"}, {"text": "他不同意处罚决定，所以去申诉了。", "target_word": "申诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们多次向有关部门申诉，却没有结果。", "target_word": "申诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人不满法院的判决，想要申诉。", "target_word": "申诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "申诉前，请先准备好所有的材料。", "target_word": "申诉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机不服罚款，向交警部门申诉过。", "target_word": "申诉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "申诉了", "label": "完成体"}, {"form": "申诉过", "label": "经历体"}, {"form": "申诉书", "label": "复合"}], "register": "书面", "sense_fingerprint": "对判决或决定不服，向原机关或上级机关要求重新处理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34a0e51c-73da-4535-940d-e3dbc7c8f001') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19897, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "申诉", "is_correct": true, "explanation": "正确：shēn sù，对判决或决定不服，向原机关或上级机关要求重新处理。"}, {"text": "神速", "is_correct": false, "explanation": "声调不同：神速（shén sù）第一音节为阳平，与申诉（shēn sù）的阴平不同，意思是非常迅速。"}, {"text": "声速", "is_correct": false, "explanation": "韵尾不同：声速（shēng sù）第一音节为 -ng，与申诉的 -n 不同，意思是声音传播的速度。"}, {"text": "伸缩", "is_correct": false, "explanation": "读音不同：伸缩（shēn suō）第二音节为 suō，与申诉的 sù 韵母、声调都不同，意思是伸长和缩短。"}], "explanations": {"申诉": "正确：shēn sù，对判决或决定不服，向原机关或上级机关要求重新处理。", "神速": "声调不同：神速（shén sù）第一音节为阳平，与申诉（shēn sù）的阴平不同，意思是非常迅速。", "声速": "韵尾不同：声速（shēng sù）第一音节为 -ng，与申诉的 -n 不同，意思是声音传播的速度。", "伸缩": "读音不同：伸缩（shēn suō）第二音节为 suō，与申诉的 sù 韵母、声调都不同，意思是伸长和缩短。"}, "sentence_index": null, "correct_answer": "申诉"}, "level_3": {"options": [{"text": "申诉", "is_correct": true, "explanation": "正确：“并有机会申诉”指用户对系统的决定不服，可以请求重新处理。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：用户有机会跳舞与系统决定、主要原因的语境无关，句意不通。"}, {"text": "种树", "is_correct": false, "explanation": "语义：“种树”是种植活动，与用户对决定提出重新处理的语境无关，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与用户应知道原因、有机会处理决定的语境无关，句意不通。"}], "explanations": {"申诉": "正确：“并有机会申诉”指用户对系统的决定不服，可以请求重新处理。", "跳舞": "语义：用户有机会跳舞与系统决定、主要原因的语境无关，句意不通。", "种树": "语义：“种树”是种植活动，与用户对决定提出重新处理的语境无关，句意不通。", "睡觉": "语义：“睡觉”与用户应知道原因、有机会处理决定的语境无关，句意不通。"}, "sentence_index": 0, "correct_answer": "申诉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和邻居为一块地闹得很凶，准备提起申诉。", "explanation": "这里应该用〈诉讼〉。“申诉”针对的是对判决或行政决定不服，普通民事纠纷要说“提起诉讼”。"}, {"text": "他向老师申诉了自己的进步。", "explanation": "这里应该用〈汇报〉。“申诉”是对决定不服、请求重新处理，汇报自己的进步应说“汇报”。"}, {"text": "学生们向校长申诉学校的新食堂很干净。", "explanation": "这里应该用〈称赞〉。“申诉”针对的是不服的决定，夸赞食堂干净应说“称赞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19897, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "申诉", "is_correct": true, "explanation": "正确：“多次向有关部门申诉，却没有结果”指多次提出重新处理的请求。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是个人的休闲活动，不能用来描述向有关部门提出的请求。"}, {"text": "绣花", "is_correct": false, "explanation": "语义：“绣花”指用针线做装饰，与“多次向有关部门”的语境完全不符。"}, {"text": "生气", "is_correct": false, "explanation": "配价：“生气”不能用“向有关部门”引出对象，应说“对……生气”。"}], "explanations": {"申诉": "正确：“多次向有关部门申诉，却没有结果”指多次提出重新处理的请求。", "散步": "语义：“散步”是个人的休闲活动，不能用来描述向有关部门提出的请求。", "绣花": "语义：“绣花”指用针线做装饰，与“多次向有关部门”的语境完全不符。", "生气": "配价：“生气”不能用“向有关部门”引出对象，应说“对……生气”。"}, "sentence_index": 6, "correct_answer": "申诉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向大家申诉了那次旅行。", "explanation": "这里应该用〈讲述〉。“申诉”针对的是不服的判决或决定，讲述经历应说“讲述”。"}, {"text": "他向朋友申诉了一本好书。", "explanation": "这里应该用〈推荐〉。“申诉”是对决定不服、请求重新处理，向朋友介绍好书应说“推荐”。"}, {"text": "他向老师申诉，承认自己说了谎。", "explanation": "这里应该用〈认错〉。“申诉”不用于承认错误，承认错误应说“认错”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19897, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不服这次处罚，向交警部门申诉了三个。", "corrected_sentence": "他不服这次处罚，向交警部门申诉了三次。", "error_description": "错误：计算动作次数要用量词“次”，不能用“个”。正确：应说“申诉了三次”，“次”专用于计量动作的次数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19897, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她为这件事申诉了两个。", "corrected_sentence": "她为这件事申诉了两次。", "error_description": "错误：计算动作的次数要用量词“次”，不能用“个”。正确：应说“申诉了两次”，“次”专用于计量动作的次数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7812589b-bd5d-49c3-abbb-fb9c8bbc75d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
