INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19900, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用来表示事物编号或联系方式的数字组合。", "primary_collocate": null, "pronunciation": "hào mǎ", "ipa": "xɑʊ˥˩ ma˨˩˦", "syllable_count": 2, "sentences": [{"text": "公司应确保数据是合法获取的，不包含敏感信息，如健康记录或身份号码。", "target_word": "号码", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个号码我不认识，是谁打来的？", "target_word": "号码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想打给你，请把你的号码写在这张纸上。", "target_word": "号码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个球员的号码是十，他踢得很好。", "target_word": "号码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的票上有号码，座位在第二排。", "target_word": "号码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行叫到我的号码，我就去窗口了。", "target_word": "号码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你有没有他的号码？我想给他打电话。", "target_word": "号码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他换了手机，所以号码也不一样了。", "target_word": "号码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我拨错了号码，所以没有找到他。", "target_word": "号码", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张卡的号码在后面，一共有十六个数字。", "target_word": "号码", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "电话号码", "label": "复合"}, {"form": "手机号码", "label": "复合"}, {"form": "號碼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "号码：编号或联系方式的数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12968ab-dfb2-45a1-8c6f-73fe3fd501b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19900, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "号码", "is_correct": true, "explanation": "正确。“身份号码”指身份证上的编号。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“身份年龄”不成词组，身份类信息不说年龄。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：身份信息不用颜色表示，“身份颜色”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重属于健康数据，不能证明身份，与“身份”的用法不符。"}], "explanations": {"号码": "正确。“身份号码”指身份证上的编号。", "年龄": "搭配：“身份年龄”不成词组，身份类信息不说年龄。", "颜色": "搭配：身份信息不用颜色表示，“身份颜色”说不通。", "体重": "语义：体重属于健康数据，不能证明身份，与“身份”的用法不符。"}, "sentence_index": 0, "correct_answer": "号码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个号码我算错了，得重新算一遍。", "explanation": "这里应该用〈数字〉。计算得出的数值用数字，号码指用于编号或联系的数字组合。"}, {"text": "这件衣服的号码是五十块。", "explanation": "这里应该用〈价码〉。标价多少用价码，号码指编号或联系方式的数字。"}, {"text": "我的号码是一米七五，比哥哥高。", "explanation": "这里应该用〈身高〉。说人有多高要用身高，号码指编号或联系方式的数字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "号码", "is_correct": true, "explanation": "正确。“你有没有他的号码”指可以用来联系他的数字。"}, {"text": "职业", "is_correct": false, "explanation": "语义：职业指工作类别，不是可以用来联系他的信息，与“打电话”无关。"}, {"text": "性别", "is_correct": false, "explanation": "语义：性别是个人属性，不是可以用来联系他的信息，与“打电话”无关。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”说身体的高矮，与“打电话”无关。"}], "explanations": {"号码": "正确。“你有没有他的号码”指可以用来联系他的数字。", "职业": "语义：职业指工作类别，不是可以用来联系他的信息，与“打电话”无关。", "性别": "语义：性别是个人属性，不是可以用来联系他的信息，与“打电话”无关。", "身高": "语义：“身高”说身体的高矮，与“打电话”无关。"}, "sentence_index": 6, "correct_answer": "号码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果的号码是二十个。", "explanation": "这里应该用〈数量〉。物品数目用数量，号码指编号或联系方式的数字。"}, {"text": "今天的号码是十月三十一日。", "explanation": "这里应该用〈日期〉。说哪一天要用日期，号码指编号或联系方式的数字。"}, {"text": "会议的号码是下午三点。", "explanation": "这里应该用〈时间〉。说什么时候要用时间，号码指编号或联系方式的数字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我换了手机，所以有了一只新号码。", "corrected_sentence": "我换了手机，所以有了一个新号码。", "error_description": "错误：号码的量词是「个」，「只」用于动物或成对的东西。正确应为「一个新号码」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一共记下了三张号码，都是他的。", "corrected_sentence": "我一共记下了三个号码，都是他的。", "error_description": "错误：号码的量词是「个」，不用「张」。正确应为「三个号码」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
