INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19901, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按照一定的时间间隔对事物进行检查或检验。", "primary_collocate": null, "pronunciation": "dìng qī jiǎn chá", "ipa": "tiŋ˥˩ tɕʰi˥ tɕjɛn˨˩˦ tʂʰa˧˥", "syllable_count": 4, "sentences": [{"text": "定期检查数据质量，可以减少错误结果。", "target_word": "定期检查", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "医生说，老人应该定期检查身体。", "target_word": "定期检查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂每个月定期检查机器，所以很少坏。", "target_word": "定期检查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司要定期检查电脑里的文件，保护数据。", "target_word": "定期检查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每年定期检查食堂，保证学生吃得安全。", "target_word": "定期检查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机应该定期检查车，这样路上更安全。", "target_word": "定期检查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们定期检查消防设备，防止出问题。", "target_word": "定期检查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牙医建议每半年定期检查一次牙齿。", "target_word": "定期检查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们定期检查网站，发现问题就马上修好。", "target_word": "定期检查", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每个星期定期检查冰箱，把坏的东西拿走。", "target_word": "定期检查", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "定期檢查", "label": "繁体"}], "register": "中性", "sense_fingerprint": "定期检查：按固定时间间隔检查事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12968ab-dfb2-45a1-8c6f-73fe3fd501b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19901, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "定期检查", "is_correct": true, "explanation": "定期检查：按固定时间间隔检查，能够支持“减少错误结果”这一目的。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：忽略数据质量不会减少错误结果，与句子的因果关系相反。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”的对象是文件，不能说“打印数据质量”。"}, {"text": "庆祝", "is_correct": false, "explanation": "搭配：“庆祝”不能带“数据质量”作宾语，句子不通。"}], "explanations": {"定期检查": "定期检查：按固定时间间隔检查，能够支持“减少错误结果”这一目的。", "忽略": "语义：忽略数据质量不会减少错误结果，与句子的因果关系相反。", "打印": "搭配：“打印”的对象是文件，不能说“打印数据质量”。", "庆祝": "搭配：“庆祝”不能带“数据质量”作宾语，句子不通。"}, "sentence_index": 0, "correct_answer": "定期检查"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校每个月定期检查学生的想法，了解大家的需要。", "explanation": "这里应该用〈调查〉。调查用于了解想法、意见；检查指查看有没有问题，不用来指了解想法。"}, {"text": "老师每周定期检查同学们的友谊，让大家更亲近。", "explanation": "这里应该用〈维护〉。维护指保持、保护使其良好；检查指查看有没有问题，不用来指友谊。"}, {"text": "我们每天定期检查舞，身体很健康。", "explanation": "这里应该用〈跳〉。跳舞指做舞蹈动作；检查指查看有没有问题，不能用于舞蹈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19901, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "定期检查", "is_correct": true, "explanation": "定期检查：按固定时间查看设备，与“防止出问题”的目的相符。"}, {"text": "忘记", "is_correct": false, "explanation": "搭配：“定期”不修饰“忘记”，“定期忘记消防设备”说不通，且与“防止出问题”的目的相反。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：销毁消防设备后谈不上防止问题，句意相反。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”不能与“消防设备”搭配，句子不通。"}], "explanations": {"定期检查": "定期检查：按固定时间查看设备，与“防止出问题”的目的相符。", "忘记": "搭配：“定期”不修饰“忘记”，“定期忘记消防设备”说不通，且与“防止出问题”的目的相反。", "销毁": "语义：销毁消防设备后谈不上防止问题，句意相反。", "欣赏": "搭配：“欣赏”不能与“消防设备”搭配，句子不通。"}, "sentence_index": 6, "correct_answer": "定期检查"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "导游每天定期检查景点的历史，给游客讲故事。", "explanation": "这里应该用〈讲解〉。讲解指向别人说明、解释；检查指查看有没有问题，不用于讲历史。"}, {"text": "孩子们每周定期检查歌，心情很好。", "explanation": "这里应该用〈唱〉。唱歌是发声演唱；检查指查看问题，不能与“歌”搭配表示演唱。"}, {"text": "朋友们每年定期检查他的生日，给他送花。", "explanation": "这里应该用〈祝贺〉。祝贺指表示祝福、庆贺；检查指查看问题，不能用于生日。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂每个月把定期检查安全门。", "corrected_sentence": "工厂每个月定期检查安全门。", "error_description": "错误：“把”字句中，“把”后须先接被处置的对象，此处直接接动词“定期检查”。正确应去掉“把”：“定期检查安全门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19901, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈每个星期的定期检查冰箱里的牛奶，看看有没有过期。", "corrected_sentence": "妈妈每个星期定期检查冰箱里的牛奶，看看有没有过期。", "error_description": "错误：“的”使“定期检查”变成名词性结构，句中缺少谓语动词。正确应去掉“的”：“妈妈每个星期定期检查冰箱里的牛奶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
