INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19905, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不遵守规则或法律，做了不允许做的事。", "primary_collocate": null, "pronunciation": "wéi fǎn", "ipa": "weɪ˧˥ fan˨˩˦", "syllable_count": 2, "sentences": [{"text": "员工需要接受培训，了解隐私保护的重要性，并知道违反规则的后果。", "target_word": "违反", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "开车时打电话违反交通规则。", "target_word": "违反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他违反了学校的规定，老师批评了他。", "target_word": "违反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "违反法律的人要受到处罚。", "target_word": "违反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在图书馆大声说话违反规定。", "target_word": "违反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司不允许员工违反合同。", "target_word": "违反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这样做违反了我们的约定。", "target_word": "违反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来没有违反过交通规则。", "target_word": "违反", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判让违反规则的球员下场了。", "target_word": "违反", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个做法违反了法律，所以不能用。", "target_word": "违反", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "违反了", "label": "体标"}, {"form": "违反过", "label": "体标"}, {"form": "違反", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：不遵守规则、法律、规定、合同，做了不允许的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c12968ab-dfb2-45a1-8c6f-73fe3fd501b9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19905, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "违反", "is_correct": true, "explanation": "违反：不遵守规则，做了不允许做的事，符合“知道……规则的后果”的语境。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮料，“喝规则”句意荒谬。"}, {"text": "收取", "is_correct": false, "explanation": "搭配：“收取”的宾语是费用、押金，不能说“收取规则”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱指发出乐音，“唱规则”的后果不成立，句意荒谬。"}], "explanations": {"违反": "违反：不遵守规则，做了不允许做的事，符合“知道……规则的后果”的语境。", "喝": "语义：“喝”的对象是饮料，“喝规则”句意荒谬。", "收取": "搭配：“收取”的宾语是费用、押金，不能说“收取规则”。", "唱": "语义：唱指发出乐音，“唱规则”的后果不成立，句意荒谬。"}, "sentence_index": 0, "correct_answer": "违反"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他故意违反了公共设施。", "explanation": "这里应该用〈破坏〉。违反的对象是规则或法律，公共设施是物件，只能破坏。"}, {"text": "他一气之下把那堵墙违反了。", "explanation": "这里应该用〈拆〉。违反的对象是规则或法律，墙是物件，应该说“拆”。"}, {"text": "士兵奋力违反敌人。", "explanation": "这里应该用〈抵抗〉。违反的对象是规则，不能是敌人，应该用〈抵抗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19905, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "违反", "is_correct": true, "explanation": "违反：不遵守规则或约定，做了不允许做的事，符合“这样做……了我们的约定”的语境。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：“吃掉”指把食物咽下去，与“约定”无关，句意荒谬。"}, {"text": "洗干净", "is_correct": false, "explanation": "语义：“洗干净”用于衣物、器具，不能用于约定，句意荒谬。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指赏识美好的事物，不能用来处理约定，句意不通。"}], "explanations": {"违反": "违反：不遵守规则或约定，做了不允许做的事，符合“这样做……了我们的约定”的语境。", "吃掉": "语义：“吃掉”指把食物咽下去，与“约定”无关，句意荒谬。", "洗干净": "语义：“洗干净”用于衣物、器具，不能用于约定，句意荒谬。", "欣赏": "语义：“欣赏”指赏识美好的事物，不能用来处理约定，句意不通。"}, "sentence_index": 6, "correct_answer": "违反"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用证据违反了自己的清白。", "explanation": "这里应该用〈证明〉。清白要靠证据证明，违反的对象是规则，不能是清白。"}, {"text": "警察应该违反市民的安全。", "explanation": "这里应该用〈保护〉。违反针对规则，警察应保护的是市民的安全。"}, {"text": "他违反了朋友的邀请。", "explanation": "这里应该用〈拒绝〉。拒绝的对象是邀请，违反针对规则，不能用于邀请。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19905, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他违反得学校的纪律。", "corrected_sentence": "他违反了学校的纪律。", "error_description": "补语错误：“违反”后应接动态助词“了”，表示动作完成。误用结构助词“得”，后面需要补语，不能直接带宾语。应改为“违反了学校的纪律”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19905, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在考试中作弊，严重违反得学校的纪律。", "corrected_sentence": "他在考试中作弊，严重违反了学校的纪律。", "error_description": "补语错误：“违反”后应接动态助词“了”，表示动作完成。写成“违反得”把它当成程度补语，不合语法，应改为“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff36a586-0261-4afb-a08e-4606642a5be4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19906, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19906, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19906, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情发展最后产生的结果，多指不好的结局。", "primary_collocate": null, "pronunciation": "hòu guǒ", "ipa": "xou˥˩ kuo˨˩˦", "syllable_count": 2, "sentences": [{"text": "员工需要接受培训，了解隐私保护的重要性，并知道违反规则的后果。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "做事以前，先想一想后果。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不听医生的话，后果很严重。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车喝酒会有什么后果？", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要为自己的错误负责，也要接受后果。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的后果，我们谁也没想到。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不写作业，后果是老师会生气。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早就知道迟到的后果，所以今天提前出门了。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不遵守交通规则，可能带来很坏的后果。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个错误造成的后果，一年后才看出来。", "target_word": "后果", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个后果", "label": "量词"}, {"form": "後果", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事情发展最终产生的不好的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0340599b-d1b3-4420-a126-e8eea9bfd3af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19906, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "后果", "is_correct": true, "explanation": "正确：后果指违反规则之后产生的不好结局，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色与违反规则的结果无关，句意不通。"}, {"text": "优点", "is_correct": false, "explanation": "语义：优点是正面评价，与“违反规则”的负面语境相反。"}, {"text": "印象", "is_correct": false, "explanation": "搭配：“违反规则”之后接的是结果、处罚一类的名词，“印象”不能与“违反规则”搭配。"}], "explanations": {"后果": "正确：后果指违反规则之后产生的不好结局，与句意相符。", "颜色": "语义：颜色与违反规则的结果无关，句意不通。", "优点": "语义：优点是正面评价，与“违反规则”的负面语境相反。", "印象": "搭配：“违反规则”之后接的是结果、处罚一类的名词，“印象”不能与“违反规则”搭配。"}, "sentence_index": 0, "correct_answer": "后果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的后果很高，有一米八。", "explanation": "这里应该用〈身高〉。后果指事情发展产生的结果，不能用来说人的身高。"}, {"text": "他迟到的后果是路上堵车了。", "explanation": "后果指的是产生的结果，不是原因。这里堵车是迟到的原因，应该用〈原因〉。"}, {"text": "这部电影的后果很长，我看了三个小时。", "explanation": "这里应该用〈时长〉。后果指事情发展产生的结果，不能用来说影片的长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "后果", "is_correct": true, "explanation": "正确：后果指不写作业之后引出的结果，句中“是老师会生气”正好是这个结果。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音与孩子不写作业没有直接关系，句意不通。"}, {"text": "任务", "is_correct": false, "explanation": "语义：任务是需要完成的事，老师生气不是孩子要完成的任务。"}, {"text": "体会", "is_correct": false, "explanation": "搭配：“体会”一般接感受、经验，不能引出“老师会生气”这类后续结果。"}], "explanations": {"后果": "正确：后果指不写作业之后引出的结果，句中“是老师会生气”正好是这个结果。", "声音": "语义：声音与孩子不写作业没有直接关系，句意不通。", "任务": "语义：任务是需要完成的事，老师生气不是孩子要完成的任务。", "体会": "搭配：“体会”一般接感受、经验，不能引出“老师会生气”这类后续结果。"}, "sentence_index": 6, "correct_answer": "后果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次运动会的后果很长，我们玩了一整天。", "explanation": "这里应该用〈时长〉。后果指事情产生的结果，不能用来说活动持续的时间。"}, {"text": "我把这个后果送给了朋友。", "explanation": "后果指事情发展的结果，不能当作东西送人，这里应该用〈礼物〉。"}, {"text": "这件事的后果是用邮件通知大家的。", "explanation": "后果指事情造成的结果，不能指通知的方式，这里应该用〈方式〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只后果谁都不想看到。", "corrected_sentence": "这种后果谁都不想看到。", "error_description": "量词错误：“后果”的量词应为“种”（或“个”）。“只”用于动物等，不能修饰“后果”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不复习地后果很严重。", "corrected_sentence": "他不复习的后果很严重。", "error_description": "结构助词错误：修饰名词“后果”应用“的”，“地”用于修饰动词、形容词，写成“地后果”不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
