INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19907, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对财务账目、报表等进行审查和核实，以确认其真实性和合规性。", "primary_collocate": null, "pronunciation": "shěn jì", "ipa": "ʂən˨˩˦ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "请第三方审计账目，可以帮助发现漏洞。", "target_word": "审计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们刚把这家店的账目审计完。", "target_word": "审计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司每年都请外部人员审计账目。", "target_word": "审计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们正在审计这家银行的财务报表。", "target_word": "审计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司去年审计过三次。", "target_word": "审计", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会计师审计了公司的全部账本。", "target_word": "审计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校要审计这笔经费的使用情况。", "target_word": "审计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府决定审计所有的公共项目。", "target_word": "审计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请专业机构审计，结果才更可信。", "target_word": "审计", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理要求财务部门审计这个月的支出。", "target_word": "审计", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "审计了", "label": "体标"}, {"form": "审计过", "label": "体标"}, {"form": "审计师", "label": "复合"}, {"form": "审计报告", "label": "复合"}, {"form": "審計", "label": "繁体"}], "register": "正式", "sense_fingerprint": "审查并核实财务账目、报表，确认其真实合规", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '228a4112-dbe4-4f55-9364-4edc773aa3f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19907, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审计", "is_correct": true, "explanation": "正确：“审计”指独立核查财务账目，句中指请第三方核查账目，能帮助发现漏洞。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”指装饰房屋，不能用来发现漏洞。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”指测验知识，与发现漏洞的核查作用不符。"}, {"text": "演讲", "is_correct": false, "explanation": "语义：“演讲”指公开讲话，不能用来查找漏洞。"}], "explanations": {"审计": "正确：“审计”指独立核查财务账目，句中指请第三方核查账目，能帮助发现漏洞。", "装修": "搭配：“装修”指装饰房屋，不能用来发现漏洞。", "考试": "语义：“考试”指测验知识，与发现漏洞的核查作用不符。", "演讲": "语义：“演讲”指公开讲话，不能用来查找漏洞。"}, "sentence_index": 0, "correct_answer": "审计"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生正在审计他的心脏，看看有没有问题。", "explanation": "这里应该用〈检查〉。审计专指对账目、财务报表的核实，不能用于人的身体。"}, {"text": "编辑正在审计这篇文章的内容。", "explanation": "这里应该用〈审查〉。审计只针对账目和财务报表，文章内容不属于审计对象。"}, {"text": "工人正在审计这台机器的油漆。", "explanation": "这里应该用〈刷〉。审计只用于账目、报表的核实，给机器刷油漆应说刷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19907, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审计", "is_correct": true, "explanation": "正确：“审计”指核查财务使用情况，句中是对经费使用情况的核查。"}, {"text": "批改", "is_correct": false, "explanation": "语义：“批改”指修改作业或文稿，与经费的使用情况无关。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”用于树枝、头发等，不能与“使用情况”搭配。"}, {"text": "演唱", "is_correct": false, "explanation": "语义：“演唱”指唱歌，与“经费”完全无关。"}], "explanations": {"审计": "正确：“审计”指核查财务使用情况，句中是对经费使用情况的核查。", "批改": "语义：“批改”指修改作业或文稿，与经费的使用情况无关。", "修剪": "搭配：“修剪”用于树枝、头发等，不能与“使用情况”搭配。", "演唱": "语义：“演唱”指唱歌，与“经费”完全无关。"}, "sentence_index": 6, "correct_answer": "审计"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察正在审计这个嫌疑人。", "explanation": "这里应该用〈审讯〉。审讯是对人进行审问，审计只用于账目等的核实。"}, {"text": "工程师正在审计这座桥的高度。", "explanation": "这里应该用〈测量〉。审计用于财务核实，量取物体的高度应说测量。"}, {"text": "海关正在审计旅客的身份。", "explanation": "这里应该用〈核实〉。审计专指对账目和财务报表的核查，核实身份不属于审计。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19907, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们正在审计了那家公司的账目。", "corrected_sentence": "他们正在审计那家公司的账目。", "error_description": "错误：“正在”与“了”同用。“正在”表示动作进行中，“了”表示动作完成，二者不能同时用于“审计”。正确应为“他们正在审计那家公司的账目”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19907, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把这份报表审计。", "corrected_sentence": "他们把这份报表审计了。", "error_description": "错误：“把”字句中动词后要带“了”或其他成分，不能只说“审计”。正确形式为“他们把这份报表审计了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4ef227a-ccf3-4885-bd62-7a306efce275') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
