INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19909, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一整年或每一年的期间。", "primary_collocate": null, "pronunciation": "nián dù", "ipa": "njɛn˧˥ tu˥˩", "syllable_count": 2, "sentences": [{"text": "公开年度透明度报告，能让公众更信任服务。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "公司下周要开年度会议。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我们公司的年度计划。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家选他做年度最佳员工。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年度预算已经定好了。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在年度总结里写了很多建议。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的年度销售额很高。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年度考试在十二月举行。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的年度检查安排在春天。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年度报告会告诉大家公司赚了多少钱。", "target_word": "年度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "年度报告", "label": "复合"}, {"form": "年度计划", "label": "复合"}], "register": "书面", "sense_fingerprint": "按年划分的一年期间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0340599b-d1b3-4420-a126-e8eea9bfd3af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19909, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内部", "is_correct": false, "explanation": "语义：“内部”与“公开”相矛盾，公开的报告不能是内部的。"}, {"text": "年度", "is_correct": true, "explanation": "正确：“年度”修饰“透明度报告”，指一年一度的报告期，句意完整。"}, {"text": "私人", "is_correct": false, "explanation": "语义：“私人”与“公开”和“公众”相矛盾，句意不通。"}, {"text": "秘密", "is_correct": false, "explanation": "搭配：“公开”与“秘密”搭配不当，秘密之事无法公开。"}], "explanations": {"内部": "语义：“内部”与“公开”相矛盾，公开的报告不能是内部的。", "年度": "正确：“年度”修饰“透明度报告”，指一年一度的报告期，句意完整。", "私人": "语义：“私人”与“公开”和“公众”相矛盾，句意不通。", "秘密": "搭配：“公开”与“秘密”搭配不当，秘密之事无法公开。"}, "sentence_index": 0, "correct_answer": "年度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的年度很古老。", "explanation": "这里应该用〈历史〉。年度只指一年的期间，不能用来说城市的悠久历史。"}, {"text": "合同的年度是五年。", "explanation": "这里应该用〈年限〉。年限指规定的年数期限，年度指按年划分的一个期间，不指合同的总年数。"}, {"text": "他的年度是三十岁。", "explanation": "这里应该用〈年龄〉。年龄指人的岁数，年度不表示人的岁数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19909, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地铁", "is_correct": false, "explanation": "语义：地铁不是店铺的经营范围，“地铁销售”句意不通。"}, {"text": "年度", "is_correct": true, "explanation": "正确：“年度”修饰“销售”，指一年的销售情况，与“这家店的”搭配通顺。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是店铺的销售对象，“月亮销售”句意不通。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠与店铺经营无关，“沙漠销售”句意不通。"}], "explanations": {"地铁": "语义：地铁不是店铺的经营范围，“地铁销售”句意不通。", "年度": "正确：“年度”修饰“销售”，指一年的销售情况，与“这家店的”搭配通顺。", "月亮": "语义：月亮不是店铺的销售对象，“月亮销售”句意不通。", "沙漠": "语义：沙漠与店铺经营无关，“沙漠销售”句意不通。"}, "sentence_index": 6, "correct_answer": "年度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司每个月都做年度报告。", "explanation": "这里应该用〈月度〉。月度指按月划分的期间，每月做的报告用月度；年度指一整年，不能每月都做。"}, {"text": "这个项目的年度是三个月。", "explanation": "这里应该用〈周期〉。周期指一段持续的时间，年度指按年划分的期间，不能用来说三个月的长度。"}, {"text": "这场战争的年度很长，持续了八年。", "explanation": "这里应该用〈时期〉。年度只指一年的期间，不能用来说持续八年的战争。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19909, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正在制定年度地计划。", "corrected_sentence": "我们正在制定年度计划。", "error_description": "“年度”修饰名词“计划”时中间不应加“地”（“地”用于修饰动词、形容词）。应删去“地”，改为“年度计划”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19909, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些年度了报告都放在桌上。", "corrected_sentence": "这些年度报告都放在桌上。", "error_description": "“年度”后面不能加“了”，“了”表示动作或变化的完成，不能附在修饰名词的“年度”上。应删去“了”，改为“这些年度报告”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
