INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19910, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "说话或做事时所依据的法则或标准。", "primary_collocate": null, "pronunciation": "yuán zé", "ipa": "ɥɛn˧˥ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "总的来看，公开数据做法和算法原则，不是负担，而是建立长期信任的关键步骤。", "target_word": "原则", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他做事很有原则，从不乱收别人的钱。", "target_word": "原则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司有一条原则：客人的意见一定要认真听。", "target_word": "原则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在原则问题上，我们不能让步。", "target_word": "原则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直坚持自己的原则，所以朋友都信任他。", "target_word": "原则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生治病时，第一原则是保护病人。", "target_word": "原则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈教我，对人要诚实，这是做人的原则。", "target_word": "原则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了公平，老师按同一个原则给大家打分。", "target_word": "原则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以不同意，但不能违反学校的原则。", "target_word": "原则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他为了钱放弃了原则，大家都很失望。", "target_word": "原则", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条原则", "label": "量词"}, {"form": "原则性", "label": "复合"}, {"form": "原则上", "label": "复合"}, {"form": "原則", "label": "繁体"}], "register": "中性", "sense_fingerprint": "原则|说话做事所依据的法则或标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0340599b-d1b3-4420-a126-e8eea9bfd3af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19910, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色与做法和算法无关，句意不通。"}, {"text": "原则", "is_correct": true, "explanation": "正确：“原则”指做事依据的标准，与“做法和算法”并列，句意通顺。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能用来说明算法，句意不通。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“算法”与“尺寸”不能并列组成定语，搭配不当。"}], "explanations": {"颜色": "语义：颜色与做法和算法无关，句意不通。", "原则": "正确：“原则”指做事依据的标准，与“做法和算法”并列，句意通顺。", "味道": "语义：味道不能用来说明算法，句意不通。", "尺寸": "搭配：“算法”与“尺寸”不能并列组成定语，搭配不当。"}, "sentence_index": 0, "correct_answer": "原则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次考试的原则拿了一百分，大家都很佩服。", "explanation": "这里应该用〈成绩〉。原则指做事依据的标准，不能用来说拿了多少分，考试得分应说成绩。"}, {"text": "这件衣服的原则是红色。", "explanation": "这里应该用〈颜色〉。颜色指物体呈现的色彩，原则指做事依据的标准，不能用来说衣服的颜色。"}, {"text": "这种水果的原则很甜。", "explanation": "这里应该用〈味道〉。味道指食物入口后的感觉，原则指做事依据的标准，不能用来形容水果甜不甜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "语义：工资是报酬，与做人无关，“做人的工资”句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能说“做人的天气”。"}, {"text": "原则", "is_correct": true, "explanation": "正确：“原则”指做人依据的标准，与“对人要诚实”前后呼应，句意通顺。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“做人的体重”不成搭配，且与前文“诚实”无关。"}], "explanations": {"工资": "语义：工资是报酬，与做人无关，“做人的工资”句意不通。", "天气": "语义：天气是自然现象，不能说“做人的天气”。", "原则": "正确：“原则”指做人依据的标准，与“对人要诚实”前后呼应，句意通顺。", "体重": "搭配：“做人的体重”不成搭配，且与前文“诚实”无关。"}, "sentence_index": 6, "correct_answer": "原则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的原则已经三十岁了，周末总在家里练习。", "explanation": "这里应该用〈年龄〉。原则指做事依据的标准，不能用来说人的岁数。"}, {"text": "他的原则很重，有八十公斤。", "explanation": "这里应该用〈体重〉。体重指人身体的重量，原则指做事依据的标准，不能用来说一个人有多重。"}, {"text": "这条路的原则是通往北方。", "explanation": "这里应该用〈方向〉。方向指前进的指向，原则不表示路线的走向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他做事很原则性，从不马虎。", "corrected_sentence": "他做事很有原则性，从不马虎。", "error_description": "“很”不能直接修饰“原则性”，这里需要动词“有”，应说“很有原则性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师给学生定了一张原则。", "corrected_sentence": "老师给学生定了一条原则。", "error_description": "量词错误：“原则”应该用“条”，“张”用于纸张、桌子等平面物，不能用来数原则。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b47d65-33ae-48f4-9dd5-b381109a3281') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
