INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19912, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示动作、变化已经完成或达到某种程度。", "primary_collocate": null, "pronunciation": "yǐ", "ipa": "i˨˩˦", "syllable_count": 1, "sentences": [{"text": "天色已黑，路上没有人。", "target_word": "已", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "时间已晚，我们回家吧。", "target_word": "已", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜已深，孩子们都睡了。", "target_word": "已", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "名额已满，不能再报名了。", "target_word": "已", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪已停，太阳出来了。", "target_word": "已", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的病已好，可以上班。", "target_word": "已", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "花已开，春天来了。", "target_word": "已", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子已长大，不需要你管。", "target_word": "已", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天已亮，鸟儿开始唱歌。", "target_word": "已", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "汤已凉，我帮你热一热。", "target_word": "已", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "已经", "label": "复合"}], "register": "书面", "sense_fingerprint": "副词，用在形容词或动词前，表示变化已经完成或达到某种程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06ef7b24-878b-4d84-b099-4f00efa873d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19912, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "已", "is_correct": true, "explanation": "正确答案：已（yǐ），副词，表示变化已经完成或达到某种程度。"}, {"text": "也", "is_correct": false, "explanation": "也（yě）与已（yǐ）韵母不同（e／i），意思是“也”，不表示变化完成。"}, {"text": "姨", "is_correct": false, "explanation": "姨（yí）与已（yǐ）声调不同（第二声／第三声），意思是“阿姨”。"}, {"text": "亿", "is_correct": false, "explanation": "亿（yì）与已（yǐ）声调不同（第四声／第三声），意思是“亿”。"}, {"text": "语", "is_correct": false, "explanation": "语（yǔ）与已（yǐ）韵母不同（ü／i），意思是“语言”。"}], "explanations": {"已": "正确答案：已（yǐ），副词，表示变化已经完成或达到某种程度。", "也": "也（yě）与已（yǐ）韵母不同（e／i），意思是“也”，不表示变化完成。", "姨": "姨（yí）与已（yǐ）声调不同（第二声／第三声），意思是“阿姨”。", "亿": "亿（yì）与已（yǐ）声调不同（第四声／第三声），意思是“亿”。", "语": "语（yǔ）与已（yǐ）韵母不同（ü／i），意思是“语言”。"}, "sentence_index": null, "correct_answer": "已"}, "level_3": {"options": [{"text": "已", "is_correct": true, "explanation": "已表示天色变黑这一变化已经完成，与“路上没有人”的语境相符。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”后接动作或变化动词，不能直接修饰“黑”这样的状态形容词，“天色正在黑”不通。"}, {"text": "曾", "is_correct": false, "explanation": "语义：“曾”表示过去经历过的事，与“天色黑”的当下状态不合。"}, {"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，句中没有与之相对的内容，用在这里不通。"}], "explanations": {"已": "已表示天色变黑这一变化已经完成，与“路上没有人”的语境相符。", "正在": "搭配：“正在”后接动作或变化动词，不能直接修饰“黑”这样的状态形容词，“天色正在黑”不通。", "曾": "语义：“曾”表示过去经历过的事，与“天色黑”的当下状态不合。", "却": "语义：“却”表示转折，句中没有与之相对的内容，用在这里不通。"}, "sentence_index": 0, "correct_answer": "已"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天傍晚天色已黑，我们早点回家吧。", "explanation": "这里应该用〈将〉。已表示变化已经完成，“明天傍晚”尚未到来，不能用已，应说“明天傍晚天色将黑”。"}, {"text": "我们下星期已放假。", "explanation": "这里应该用〈要〉。已表示动作已经完成，“下星期”尚未到来，将要发生的事应说“我们下星期要放假”。"}, {"text": "他每天已早起锻炼。", "explanation": "这里应该用〈总〉。已表示变化已经完成，每天重复的习惯要用“总”，应说“他每天总早起锻炼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19912, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "已", "is_correct": true, "explanation": "正确答案：已（yǐ），副词，表示变化已经完成或达到某种程度。"}, {"text": "衣", "is_correct": false, "explanation": "衣（yī）与已（yǐ）声调不同（第一声／第三声），意思是“衣服”。"}, {"text": "移", "is_correct": false, "explanation": "移（yí）与已（yǐ）声调不同（第二声／第三声），意思是“移动”。"}, {"text": "意", "is_correct": false, "explanation": "意（yì）与已（yǐ）声调不同（第四声／第三声），意思是“意思”。"}, {"text": "雨", "is_correct": false, "explanation": "雨（yǔ）与已（yǐ）韵母不同（ü／i），意思是“雨”。"}], "explanations": {"已": "正确答案：已（yǐ），副词，表示变化已经完成或达到某种程度。", "衣": "衣（yī）与已（yǐ）声调不同（第一声／第三声），意思是“衣服”。", "移": "移（yí）与已（yǐ）声调不同（第二声／第三声），意思是“移动”。", "意": "意（yì）与已（yǐ）声调不同（第四声／第三声），意思是“意思”。", "雨": "雨（yǔ）与已（yǐ）韵母不同（ü／i），意思是“雨”。"}, "sentence_index": null, "correct_answer": "已"}, "level_3": {"options": [{"text": "已", "is_correct": true, "explanation": "已表示花已经开了，变化已经完成，与“春天来了”的语境相符。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不”表示否定，“花不开”与“春天来了”的语境相反。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”表示过去的经历，与“花开”这一当下变化不合。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”一般修饰形容词，不能直接修饰动词“开”，“花很开”不通。"}], "explanations": {"已": "已表示花已经开了，变化已经完成，与“春天来了”的语境相符。", "不": "语义：“不”表示否定，“花不开”与“春天来了”的语境相反。", "曾经": "语义：“曾经”表示过去的经历，与“花开”这一当下变化不合。", "很": "搭配：“很”一般修饰形容词，不能直接修饰动词“开”，“花很开”不通。"}, "sentence_index": 6, "correct_answer": "已"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你已喝汤，然后再吃饭。", "explanation": "这里应该用〈先〉。已表示动作已经完成，祈使句中要说先做什么，应说“请你先喝汤”。"}, {"text": "汤已就凉，你快喝吧。", "explanation": "这里应该用〈马上〉。已表示变化已经完成，不能与“就”这种表示即将发生的时间词搭配，应说“汤马上就凉”。"}, {"text": "请你已看一下。", "explanation": "这里应该用〈再〉。已表示动作已经完成，要求对方重复做某事要用“再”，应说“请你再看一下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子长已大了。", "corrected_sentence": "孩子已长大了。", "error_description": "错误：“孩子长已大了”。正确：“孩子已长大了”。“已”是副词，应放在动词“长大”之前，不能插在“长”和“大”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事是已第三次了。", "corrected_sentence": "这件事已是第三次了。", "error_description": "“已”应放在“是”之前，表示已经达到第三次，应说“这件事已是第三次了”。“是已第三次”把已放在“是”之后，位置错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
