INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19913, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指通过技术和管理措施，确保数据在存储、传输和使用过程中的安全性、完整性和可用性。", "primary_collocate": null, "pronunciation": "shù jù bǎo hù", "ipa": "ʂu˥˩ tɕy˥˩ pɑʊ˨˩˦ xu˥˩", "syllable_count": 4, "sentences": [{"text": "在全球化数字生态日益复杂的背景下，SaaS企业面临的合规挑战已从传统的数据保护范畴，延伸至训练数据来源披露与算法运作机制透明度的深层治理维度。", "target_word": "数据保护", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司很重视数据保护。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据保护对每个用户都很重要。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家出台了新政策，强调数据保护的重要性。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要加强数据保护，防止信息丢失。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行的数据保护做得很好。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习数据保护，可以让你的电脑更安全。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了数据保护，公司给每台电脑都装了软件。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院需要严格的数据保护，因为病人的资料很重要。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司负责数据保护工作。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "数据保护法", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "用技术和管理措施保障数据安全完整可用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84e52338-d86c-46e6-8c0d-e6c3d2a19ae0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19913, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数据保护", "is_correct": true, "explanation": "数据保护：指用技术和管理措施保障数据安全，与句中的合规、治理语境相合。"}, {"text": "体育", "is_correct": false, "explanation": "语义：“传统的体育范畴”与句中的SaaS企业、数字生态语境无关。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与这段书面语的语域不符。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“传统的烹饪范畴”与句中的数字生态、合规挑战语境不相符。"}], "explanations": {"数据保护": "数据保护：指用技术和管理措施保障数据安全，与句中的合规、治理语境相合。", "体育": "语义：“传统的体育范畴”与句中的SaaS企业、数字生态语境无关。", "玩意儿": "语域：“玩意儿”是口语，与这段书面语的语域不符。", "烹饪": "语义：“传统的烹饪范畴”与句中的数字生态、合规挑战语境不相符。"}, "sentence_index": 0, "correct_answer": "数据保护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司买了一台数据保护。", "explanation": "数据保护是抽象的工作，不是机器，不能用〈台〉，也不能直接“买”；可说“买了一套数据保护软件”。"}, {"text": "我们给手机买了一只数据保护。", "explanation": "数据保护是抽象的工作，不能用〈只〉计量，也不能直接“买”；可说“装了数据保护软件”。"}, {"text": "学校订了一把数据保护。", "explanation": "数据保护是抽象的工作，不能用〈把〉计量，也不能“订”；可说“订了数据保护服务”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19913, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数据保护", "is_correct": true, "explanation": "数据保护：学习数据保护能让电脑更安全，符合句意。"}, {"text": "书法", "is_correct": false, "explanation": "语义：学习书法与让电脑更安全没有关系。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“学习衣服”不是常用搭配，句子不通。"}, {"text": "歌剧", "is_correct": false, "explanation": "语义：学习歌剧与电脑安全无关。"}], "explanations": {"数据保护": "数据保护：学习数据保护能让电脑更安全，符合句意。", "书法": "语义：学习书法与让电脑更安全没有关系。", "衣服": "搭配：“学习衣服”不是常用搭配，句子不通。", "歌剧": "语义：学习歌剧与电脑安全无关。"}, "sentence_index": 6, "correct_answer": "数据保护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们买了一辆数据保护。", "explanation": "数据保护是抽象的工作，不是车辆，不能用〈辆〉，也不能直接“买”。"}, {"text": "学校订了一张数据保护。", "explanation": "数据保护是抽象的工作，不能用〈张〉计量，也不能“订”；可说“订了数据保护服务”。"}, {"text": "他的电脑装了一块数据保护。", "explanation": "数据保护是抽象的工作，不能用〈块〉计量；可说“装了数据保护软件”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19913, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个部门很重视一只数据保护。", "corrected_sentence": "这个部门很重视数据保护。", "error_description": "量词错误：“数据保护”是抽象概念，不能用“只”（只用于动物等）修饰；直接说“很重视数据保护”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19913, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家医院很重视一颗数据保护。", "corrected_sentence": "这家医院很重视数据保护。", "error_description": "量词错误：“颗”只用于粒状的东西，不能修饰“数据保护”；直接说“很重视数据保护”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f05e7d5-5a65-4a7f-99e6-119fbf78b385') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19914, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐瞒", "is_correct": true, "explanation": "隐瞒：不让人知道，与披露构成反义关系。"}, {"text": "增加", "is_correct": false, "explanation": "增加指数量变多，与披露没有对立关系。"}, {"text": "参观", "is_correct": false, "explanation": "参观指去看，与披露不构成反义。"}, {"text": "保持", "is_correct": false, "explanation": "保持指维持原状，与披露没有反义关系。"}], "correct_answer": "隐瞒", "explanations": {"隐瞒": "隐瞒：不让人知道，与披露构成反义关系。", "增加": "增加指数量变多，与披露没有对立关系。", "参观": "参观指去看，与披露不构成反义。", "保持": "保持指维持原状，与披露没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19914, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐瞒", "is_correct": true, "explanation": "隐瞒：不让人知道，与披露构成反义关系。"}, {"text": "上升", "is_correct": false, "explanation": "上升指向上移动，与披露没有对立关系。"}, {"text": "检查", "is_correct": false, "explanation": "检查指核对，与披露不构成反义。"}, {"text": "设计", "is_correct": false, "explanation": "设计指规划，与披露没有反义关系。"}], "correct_answer": "隐瞒", "explanations": {"隐瞒": "隐瞒：不让人知道，与披露构成反义关系。", "上升": "上升指向上移动，与披露没有对立关系。", "检查": "检查指核对，与披露不构成反义。", "设计": "设计指规划，与披露没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19914, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "将隐藏或未公开的信息、事实等公开出来，让人知道。", "primary_collocate": null, "pronunciation": "pī lù", "ipa": "pʰi˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "在全球化数字生态日益复杂的背景下，SaaS企业面临的合规挑战已从传统的数据保护范畴，延伸至训练数据来源披露与算法运作机制透明度的深层治理维度。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "首先，训练数据的采集与使用需满足“知情—同意”框架的实质要求，这意味着企业不能仅依赖用户协议中的概括性条款，而应通过分层披露机制，清晰说明数据将被用于模型训练的具体场景、类别及潜在影响，尤其在涉及个人敏感信息或生成式内容时，须实现可验证的用户授权路径。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "值得注意的是，透明度实践亦存在边界——过度披露可能引发模型逆向工程或恶意攻击，故企业应在安全与开放间寻求动态平衡，采用差分隐私、联邦学习等技术手段实现“有限透明”。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "公司公开披露了去年的财务数据。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行每个季度都要披露经营情况。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家企业没有披露产品的价格。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报告披露了新工厂的建设计划。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上市公司必须及时披露重要消息。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在会上披露了合作的细节。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府披露了今年的预算安排。", "target_word": "披露", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "披露了", "label": "体标"}, {"form": "披露过", "label": "体标"}, {"form": "信息披露", "label": "复合"}], "register": "书面语", "sense_fingerprint": "把未公开的信息、数据正式公布出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9731bc0-27a4-4e2f-ae72-9377691b0db9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19914, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "披露", "is_correct": true, "explanation": "披露：把未公开的信息公开，与“数据来源”搭配，句意通顺。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：浪费指白白耗费，“数据来源浪费”与透明度治理无关，句意不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：跳舞是身体活动，不能与“数据来源”搭配，句意荒谬。"}, {"text": "保护", "is_correct": false, "explanation": "搭配：“保护”指防护，数据来源不说“保护”。"}], "explanations": {"披露": "披露：把未公开的信息公开，与“数据来源”搭配，句意通顺。", "浪费": "语义：浪费指白白耗费，“数据来源浪费”与透明度治理无关，句意不通。", "跳舞": "语义：跳舞是身体活动，不能与“数据来源”搭配，句意荒谬。", "保护": "搭配：“保护”指防护，数据来源不说“保护”。"}, "sentence_index": 0, "correct_answer": "披露"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在台上披露了自己的胸膛。", "explanation": "这里应该用〈袒露〉。披露指把隐藏或未公开的信息公开出来，袒露指把身体露出来，胸膛是身体的部位，不能说“披露”。"}, {"text": "他在派对上披露了一个笑话。", "explanation": "这里应该用〈讲〉。披露只用于把隐藏的信息、事实公开，笑话是讲出来的，搭配不当。"}, {"text": "他把地图披露在桌上。", "explanation": "这里应该用〈摊开〉。披露指把隐藏或未公开的信息公开，不表示把物品铺展开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "披露", "is_correct": true, "explanation": "披露：把未公开的计划公开，与“报告”搭配，句意通顺。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：吃掉指吞食，与“建设计划”无关，句意荒谬。"}, {"text": "忍受", "is_correct": false, "explanation": "配价：“忍受”要求有感受的人作主语，“报告”不能忍受计划。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：讨厌是对人的情感，报告不能讨厌计划。"}], "explanations": {"披露": "披露：把未公开的计划公开，与“报告”搭配，句意通顺。", "吃掉": "语义：吃掉指吞食，与“建设计划”无关，句意荒谬。", "忍受": "配价：“忍受”要求有感受的人作主语，“报告”不能忍受计划。", "讨厌": "语义：讨厌是对人的情感，报告不能讨厌计划。"}, "sentence_index": 6, "correct_answer": "披露"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把毯子披露在肩上。", "explanation": "这里应该用〈披上〉。披露指把信息公开，不表示把东西披在身上，毯子披在肩上应说“披上”。"}, {"text": "他故意披露了这件事，谁也不让知道。", "explanation": "这里应该用〈隐瞒〉。披露是把事情公开，与“谁也不让知道”自相矛盾。"}, {"text": "他把书披露在床上，然后去睡觉了。", "explanation": "这里应该用〈放〉。披露指把信息公开，不表示把物品放在某处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司已经把事故原因披露起来了。", "corrected_sentence": "公司已经把事故原因披露出来了。", "error_description": "“披露”后应接趋向补语“出来”，表示把隐藏的信息公开出来；“起来”不能接在“披露”后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司去年披露着财务数据。", "corrected_sentence": "这家公司去年披露了财务数据。", "error_description": "“去年”表示已经完成的动作，“披露”后应用表示完成的“了”。“着”表示持续，不能用在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19915, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "引申", "is_correct": true, "explanation": "引申：由字面义延伸出的意思，与字面义相对。"}, {"text": "颜色", "is_correct": false, "explanation": "颜色与字面义没有对立关系。"}, {"text": "声音", "is_correct": false, "explanation": "声音与字面义不构成反义。"}, {"text": "时间", "is_correct": false, "explanation": "时间与字面义没有反义关系。"}], "correct_answer": "引申", "explanations": {"引申": "引申：由字面义延伸出的意思，与字面义相对。", "颜色": "颜色与字面义没有对立关系。", "声音": "声音与字面义不构成反义。", "时间": "时间与字面义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19915, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "引申", "is_correct": true, "explanation": "引申：由字面义延伸出的意思，与字面义相对。"}, {"text": "数量", "is_correct": false, "explanation": "数量与字面义没有对立关系。"}, {"text": "季节", "is_correct": false, "explanation": "季节与字面义不构成反义。"}, {"text": "方法", "is_correct": false, "explanation": "方法与字面义没有反义关系。"}], "correct_answer": "引申", "explanations": {"引申": "引申：由字面义延伸出的意思，与字面义相对。", "数量": "数量与字面义没有对立关系。", "季节": "季节与字面义不构成反义。", "方法": "方法与字面义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19915, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "字面指词语或句子直接表达出的、不隐含比喻或引申义的意思。", "primary_collocate": null, "pronunciation": "zì miàn", "ipa": "tsɿ˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "此类义务不仅涉及法律文本的字面遵循，更要求企业构建一套贯穿产品生命周期的伦理—合规架构。", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这句话的字面意思很简单。", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要只看字面意思。", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从字面上看，这个词很容易懂。", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个成语的字面意思是什么？", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只看懂了字面意思，没有听出暗示。", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "合同的字面意思和实际做法不同。", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "翻译时不能只照字面翻。", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗的字面意思平淡，但意境很深。", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "字面上的意思我懂，但他想说什么我不明白。", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "字面上", "label": "复合"}, {"form": "字面意思", "label": "复合"}, {"form": "字面意义", "label": "复合"}], "register": "中性", "sense_fingerprint": "词句直接表达的、不含比喻或引申的意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9731bc0-27a4-4e2f-ae72-9377691b0db9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19915, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "字面", "is_correct": true, "explanation": "字面：指法律文本的直接字义，与“遵循”搭配，句意通顺。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数指字的多少，与“遵循”的对象无关。"}, {"text": "字体", "is_correct": false, "explanation": "语义：字体指字形样式，不能用来遵循法律文本。"}, {"text": "规模", "is_correct": false, "explanation": "搭配：“遵循”的对象是规则、原则，不说遵循“规模”。"}], "explanations": {"字面": "字面：指法律文本的直接字义，与“遵循”搭配，句意通顺。", "字数": "语义：字数指字的多少，与“遵循”的对象无关。", "字体": "语义：字体指字形样式，不能用来遵循法律文本。", "规模": "搭配：“遵循”的对象是规则、原则，不说遵循“规模”。"}, "sentence_index": 0, "correct_answer": "字面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗的字面很深，值得细读。", "explanation": "这里应该用〈含义〉。字面指词句直接表达的意思，说“深”要用“含义”。"}, {"text": "他的字面很工整，老师表扬了他。", "explanation": "这里应该用〈字迹〉。字面指意思，不指写出来的字的样子。"}, {"text": "书后的字面列出了所有生词。", "explanation": "这里应该用〈字表〉。字面指词句的意思，不指词表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19915, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "字面", "is_correct": true, "explanation": "字面：指合同条文的直接意思，与“实际做法”形成对比，句意通顺。"}, {"text": "语音", "is_correct": false, "explanation": "语义：语音指发音，与“实际做法”的对比无关。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“意思”前不用“颜色”修饰。"}, {"text": "数字", "is_correct": false, "explanation": "语义：数字不能与“实际做法”构成意思上的对比，句意荒谬。"}], "explanations": {"字面": "字面：指合同条文的直接意思，与“实际做法”形成对比，句意通顺。", "语音": "语义：语音指发音，与“实际做法”的对比无关。", "颜色": "搭配：“意思”前不用“颜色”修饰。", "数字": "语义：数字不能与“实际做法”构成意思上的对比，句意荒谬。"}, "sentence_index": 6, "correct_answer": "字面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把字面藏进抽屉，谁也找不到。", "explanation": "这里应该用〈字条〉。字面是抽象的意思，不是纸条，不能藏进抽屉。"}, {"text": "他的字面很红，大概是喝醉了。", "explanation": "这里应该用〈脸色〉。字面指词句的意思，不指脸色。"}, {"text": "这篇文章的字面很长，我读了一天。", "explanation": "这里应该用〈篇幅〉。字面指意思，不能用长短来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19915, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "从字面看上，这句话并不难懂。", "corrected_sentence": "从字面上看，这句话并不难懂。", "error_description": "“字面上”的“上”应紧跟“字面”，写作“从字面上看”；“上”放在“看”后是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19915, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "翻译时不能只字面意思来理解。", "corrected_sentence": "翻译时不能只按字面意思来理解。", "error_description": "“字面意思”前缺少介词“按”，“只字面意思来理解”不通；应写作“只按字面意思来理解”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
