INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19916, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "知道某件事的内情或真相。", "primary_collocate": null, "pronunciation": "zhī qíng", "ipa": "ʈʂɻ̩˥ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "首先，训练数据的采集与使用需满足“知情—同意”框架的实质要求，这意味着企业不能仅依赖用户协议中的概括性条款，而应通过分层披露机制，清晰说明数据将被用于模型训练的具体场景、类别及潜在影响，尤其在涉及个人敏感信息或生成式内容时，须实现可验证的用户授权路径。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这件事我完全不知情。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是唯一知情的人。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的人对此并不知情。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察想问问知情的邻居。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知情却不说，这样不好。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们对家里的困难不知情。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当时只有两个人知情。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说自己事先并不知情。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "知情的同事都不愿意说话。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不知情", "label": "否定"}, {"form": "知情人", "label": "复合"}, {"form": "知情权", "label": "复合"}], "register": "中性", "sense_fingerprint": "知道某件事的内情或真相", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9731bc0-27a4-4e2f-ae72-9377691b0db9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19916, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "知情", "is_correct": true, "explanation": "正确：知情 zhī qíng，指知道某件事的内情或真相。"}, {"text": "知青", "is_correct": false, "explanation": "知青 zhī qīng 与 知情 第二音节声调不同（阴平与阳平），意思是知识青年。"}, {"text": "痴情", "is_correct": false, "explanation": "痴情 chī qíng 与 知情 声母不同（ch 与 zh），意思是深切的感情。"}, {"text": "诗情", "is_correct": false, "explanation": "诗情 shī qíng 与 知情 声母不同（sh 与 zh），意思是诗意的情感。"}, {"text": "知名", "is_correct": false, "explanation": "知名 zhī míng 与 知情 第二音节声母不同（m 与 q），意思是有名气。"}], "explanations": {"知情": "正确：知情 zhī qíng，指知道某件事的内情或真相。", "知青": "知青 zhī qīng 与 知情 第二音节声调不同（阴平与阳平），意思是知识青年。", "痴情": "痴情 chī qíng 与 知情 声母不同（ch 与 zh），意思是深切的感情。", "诗情": "诗情 shī qíng 与 知情 声母不同（sh 与 zh），意思是诗意的情感。", "知名": "知名 zhī míng 与 知情 第二音节声母不同（m 与 q），意思是有名气。"}, "sentence_index": null, "correct_answer": "知情"}, "level_3": {"options": [{"text": "知情", "is_correct": true, "explanation": "正确：“知情—同意”是固定术语，指在知悉相关信息的前提下作出的同意。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：句中要求“分层披露”和“清晰说明”，与“隐瞒”的意思相反。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：句中明确要求企业不能仅依赖概括性条款，忽略与此矛盾。"}, {"text": "猜测", "is_correct": false, "explanation": "搭配：“猜测—同意”不构成术语，句中要求的是可验证的授权路径，不能靠猜测。"}], "explanations": {"知情": "正确：“知情—同意”是固定术语，指在知悉相关信息的前提下作出的同意。", "隐瞒": "语义：句中要求“分层披露”和“清晰说明”，与“隐瞒”的意思相反。", "忽略": "语义：句中明确要求企业不能仅依赖概括性条款，忽略与此矛盾。", "猜测": "搭配：“猜测—同意”不构成术语，句中要求的是可验证的授权路径，不能靠猜测。"}, "sentence_index": 0, "correct_answer": "知情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我知情他的电话号码，所以能随时打给他。", "explanation": "这里应该用〈知道〉。知情不能直接带“电话号码”这样的宾语，要说“知道他的电话号码”。"}, {"text": "他这次考试很知情，成绩一定很好。", "explanation": "这里应该用〈认真〉。知情指知道内情，不能用来形容学习的态度。"}, {"text": "我很知情你的性格，所以才这样说。", "explanation": "这里应该用〈了解〉。知情不带“性格”这类宾语，表示了解一个人要用“了解”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19916, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "知情", "is_correct": true, "explanation": "正确：知情 zhī qíng，指知道某件事的内情或真相。"}, {"text": "知行", "is_correct": false, "explanation": "知行 zhī xíng 与 知情 第二音节声母不同（x 与 q），意思是认识与实践。"}, {"text": "事情", "is_correct": false, "explanation": "事情 shì qíng 与 知情 第一音节声母与声调都不同（sh 与 zh，第四声与第一声），意思是事件或情况。"}, {"text": "实情", "is_correct": false, "explanation": "实情 shí qíng 与 知情 第一音节声母与声调不同（sh 与 zh，第二声与第一声），意思是实际的情况。"}, {"text": "真情", "is_correct": false, "explanation": "真情 zhēn qíng 与 知情 第一音节韵母不同（en 与 i），意思是真实的感情。"}, {"text": "深情", "is_correct": false, "explanation": "深情 shēn qíng 与 知情 第一音节声母与韵母都不同（sh、en 与 zh、i），意思是深厚的感情。"}, {"text": "私情", "is_correct": false, "explanation": "私情 sī qíng 与 知情 第一音节声母不同（s 与 zh），意思是私人的感情或私下的交情。"}], "explanations": {"知情": "正确：知情 zhī qíng，指知道某件事的内情或真相。", "知行": "知行 zhī xíng 与 知情 第二音节声母不同（x 与 q），意思是认识与实践。", "事情": "事情 shì qíng 与 知情 第一音节声母与声调都不同（sh 与 zh，第四声与第一声），意思是事件或情况。", "实情": "实情 shí qíng 与 知情 第一音节声母与声调不同（sh 与 zh，第二声与第一声），意思是实际的情况。", "真情": "真情 zhēn qíng 与 知情 第一音节韵母不同（en 与 i），意思是真实的感情。", "深情": "深情 shēn qíng 与 知情 第一音节声母与韵母都不同（sh、en 与 zh、i），意思是深厚的感情。", "私情": "私情 sī qíng 与 知情 第一音节声母不同（s 与 zh），意思是私人的感情或私下的交情。"}, "sentence_index": null, "correct_answer": "知情"}, "level_3": {"options": [{"text": "知情", "is_correct": true, "explanation": "正确：“不知情”指不了解内情，与句中“家里的困难”所指的情况相合。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受”含有喜爱、愉悦之意，“对困难不享受”与句意相悖。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象多为作品、风景，不能说“欣赏困难”。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”的对象是人或事物的优点，不能用于“困难”。"}], "explanations": {"知情": "正确：“不知情”指不了解内情，与句中“家里的困难”所指的情况相合。", "享受": "语义：“享受”含有喜爱、愉悦之意，“对困难不享受”与句意相悖。", "欣赏": "搭配：“欣赏”的对象多为作品、风景，不能说“欣赏困难”。", "赞美": "搭配：“赞美”的对象是人或事物的优点，不能用于“困难”。"}, "sentence_index": 6, "correct_answer": "知情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我知情他的生日，所以提前准备了礼物。", "explanation": "这里应该用〈记得〉。知情指知道内情或真相，不能带“生日”这类个人信息作宾语，应说“记得他的生日”。"}, {"text": "这个苹果很知情，又甜又脆。", "explanation": "这里应该用〈新鲜〉。知情指知道内情，不能用来形容食物。"}, {"text": "这台电脑很知情，用起来很顺手。", "explanation": "这里应该用〈智能〉。知情指知道内情，不能用来形容物品的功能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都对这件事了知情。", "corrected_sentence": "大家都对这件事知情。", "error_description": "错误：“了”放在“知情”之前，不能说“了知情”。“知情”是动词，“了”不能放在动词前面，此处应说“大家都对这件事知情”，去掉动词前的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事孩子们都了不知情。", "corrected_sentence": "这件事孩子们都不知情。", "error_description": "错误：“了”放在否定词“不”之前，不能说“都了不知情”，应说“都不知情”，去掉“不”前面多余的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19917, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "正确：反对与同意（表示认可、赞成）构成反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "与同意无反义关系，“散步”是一种活动。"}, {"text": "打扫", "is_correct": false, "explanation": "与同意无反义关系，“打扫”指清理场所。"}, {"text": "购买", "is_correct": false, "explanation": "与同意无反义关系，“购买”指付钱获得物品。"}], "correct_answer": "反对", "explanations": {"反对": "正确：反对与同意（表示认可、赞成）构成反义关系。", "散步": "与同意无反义关系，“散步”是一种活动。", "打扫": "与同意无反义关系，“打扫”指清理场所。", "购买": "与同意无反义关系，“购买”指付钱获得物品。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19917, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "正确：反对与同意（表示认可、赞成）构成反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "与同意无反义关系，“跑步”是一种运动。"}, {"text": "收拾", "is_correct": false, "explanation": "与同意无反义关系，“收拾”指整理。"}, {"text": "游泳", "is_correct": false, "explanation": "与同意无反义关系，“游泳”是一种运动。"}], "correct_answer": "反对", "explanations": {"反对": "正确：反对与同意（表示认可、赞成）构成反义关系。", "跑步": "与同意无反义关系，“跑步”是一种运动。", "收拾": "与同意无反义关系，“收拾”指整理。", "游泳": "与同意无反义关系，“游泳”是一种运动。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19917, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指对某件事情或某个看法表示认可、赞成，双方意见一致。", "primary_collocate": null, "pronunciation": "tóng yì", "ipa": "tʰʊŋ³⁵ i⁵¹", "syllable_count": 2, "sentences": [{"text": "首先，训练数据的采集与使用需满足“知情—同意”框架的实质要求，这意味着企业不能仅依赖用户协议中的概括性条款，而应通过分层披露机制，清晰说明数据将被用于模型训练的具体场景、类别及潜在影响，尤其在涉及个人敏感信息或生成式内容时，须实现可验证的用户授权路径。", "target_word": "同意", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "妈妈同意我周末去朋友家玩。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师不同意我们明天考试。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理同意了我的请假申请。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你同意这个办法吗？", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直不同意搬到别的城市住。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生同意他明天出院。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房东同意把房租少收一百块。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我问了爸爸，他很快就同意了。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的计划，公司已经同意了。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "同意了", "label": "体标"}, {"form": "不同意", "label": "否定"}, {"form": "同意书", "label": "复合"}], "register": "中性", "sense_fingerprint": "对事情或看法表示认可、赞成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 7 above tier T1: 3 words above tier T1 (max 2): 房东 (Zipf 3.86), 房租 (Zipf 3.92), 一百块 (Zipf 3.13)']::text[], 'b9731bc0-27a4-4e2f-ae72-9377691b0db9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19917, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同意", "is_correct": true, "explanation": "正确：同意 tóng yì，指对某件事或某个看法表示认可、赞成。"}, {"text": "同事", "is_correct": false, "explanation": "同事 tóng shì 与 同意 第二音节声母不同（sh 与 y），意思是共事的人。"}, {"text": "同一", "is_correct": false, "explanation": "同一 tóng yī 与 同意 第二音节声调不同（第一声与第四声），意思是相同的。"}, {"text": "中意", "is_correct": false, "explanation": "中意 zhōng yì 与 同意 第一音节声母与声调不同（zh 与 t，第一声与第二声），意思是满意、喜欢。"}, {"text": "同理", "is_correct": false, "explanation": "同理 tóng lǐ 与 同意 第二音节声母与声调不同（l 与 y，第三声与第四声），意思是同样的道理。"}, {"text": "同日", "is_correct": false, "explanation": "同日 tóng rì 与 同意 第二音节声母不同（r 与零声母），意思是同一天。"}], "explanations": {"同意": "正确：同意 tóng yì，指对某件事或某个看法表示认可、赞成。", "同事": "同事 tóng shì 与 同意 第二音节声母不同（sh 与 y），意思是共事的人。", "同一": "同一 tóng yī 与 同意 第二音节声调不同（第一声与第四声），意思是相同的。", "中意": "中意 zhōng yì 与 同意 第一音节声母与声调不同（zh 与 t，第一声与第二声），意思是满意、喜欢。", "同理": "同理 tóng lǐ 与 同意 第二音节声母与声调不同（l 与 y，第三声与第四声），意思是同样的道理。", "同日": "同日 tóng rì 与 同意 第二音节声母不同（r 与零声母），意思是同一天。"}, "sentence_index": null, "correct_answer": "同意"}, "level_3": {"options": [{"text": "同意", "is_correct": true, "explanation": "正确：“知情—同意”是固定术语，指在知情的基础上表示认可。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“知情—删除”不成术语，与句中的授权路径不相合。"}, {"text": "分析", "is_correct": false, "explanation": "语义：句意是规定用户授权，而不是对数据做分析。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，与授权框架无关。"}], "explanations": {"同意": "正确：“知情—同意”是固定术语，指在知情的基础上表示认可。", "删除": "搭配：“知情—删除”不成术语，与句中的授权路径不相合。", "分析": "语义：句意是规定用户授权，而不是对数据做分析。", "翻译": "语义：“翻译”指转换语言，与授权框架无关。"}, "sentence_index": 0, "correct_answer": "同意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司同意了他的能力。", "explanation": "这里应该用〈认可〉。同意用于请求、计划、意见，不能用于“能力”这类属性。"}, {"text": "他同意了这个错误。", "explanation": "这里应该用〈承认〉。同意是接受请求或建议，不能用来指承认错误。"}, {"text": "我同意你的帮助。", "explanation": "这里应该用〈感谢〉。同意不能用于“帮助”这类人际行为的回应。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19917, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同意", "is_correct": true, "explanation": "正确：“医生同意他明天出院”表示医生认可他出院。"}, {"text": "游览", "is_correct": false, "explanation": "语义：“游览”指参观景物，与医生决定患者出院无关。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是作品或风景，不能用于“出院”这样的事件。"}, {"text": "收割", "is_correct": false, "explanation": "语义：“收割”指收取农作物，与医生的决定毫不相关。"}], "explanations": {"同意": "正确：“医生同意他明天出院”表示医生认可他出院。", "游览": "语义：“游览”指参观景物，与医生决定患者出院无关。", "欣赏": "搭配：“欣赏”的对象是作品或风景，不能用于“出院”这样的事件。", "收割": "语义：“收割”指收取农作物，与医生的决定毫不相关。"}, "sentence_index": 6, "correct_answer": "同意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我同意了一碗面条，吃得很饱。", "explanation": "这里应该用〈吃〉。同意指赞成请求或看法，不能以食物为对象。"}, {"text": "他每天早上都同意半个小时。", "explanation": "这里应该用〈跑步〉。同意是表示赞成，不是一种可以持续进行的活动。"}, {"text": "老师同意了他的脾气。", "explanation": "这里应该用〈忍受〉。同意不能用于“脾气”这类性格特点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19917, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们俩都了同意他的说法。", "corrected_sentence": "我们俩都同意他的说法。", "error_description": "错误：“了”放在“同意”之前，不能说“都了同意他的说法”，应说“都同意他的说法”，“了”不能放在动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19917, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生已经了同意他出院。", "corrected_sentence": "医生已经同意他出院。", "error_description": "错误：“了”放在“同意”之前，不能说“已经了同意他出院”，应说“已经同意他出院”，“了”不能放在动词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19918, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "具体性", "is_correct": true, "explanation": "具体性与概括性相对：概括性指归纳共同点，具体性指细节明确、针对个别事物。"}, {"text": "连续性", "is_correct": false, "explanation": "与概括性无反义关系：连续性指时间或空间上不间断的特性。"}, {"text": "时效性", "is_correct": false, "explanation": "与概括性无反义关系：时效性指在一定时间内有效的特性。"}, {"text": "可靠性", "is_correct": false, "explanation": "与概括性无反义关系：可靠性指值得信赖、不易出错的特性。"}], "correct_answer": "具体性", "explanations": {"具体性": "具体性与概括性相对：概括性指归纳共同点，具体性指细节明确、针对个别事物。", "连续性": "与概括性无反义关系：连续性指时间或空间上不间断的特性。", "时效性": "与概括性无反义关系：时效性指在一定时间内有效的特性。", "可靠性": "与概括性无反义关系：可靠性指值得信赖、不易出错的特性。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19918, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "具体性", "is_correct": true, "explanation": "具体性与概括性相对：概括性指归纳共同点，具体性指细节明确、针对个别事物。"}, {"text": "流动性", "is_correct": false, "explanation": "与概括性无反义关系：流动性指事物能够移动、变化的特性。"}, {"text": "独立性", "is_correct": false, "explanation": "与概括性无反义关系：独立性指不依附他人或事物的特性。"}, {"text": "稳定性", "is_correct": false, "explanation": "与概括性无反义关系：稳定性指不易发生变化的特性。"}], "correct_answer": "具体性", "explanations": {"具体性": "具体性与概括性相对：概括性指归纳共同点，具体性指细节明确、针对个别事物。", "流动性": "与概括性无反义关系：流动性指事物能够移动、变化的特性。", "独立性": "与概括性无反义关系：独立性指不依附他人或事物的特性。", "稳定性": "与概括性无反义关系：稳定性指不易发生变化的特性。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19918, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指对事物共同特征进行归纳和总结的特性。", "primary_collocate": null, "pronunciation": "gài kuò xìng", "ipa": "kaɪ⁵¹ kʰuɔ⁵¹ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "首先，训练数据的采集与使用需满足“知情—同意”框架的实质要求，这意味着企业不能仅依赖用户协议中的概括性条款，而应通过分层披露机制，清晰说明数据将被用于模型训练的具体场景、类别及潜在影响，尤其在涉及个人敏感信息或生成式内容时，须实现可验证的用户授权路径。", "target_word": "概括性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个标题的概括性很强。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的发言很有概括性。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话太有概括性了，没有细节。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这篇文章的概括性不够。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总结要有概括性，不能写得太长。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词的概括性比较强，能说很多东西。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的回答概括性太强，我没听懂细节。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告缺少概括性，读起来很乱。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的题目一般都有概括性。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "概括", "label": "词根"}], "register": "书面", "sense_fingerprint": "归纳总结共同特征的特性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9731bc0-27a4-4e2f-ae72-9377691b0db9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19918, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "概括性", "is_correct": true, "explanation": "概括性修饰条款，指条款写得笼统、覆盖面宽，符合句意。"}, {"text": "口头性", "is_correct": false, "explanation": "语义：用户协议是书面文件，「口头性条款」与协议的书面形式相矛盾。"}, {"text": "情感性", "is_correct": false, "explanation": "语域：条款是法律文本，用「情感性」形容不合规范，也与「清晰说明」的要求相反。"}, {"text": "图像性", "is_correct": false, "explanation": "搭配：「图像性」多修饰图形、画面，不能修饰条款。"}], "explanations": {"概括性": "概括性修饰条款，指条款写得笼统、覆盖面宽，符合句意。", "口头性": "语义：用户协议是书面文件，「口头性条款」与协议的书面形式相矛盾。", "情感性": "语域：条款是法律文本，用「情感性」形容不合规范，也与「清晰说明」的要求相反。", "图像性": "搭配：「图像性」多修饰图形、画面，不能修饰条款。"}, "sentence_index": 0, "correct_answer": "概括性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位医生的概括性很强，每次诊断都有依据。", "explanation": "这里应该用〈严谨性〉。概括性指归纳共同点的特性，不指医生做事是否严密；形容医生做事严谨，应说“严谨性很强”。"}, {"text": "这张桌子的概括性很强。", "explanation": "这里应该用〈结实〉。概括性指归纳共同点的特性，不指家具的牢固程度；形容桌子牢固，应说“很结实”。"}, {"text": "我家的猫很有概括性。", "explanation": "这里应该用〈可爱〉。概括性指归纳共同点的特性，不用来形容动物；形容猫，应说“很可爱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "概括性", "is_correct": true, "explanation": "概括性指能归纳很多事物的共同点，与「能说很多东西」相符。"}, {"text": "单一性", "is_correct": false, "explanation": "语义：单一性指只有一种，与「能说很多东西」的含义相反。"}, {"text": "具体性", "is_correct": false, "explanation": "语义：具体性指细节明确，与「能说很多东西」的广泛含义不符。"}, {"text": "唯一性", "is_correct": false, "explanation": "语义：唯一性指只有一个，与「能说很多东西」的广泛含义相反。"}], "explanations": {"概括性": "概括性指能归纳很多事物的共同点，与「能说很多东西」相符。", "单一性": "语义：单一性指只有一种，与「能说很多东西」的含义相反。", "具体性": "语义：具体性指细节明确，与「能说很多东西」的广泛含义不符。", "唯一性": "语义：唯一性指只有一个，与「能说很多东西」的广泛含义相反。"}, "sentence_index": 6, "correct_answer": "概括性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把尺子的概括性很高，能量到毫米。", "explanation": "这里应该用〈精确性〉。概括性指归纳共同点的特性，不指测量的准确程度；尺子能量到毫米，应说精确性高。"}, {"text": "这家银行的概括性很高，存款很安全。", "explanation": "这里应该用〈可靠性〉。概括性指归纳共同点的特性，不指银行的信用程度；存款安全，应说可靠性高。"}, {"text": "他的译文概括性很好，读起来很顺。", "explanation": "这里应该用〈流畅性〉。概括性指归纳共同点的特性，不指译文是否通顺；读起来很顺，应说流畅性好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告有一把很强的概括性，读起来很清楚。", "corrected_sentence": "这份报告有一种很强的概括性，读起来很清楚。", "error_description": "量词错误：「概括性」是抽象名词，应用「种」；「把」用于有柄的器具，不能用来修饰概括性。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的回答很概括性，抓住了重点。", "corrected_sentence": "他的回答很有概括性，抓住了重点。", "error_description": "搭配错误：「概括性」是名词，不能直接用「很」修饰，应说「很有概括性」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
