INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19919, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "条款指文件或合同中的具体规定或项目。", "primary_collocate": null, "pronunciation": "tiáo kuǎn", "ipa": "tʰiɑʊ³⁵ kʰuan²¹⁴", "syllable_count": 2, "sentences": [{"text": "首先，训练数据的采集与使用需满足“知情—同意”框架的实质要求，这意味着企业不能仅依赖用户协议中的概括性条款，而应通过分层披露机制，清晰说明数据将被用于模型训练的具体场景、类别及潜在影响，尤其在涉及个人敏感信息或生成式内容时，须实现可验证的用户授权路径。", "target_word": "条款", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "合同里增加了一项新条款。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你仔细看一下这些条款。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份协议一共有二十项条款。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司改了租房合同的条款。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没看清楚条款，就签了字。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些条款对客人不太公平。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照条款，你可以退钱。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不同意其中一个条款。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "条款写得很清楚，大家都看得懂。", "target_word": "条款", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "條款", "label": "繁体"}, {"form": "项", "label": "量词"}, {"form": "条", "label": "量词"}], "register": "书面", "sense_fingerprint": "文件或合同中的具体规定项目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9731bc0-27a4-4e2f-ae72-9377691b0db9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19919, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "条款", "is_correct": true, "explanation": "条款指文件中的规定，「概括性条款」指写得笼统的规定，符合句意。"}, {"text": "图片", "is_correct": false, "explanation": "语义：用户协议是文字文件，不含图片，「概括性图片」与句意不符。"}, {"text": "乐曲", "is_correct": false, "explanation": "搭配：「概括性」修饰的是规定性文字，不能用来修饰乐曲。"}, {"text": "歌曲", "is_correct": false, "explanation": "语域：用户协议是法律文本，「歌曲」不属于其中的内容，语体也不符。"}], "explanations": {"条款": "条款指文件中的规定，「概括性条款」指写得笼统的规定，符合句意。", "图片": "语义：用户协议是文字文件，不含图片，「概括性图片」与句意不符。", "乐曲": "搭配：「概括性」修饰的是规定性文字，不能用来修饰乐曲。", "歌曲": "语域：用户协议是法律文本，「歌曲」不属于其中的内容，语体也不符。"}, "sentence_index": 0, "correct_answer": "条款"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个花园里一共有二十项条款。", "explanation": "这里应该用〈树〉。条款指文件或合同中的规定，不指园中的树木；说花园里有多少棵树，应说“二十棵树”。"}, {"text": "我的同学一共有二十项条款。", "explanation": "这里应该用〈人〉。条款指文件或合同中的规定，不指同学；说同学有多少，应说“二十个人”。"}, {"text": "这次考试一共有三百项条款。", "explanation": "这里应该用〈题〉。条款指文件或合同中的规定，不指考试的题目；说考试有多少道题，应说“三百道题”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19919, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "条款", "is_correct": true, "explanation": "条款指文件中的规定，主语「这些条款」对客人不公平，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气没有公平与否的评价，「天气对客人不太公平」与句意不符。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：「对客人不太公平」评价的是规定或安排，不能用于声音。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不存在对客人公平与否的问题，句子不成立。"}], "explanations": {"条款": "条款指文件中的规定，主语「这些条款」对客人不公平，符合句意。", "天气": "语义：天气没有公平与否的评价，「天气对客人不太公平」与句意不符。", "声音": "搭配：「对客人不太公平」评价的是规定或安排，不能用于声音。", "颜色": "语义：颜色不存在对客人公平与否的问题，句子不成立。"}, "sentence_index": 6, "correct_answer": "条款"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的条款很好，适合出去玩。", "explanation": "这里应该用〈天气〉。条款指写下来的规则或条件，不指天气；说天气好，应说“天气很好”。"}, {"text": "这件衣服的条款很鲜艳，我很喜欢。", "explanation": "这里应该用〈颜色〉。条款指写下来的规则或条件，不指衣物的色彩；说颜色鲜艳，应说“颜色很鲜艳”。"}, {"text": "这首歌的条款很好听。", "explanation": "这里应该用〈旋律〉。条款指写下来的规则或条件，歌曲没有条款；形容歌好听，应说“旋律很好听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19919, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份协议里有一把条款不公平。", "corrected_sentence": "这份协议里有一项条款不公平。", "error_description": "量词错误：条款应用「项」或「条」，「把」用于有柄的器具，不能修饰条款。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19919, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些条款们对租客很不公平。", "corrected_sentence": "这些条款对租客很不公平。", "error_description": "词缀错误：条款是抽象名词，不加「们」；「这些条款们」错误，应直接说「这些条款」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f52347f1-10d3-4c46-9f46-bf7d3662fdaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
