INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19922, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指能够创造新内容（如文字、图片）的模型或技术。", "primary_collocate": null, "pronunciation": "shēng chéng shì", "ipa": "ʂəŋ˥ ʈʂʰəŋ˧˥ ʂʐ̩˥˩", "syllable_count": 3, "sentences": [{"text": "首先，训练数据的采集与使用需满足“知情—同意”框架的实质要求，这意味着企业不能仅依赖用户协议中的概括性条款，而应通过分层披露机制，清晰说明数据将被用于模型训练的具体场景、类别及潜在影响，尤其在涉及个人敏感信息或生成式内容时，须实现可验证的用户授权路径。", "target_word": "生成式", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "生成式人工智能能写文章，也能画画。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用生成式软件做了一张图片。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个生成式模型可以写诗。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生成式工具帮我写了一封信。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上介绍了生成式技术。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款生成式应用很受年轻人欢迎。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生成式模型需要很多数据来学习。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用生成式程序做了一首歌。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多公司都在用生成式人工智能。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "生成式：能创造新内容的模型或技术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e616806e-61bf-4de6-8b15-ca92d8620822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19922, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生成式", "is_correct": true, "explanation": "正确：修饰“内容”，指能创造新内容的，符合句意。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容温度，不能用来修饰“内容”，句意不通。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”是味觉词，不能修饰“内容”，句意不通。"}, {"text": "酸", "is_correct": false, "explanation": "语义：“酸”是味觉词，不能修饰“内容”，句意不通。"}], "explanations": {"生成式": "正确：修饰“内容”，指能创造新内容的，符合句意。", "寒冷": "语义：“寒冷”形容温度，不能用来修饰“内容”，句意不通。", "咸": "语义：“咸”是味觉词，不能修饰“内容”，句意不通。", "酸": "语义：“酸”是味觉词，不能修饰“内容”，句意不通。"}, "sentence_index": 0, "correct_answer": "生成式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这款生成式手表能测心跳。", "explanation": "这里应该用〈智能〉。生成式指能创造新内容的模型或技术，测心跳不是创造新内容，应该用“智能”。"}, {"text": "这台生成式机器能洗碗。", "explanation": "这里应该用〈自动〉。洗碗是机器自己完成的动作，不是创造新内容，应该用“自动”。"}, {"text": "这部生成式相机能防水。", "explanation": "这里应该用〈数码〉。生成式指能创造新内容的技术，防水是相机的性能，不是创造内容，应该用“数码”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生成式", "is_correct": true, "explanation": "正确：修饰“应用”，指能创造新内容的，符合句意。"}, {"text": "甜腻", "is_correct": false, "explanation": "语义：“甜腻”形容味道，不能修饰“应用”，句意不通。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不能用来修饰“应用”，句意不通。"}, {"text": "昏庸", "is_correct": false, "explanation": "语义：「昏庸」形容人糊涂、不明事理，不能用来修饰「应用」，句意不通。"}], "explanations": {"生成式": "正确：修饰“应用”，指能创造新内容的，符合句意。", "甜腻": "语义：“甜腻”形容味道，不能修饰“应用”，句意不通。", "清脆": "语义：“清脆”形容声音，不能用来修饰“应用”，句意不通。", "昏庸": "语义：「昏庸」形容人糊涂、不明事理，不能用来修饰「应用」，句意不通。"}, "sentence_index": 6, "correct_answer": "生成式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "语言学课上，老师讲了乔姆斯基的生成式语法。", "explanation": "这里的〈生成式〉指语言学中的生成式语法，是另一个义项，与“能创造新内容的模型或技术”不符。"}, {"text": "我的论文主要研究生成式语法的理论。", "explanation": "这里的〈生成式〉指语言学中的生成式语法，是另一个义项，与“能创造新内容的模型或技术”不符。"}, {"text": "这本书介绍了生成式语法的发展史。", "explanation": "这里的〈生成式〉指语言学中的生成式语法，是另一个义项，与“能创造新内容的模型或技术”不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个很生成式工具能写出新文章。", "corrected_sentence": "这个生成式工具能写出新文章。", "error_description": "程度词误用：“很”不能直接修饰作定语的“生成式”，应说“这个生成式工具”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个生成式模型能生成式新文字。", "corrected_sentence": "这个生成式模型能生成新文字。", "error_description": "词形错误：这里的动词应该用“生成”，“生成式”是修饰名词的形式，不能作动词。正确的说法是“能生成新文字”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
