INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19923, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指能够通过某种方法或过程来确认其真实性或正确性。", "primary_collocate": null, "pronunciation": "kě yàn zhèng", "ipa": "kʰɤ˨˩˦ jɛn˥˩ ʈʂəŋ˥˩", "syllable_count": 3, "sentences": [{"text": "首先，训练数据的采集与使用需满足“知情—同意”框架的实质要求，这意味着企业不能仅依赖用户协议中的概括性条款，而应通过分层披露机制，清晰说明数据将被用于模型训练的具体场景、类别及潜在影响，尤其在涉及个人敏感信息或生成式内容时，须实现可验证的用户授权路径。", "target_word": "可验证", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个结果是可验证的。", "target_word": "可验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学要求实验结果可验证。", "target_word": "可验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话没有可验证的依据。", "target_word": "可验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息可验证吗？", "target_word": "可验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的计划应该有可验证的目标。", "target_word": "可验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些数据都是可验证的。", "target_word": "可验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要求答案必须可验证。", "target_word": "可验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的消息不一定都可验证。", "target_word": "可验证", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要一套可验证的流程。", "target_word": "可验证", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可驗證", "label": "繁体"}], "register": "书面", "sense_fingerprint": "可验证：能通过方法确认真实或正确", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e616806e-61bf-4de6-8b15-ca92d8620822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19923, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可验证", "is_correct": true, "explanation": "正确。「须实现可验证的用户授权路径」指授权路径能被确认，与前文「清晰说明」一致。"}, {"text": "模糊", "is_correct": false, "explanation": "语义：「模糊」与前文「清晰说明」相反，「须实现模糊的用户授权路径」自相矛盾。"}, {"text": "隐蔽", "is_correct": false, "explanation": "语义：「隐蔽」与「分层披露机制」「清晰说明」相矛盾，不能用来修饰授权路径。"}, {"text": "随意", "is_correct": false, "explanation": "语义：「随意」与「须」和「实质要求」相矛盾，用户授权路径不能是随意的。"}], "explanations": {"可验证": "正确。「须实现可验证的用户授权路径」指授权路径能被确认，与前文「清晰说明」一致。", "模糊": "语义：「模糊」与前文「清晰说明」相反，「须实现模糊的用户授权路径」自相矛盾。", "隐蔽": "语义：「隐蔽」与「分层披露机制」「清晰说明」相矛盾，不能用来修饰授权路径。", "随意": "语义：「随意」与「须」和「实质要求」相矛盾，用户授权路径不能是随意的。"}, "sentence_index": 0, "correct_answer": "可验证"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一个可验证的朋友。", "explanation": "这里应该用〈可靠〉。可验证指能用方法确认真假，不用来形容人的品质。"}, {"text": "这家饭馆的菜是可验证的。", "explanation": "这里应该用〈美味〉。可验证只指能否确认真假，不能用来评价菜的味道。"}, {"text": "今天的天气很可验证。", "explanation": "这里应该用〈晴朗〉。可验证指能否确认真假，不用来形容天气好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19923, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可验证", "is_correct": true, "explanation": "正确。「这些数据都是可验证的」说数据能被核实，符合语境。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」形容人或物的身材、体积，不能用来形容数据。"}, {"text": "甜蜜", "is_correct": false, "explanation": "语义：「甜蜜」指味道或感情，数据不能是甜蜜的。"}, {"text": "可爱", "is_correct": false, "explanation": "搭配：「可爱」多用于人或动物，「数据」不能说可爱。"}], "explanations": {"可验证": "正确。「这些数据都是可验证的」说数据能被核实，符合语境。", "高大": "体貌：「高大」形容人或物的身材、体积，不能用来形容数据。", "甜蜜": "语义：「甜蜜」指味道或感情，数据不能是甜蜜的。", "可爱": "搭配：「可爱」多用于人或动物，「数据」不能说可爱。"}, "sentence_index": 6, "correct_answer": "可验证"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的小狗是可验证的。", "explanation": "这里应该用〈可爱〉。可验证指能否确认真假，不用来形容动物惹人喜爱的样子。"}, {"text": "这座公园是可验证的。", "explanation": "这里应该用〈美丽〉。可验证只说能否核实，不用来形容风景的美丑。"}, {"text": "他是一个可验证的学生。", "explanation": "这里应该用〈聪明〉。可验证指能否确认真假，不用来评价学生的智力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19923, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份名单上的信息是可验证。", "corrected_sentence": "这份名单上的信息是可验证的。", "error_description": "「可验证」作「是」的谓语时要带「的」，应说「是可验证的」，去掉「的」是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19923, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套系统的记录都是可验证。", "corrected_sentence": "这套系统的记录都是可验证的。", "error_description": "「可验证」作「是」的谓语时要带「的」，应说「都是可验证的」，漏掉「的」是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
