INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19924, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "依法授予他人某种权利。", "primary_collocate": null, "pronunciation": "shòu quán", "ipa": "ʂoʊ̯˥˩ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "首先，训练数据的采集与使用需满足“知情—同意”框架的实质要求，这意味着企业不能仅依赖用户协议中的概括性条款，而应通过分层披露机制，清晰说明数据将被用于模型训练的具体场景、类别及潜在影响，尤其在涉及个人敏感信息或生成式内容时，须实现可验证的用户授权路径。", "target_word": "授权", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "公司已经授权律师处理这件事。", "target_word": "授权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者授权出版社出版这本书。", "target_word": "授权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者没有授权我们使用这张照片。", "target_word": "授权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把公司的商标授权给了朋友。", "target_word": "授权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府授权这家公司管理机场。", "target_word": "授权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司授权他代表自己签合同。", "target_word": "授权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院授权警察搜查这间房子。", "target_word": "授权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专利所有人授权我们使用这项技术。", "target_word": "授权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家授权博物馆展出他的作品。", "target_word": "授权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "授权了", "label": "体标"}, {"form": "授权过", "label": "体标"}, {"form": "授权书", "label": "复合"}, {"form": "授权人", "label": "复合"}, {"form": "授權", "label": "繁体"}], "register": "正式", "sense_fingerprint": "依法把某种权利交给他人，多用于法律、商业、公文场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e616806e-61bf-4de6-8b15-ca92d8620822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19924, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "授权", "is_correct": true, "explanation": "正确。授权（shòu quán）指依法把某种权利交给他人。"}, {"text": "售券", "is_correct": false, "explanation": "quàn（第四声）与 quán（第二声）声调不同，售券意思是卖票。"}, {"text": "收权", "is_correct": false, "explanation": "shōu（第一声）与 shòu（第四声）声调不同，收权意思是收回权力，与授权相反。"}, {"text": "收拳", "is_correct": false, "explanation": "shōu（第一声）与 shòu（第四声）声调不同，收拳意思是收起拳头。"}], "explanations": {"授权": "正确。授权（shòu quán）指依法把某种权利交给他人。", "售券": "quàn（第四声）与 quán（第二声）声调不同，售券意思是卖票。", "收权": "shōu（第一声）与 shòu（第四声）声调不同，收权意思是收回权力，与授权相反。", "收拳": "shōu（第一声）与 shòu（第四声）声调不同，收拳意思是收起拳头。"}, "sentence_index": null, "correct_answer": "授权"}, "level_3": {"options": [{"text": "授权", "is_correct": true, "explanation": "正确。「用户授权路径」指用户同意授予权利的路径，与「知情—同意」框架一致。"}, {"text": "猜测", "is_correct": false, "explanation": "语义：「猜测」与「可验证」相矛盾，猜测的路径无法被确认。"}, {"text": "杜撰", "is_correct": false, "explanation": "语义：「杜撰」指编造，与「可验证」「实质要求」相矛盾。"}, {"text": "隐瞒", "is_correct": false, "explanation": "搭配：「隐瞒」与「路径」搭配不当，且与「分层披露」相矛盾。"}], "explanations": {"授权": "正确。「用户授权路径」指用户同意授予权利的路径，与「知情—同意」框架一致。", "猜测": "语义：「猜测」与「可验证」相矛盾，猜测的路径无法被确认。", "杜撰": "语义：「杜撰」指编造，与「可验证」「实质要求」相矛盾。", "隐瞒": "搭配：「隐瞒」与「路径」搭配不当，且与「分层披露」相矛盾。"}, "sentence_index": 0, "correct_answer": "授权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校授权毕业证。", "explanation": "这里应该用〈颁发〉。授权指把权利交给他人，毕业证是证书，要用「颁发」。"}, {"text": "他授权了我的请求。", "explanation": "这里应该用〈答应〉。授权指把权利交给别人，不用来回应请求。"}, {"text": "他授权了规则。", "explanation": "这里应该用〈遵守〉。授权是把权利交给他人，规则应该被遵守，不能被授权。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "授权", "is_correct": true, "explanation": "正确。「公司授权他代表自己签合同」指公司把签约的权利交给他，符合语境。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」不能表示把权利交给别人，「公司唱他代表自己签合同」不成立。"}, {"text": "煮", "is_correct": false, "explanation": "语义：「煮」与「签合同」的动作不相关，句子无法成立。"}, {"text": "砍", "is_correct": false, "explanation": "搭配：「砍」与「签合同」不搭配，签合同的动作不能用「砍」来表示。"}], "explanations": {"授权": "正确。「公司授权他代表自己签合同」指公司把签约的权利交给他，符合语境。", "唱": "语义：「唱」不能表示把权利交给别人，「公司唱他代表自己签合同」不成立。", "煮": "语义：「煮」与「签合同」的动作不相关，句子无法成立。", "砍": "搭配：「砍」与「签合同」不搭配，签合同的动作不能用「砍」来表示。"}, "sentence_index": 6, "correct_answer": "授权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "领导授权了我的申请。", "explanation": "这里应该用〈批准〉。授权是把权利交给他人，审批申请要用「批准」。"}, {"text": "他授权了我的邀请。", "explanation": "这里应该用〈接受〉。授权指交出权利，不能用来回应邀请。"}, {"text": "士兵授权了命令。", "explanation": "这里应该用〈执行〉。授权是交出权利，命令要被执行，不能被授权。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板把授权我签这份合同。", "corrected_sentence": "老板授权我签这份合同。", "error_description": "「授权」是动词，前面不能加「把」。「把」字句要求「把」后接受事宾语再接动词，此处应直接说「老板授权我签这份合同」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们明天授权了他代理这个品牌。", "corrected_sentence": "我们明天授权他代理这个品牌。", "error_description": "「明天」表示将来，「授权」后不能加「了」，应为「我们明天授权他代理这个品牌」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0820b03-5790-418e-b985-0acbbf7b8a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
