INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19927, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "用来解释某个词语或句子的含义和用法的性质。", "primary_collocate": null, "pronunciation": "jiě shì xìng", "ipa": "tɕjɛ˨˩ ʂɨ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这份说明的解释性很强，初学者也能看懂。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本词典的释义写得很有解释性，读者容易看懂。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师写了一段解释性的文字。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些注释都是解释性的，不用背。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的解释性说明很清楚。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在文章后面加了解释性的话。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告的解释性很强，我看懂了。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段说明的解释性不够，学生还是不懂。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在表格下面写一句解释性的话。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "解释性文字不能太长，要简单。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解释性文字", "label": "复合"}, {"form": "解释性说明", "label": "复合"}], "register": "书面语", "sense_fingerprint": "用来解释词语或句子含义和用法的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfaf90dd-f4b7-4419-b579-a42415751b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19927, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解释性", "is_correct": true, "explanation": "与“初学者也能看懂”一致，说明文字能让人理解，符合语境。"}, {"text": "保密性", "is_correct": false, "explanation": "语义：保密性强则不便公开，与“初学者也能看懂”的意思相反。"}, {"text": "随机性", "is_correct": false, "explanation": "搭配：“随机性”多用于数据或过程，一般不说“说明的随机性很强”。"}, {"text": "盈利性", "is_correct": false, "explanation": "语义：“盈利性”与说明文字能否看懂无关，不能用来形容说明。"}], "explanations": {"解释性": "与“初学者也能看懂”一致，说明文字能让人理解，符合语境。", "保密性": "语义：保密性强则不便公开，与“初学者也能看懂”的意思相反。", "随机性": "搭配：“随机性”多用于数据或过程，一般不说“说明的随机性很强”。", "盈利性": "语义：“盈利性”与说明文字能否看懂无关，不能用来形容说明。"}, "sentence_index": 0, "correct_answer": "解释性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌很有解释性，听了让人想哭。", "explanation": "这里应该用〈感人〉。解释性用于说明词句含义的文字，不用来形容歌曲打动人心。"}, {"text": "他的性格很有解释性，大家都喜欢和他聊天。", "explanation": "解释性用于说明词句、图表等，不用于形容人的性格；形容性格应用〈开朗〉之类的词。"}, {"text": "这次考试的成绩很有解释性，我们都很满意。", "explanation": "这里应该用〈优秀〉。解释性说明的是文字或图表的作用，不用于描述成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19927, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解释性", "is_correct": true, "explanation": "与“我看懂了”一致，说明报告容易理解，符合语境。"}, {"text": "模糊性", "is_correct": false, "explanation": "语义：报告模糊就难以看懂，与“我看懂了”冲突。"}, {"text": "抽象性", "is_correct": false, "explanation": "语义：报告过于抽象不容易看懂，与“我看懂了”的结果相矛盾。"}, {"text": "复杂性", "is_correct": false, "explanation": "语义：报告很复杂就不易看懂，与“我看懂了”冲突。"}], "explanations": {"解释性": "与“我看懂了”一致，说明报告容易理解，符合语境。", "模糊性": "语义：报告模糊就难以看懂，与“我看懂了”冲突。", "抽象性": "语义：报告过于抽象不容易看懂，与“我看懂了”的结果相矛盾。", "复杂性": "语义：报告很复杂就不易看懂，与“我看懂了”冲突。"}, "sentence_index": 6, "correct_answer": "解释性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥的解释性很好，走起来很稳。", "explanation": "解释性用于说明词句或图表，不用来描述桥梁；这里应该用〈坚固〉。"}, {"text": "妈妈做的菜很有解释性，好吃极了。", "explanation": "解释性用于文字、图表等的说明，不用来形容菜的味道；这里应该用〈美味〉。"}, {"text": "他的脚步很有解释性，走得很快。", "explanation": "解释性不用于描述人的动作；形容脚步的快慢应该用〈轻快〉或〈迅速〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19927, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套教材很解释性，学生容易看懂。", "corrected_sentence": "这套教材很有解释性，学生容易看懂。", "error_description": "错误：“很解释性”漏了“有”。正确说法是“很有解释性”，“有”不能省。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19927, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套词典的释义写得很解释性，读者容易看懂。", "corrected_sentence": "这套词典的释义写得很有解释性，读者容易看懂。", "error_description": "错误：「很」后漏了「有」，「很解释性」不成立。正确说法是「很有解释性」，「有」不能省。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
