INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19928, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "文档指记录信息的电子文件或纸质文件，通常包含文字、表格等内容。", "primary_collocate": null, "pronunciation": "wén dàng", "ipa": "wən˧˥ tɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "其次，算法透明度并非要求公开源代码或核心商业机密，而是通过“可解释性报告”“影响评估文档”等形式，向监管机构与公众传达系统的关键决策逻辑、偏差缓解措施及风险控制机制。", "target_word": "文档", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "请把这份文档发给我。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电脑里打开了文档。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个文档一共有三页。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在修改文档的标题。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文档里有文字，也有表格。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要我检查这份文档的错字。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把文档保存在电脑里了。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的文档要放在安全的地方。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文档记录了会议的内容。", "target_word": "文档", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "文檔", "label": "繁体"}], "register": "中性", "sense_fingerprint": "记录信息的电子或纸质文件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfaf90dd-f4b7-4419-b579-a42415751b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19928, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文档", "is_correct": true, "explanation": "与“影响评估”搭配，指记录评估结果的书面文件，可以作为传达的形式。"}, {"text": "人员", "is_correct": false, "explanation": "语义：这里的“形式”指的是书面载体，人员不能作为传达信息的形式。"}, {"text": "场地", "is_correct": false, "explanation": "语义：场地不是用来传达评估结果的形式，与“传达”的意思不符。"}, {"text": "资金", "is_correct": false, "explanation": "搭配：“影响评估”不说“资金”，资金与评估并不构成搭配。"}], "explanations": {"文档": "与“影响评估”搭配，指记录评估结果的书面文件，可以作为传达的形式。", "人员": "语义：这里的“形式”指的是书面载体，人员不能作为传达信息的形式。", "场地": "语义：场地不是用来传达评估结果的形式，与“传达”的意思不符。", "资金": "搭配：“影响评估”不说“资金”，资金与评估并不构成搭配。"}, "sentence_index": 0, "correct_answer": "文档"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把文档装进冰箱，放在冷冻室里。", "explanation": "这里把“文档”误当成了可以冷藏的食物。文档是记录信息的纸张或电子文件，不能放进冰箱保存。"}, {"text": "妈妈每天都吃文档当早饭。", "explanation": "这里把“文档”误当成了食物。文档指记录信息的纸张或电子文件，不能当早饭吃，应该用〈面包〉〈牛奶〉之类的食物作宾语。"}, {"text": "这个文档昨天生病了，今天去了医院。", "explanation": "文档没有生命，不会生病，不能用“生病”来形容它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文档", "is_correct": true, "explanation": "与“检查”搭配，指需要核对内容的文件，符合语境。"}, {"text": "饭", "is_correct": false, "explanation": "语义：经理要检查的是文件，不是饭。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“检查”一般不搭配“早餐”，需要核对的应是文件。"}, {"text": "盒饭", "is_correct": false, "explanation": "语义：“检查”的对象应是文件内容，盒饭与句意不符。"}], "explanations": {"文档": "与“检查”搭配，指需要核对内容的文件，符合语境。", "饭": "语义：经理要检查的是文件，不是饭。", "早餐": "搭配：“检查”一般不搭配“早餐”，需要核对的应是文件。", "盒饭": "语义：“检查”的对象应是文件内容，盒饭与句意不符。"}, "sentence_index": 6, "correct_answer": "文档"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份文档很甜，我很喜欢。", "explanation": "这里把“文档”误当成了食物。文档是记录信息的纸张或电子文件，没有味道，不能用〈香甜〉〈美味〉之类的词形容。"}, {"text": "我在花园里种了一份文档，每天浇水。", "explanation": "这里把“文档”误当成了植物。文档是记录信息的纸张或电子文件，不能种在花园里，也不需要浇水，应该用〈花〉〈树〉之类的植物作“种”的宾语。"}, {"text": "这份文档会跑步，跑得很快。", "explanation": "文档没有动作能力，不能用“跑步”来形容它。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只文档一共有五页。", "corrected_sentence": "这份文档一共有五页。", "error_description": "量词错误：“文档”应用〈份〉或〈个〉，“只”多用于动物，不能用来计量文档。正确形式是“这份文档”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些文档们都很重要。", "corrected_sentence": "这些文档都很重要。", "error_description": "错误：“文档”是物，不能加“们”表示复数。多个文档直接说“这些文档”即可，正确形式是“这些文档都很重要”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
