INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19929, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为实现特定目标而建立的组织或部门，如政府机构、科研机构。", "primary_collocate": null, "pronunciation": "jī gòu", "ipa": "tɕi˥ kou˥˩", "syllable_count": 2, "sentences": [{"text": "这家科研机构有很多专家。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府机构要为人民服务。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家金融机构工作。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机构成立了十年。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请联系有关机构了解情况。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家建立了专门的检查机构。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家机构的研究员每年做一次调查。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医疗机构要保护病人的信息。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想去国际机构实习。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些机构都由政府管理。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "政府机构", "label": "复合"}, {"form": "科研机构", "label": "复合"}, {"form": "金融机构", "label": "复合"}, {"form": "機構", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "为实现特定目标而建立的组织或部门", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfaf90dd-f4b7-4419-b579-a42415751b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19929, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机构", "is_correct": true, "explanation": "正确：“机构”指为实现特定目标而设立的组织，“科研机构”是常见搭配，与“有很多专家”相符。"}, {"text": "餐厅", "is_correct": false, "explanation": "语义：“餐厅”是吃饭的地方，不是科研单位，“科研餐厅”说不通。"}, {"text": "铺子", "is_correct": false, "explanation": "语域：“铺子”是口语，指小买卖的店，与书面语“科研”不协调，也不是研究单位。"}, {"text": "宾馆", "is_correct": false, "explanation": "语义：“宾馆”是住宿的地方，与“科研”无关，“科研宾馆”说不通。"}], "explanations": {"机构": "正确：“机构”指为实现特定目标而设立的组织，“科研机构”是常见搭配，与“有很多专家”相符。", "餐厅": "语义：“餐厅”是吃饭的地方，不是科研单位，“科研餐厅”说不通。", "铺子": "语域：“铺子”是口语，指小买卖的店，与书面语“科研”不协调，也不是研究单位。", "宾馆": "语义：“宾馆”是住宿的地方，与“科研”无关，“科研宾馆”说不通。"}, "sentence_index": 0, "correct_answer": "机构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个句子的机构很复杂。", "explanation": "这里应该用〈结构〉。“机构”指组织或部门，句子内部的组合方式要用“结构”，不能用“机构”。"}, {"text": "我买了一个机构，放在书桌上。", "explanation": "这里应该用〈台灯〉之类的物品。“机构”指为实现特定目标而设立的组织，不能买来放在桌上。"}, {"text": "我们几个朋友组成了一个小机构，每周一起爬山。", "explanation": "这里应该用〈团体〉。“机构”指为实现特定目标而设立的正式组织，几个朋友自发组成的小群体要用“团体”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19929, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机构", "is_correct": true, "explanation": "正确：“机构”指组织，可以每年开展调查，与“这家”和“做一次调查”相符。"}, {"text": "理发店", "is_correct": false, "explanation": "语义：理发店没有研究员，“理发店的研究员”说不通。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不设研究员，“花园的研究员”说不通。"}, {"text": "小店", "is_correct": false, "explanation": "语义：小店一般没有研究员，“小店的研究员”说不通。"}], "explanations": {"机构": "正确：“机构”指组织，可以每年开展调查，与“这家”和“做一次调查”相符。", "理发店": "语义：理发店没有研究员，“理发店的研究员”说不通。", "花园": "语义：花园不设研究员，“花园的研究员”说不通。", "小店": "语义：小店一般没有研究员，“小店的研究员”说不通。"}, "sentence_index": 6, "correct_answer": "机构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的猫是一个机构。", "explanation": "这里应该用〈动物〉。“机构”指为实现特定目标而设立的组织，不能用来指一只猫，猫属于动物。"}, {"text": "妈妈在厨房里做了一个机构给我吃。", "explanation": "这里应该用〈蛋糕〉之类的食物。“机构”是组织或部门，不能做来吃。"}, {"text": "这个机构有五口人。", "explanation": "这里应该用〈家庭〉。“五口人”是用来数家庭成员的说法，“机构”是组织，不能这样计算人口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19929, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去了一只大型研究机构。", "corrected_sentence": "他去了一家大型研究机构。", "error_description": "量词错误：“机构”应该用量词“家”或“个”，不能用“只”。“只”多用于动物或成对物品之一，如“一只猫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19929, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前在一把国际机构工作过。", "corrected_sentence": "我以前在一家国际机构工作过。", "error_description": "量词错误：“机构”应该用量词“家”，不能用“把”。“把”多用于有柄的东西，如“一把椅子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19930, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19930, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19930, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对重要事情做出选择和判断。", "primary_collocate": null, "pronunciation": "jué cè", "ipa": "tɕye˧˥ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "代理不仅执行任务，还能对自身决策过程进行反思性建模，通过多层级反馈回路调整目标函数。", "target_word": "决策", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种潜在的技术异化，迫使我们必须重新审视图灵测试之后的智能评估体系：是否应建立“自主性-责任性”双轴评价框架，以衡量代理在自由决策与社会嵌入之间的平衡能力？", "target_word": "决策", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "其次，算法透明度并非要求公开源代码或核心商业机密，而是通过“可解释性报告”“影响评估文档”等形式，向监管机构与公众传达系统的关键决策逻辑、偏差缓解措施及风险控制机制。", "target_word": "决策", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "经理在会上做出了一项重要决策。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的决策需要足够的信息。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个决策让全公司的人都很吃惊。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对这次决策负全部责任。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "错误的决策会让公司损失很多钱。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市长的决策影响了整个城市。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的重大决策要由董事会讨论。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "决策者", "label": "复合"}, {"form": "決策", "label": "繁体"}], "register": "书面", "sense_fingerprint": "决策|名词|对重要事情做出的选择和判断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dab0c558-bacf-42b5-ac45-3bf523f0ba2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19930, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "决策", "is_correct": true, "explanation": "正确。“决策过程”指做选择和判断的过程，正是句中反思建模的对象。"}, {"text": "答案", "is_correct": false, "explanation": "语义：“答案”是结果，不是可以被建模的决策过程，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“过程”前不能用“颜色”这类表示属性的名词来修饰。"}, {"text": "事儿", "is_correct": false, "explanation": "语域：“事儿”是口语词，与这句书面语的语域不符。"}], "explanations": {"决策": "正确。“决策过程”指做选择和判断的过程，正是句中反思建模的对象。", "答案": "语义：“答案”是结果，不是可以被建模的决策过程，句意不通。", "颜色": "搭配：“过程”前不能用“颜色”这类表示属性的名词来修饰。", "事儿": "语域：“事儿”是口语词，与这句书面语的语域不符。"}, "sentence_index": 0, "correct_answer": "决策"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题有四个决策。", "explanation": "这里应该用〈选项〉。“决策”指做选择和判断的行为，题目里供挑选的备选答案要说“选项”。"}, {"text": "他喝了一杯决策。", "explanation": "这里应该用〈茶〉。“杯”用来计量饮品，“决策”是做选择和判断的行为，不能喝。"}, {"text": "这首歌的决策很动听。", "explanation": "这里应该用〈旋律〉。“决策”指对事情做选择和判断，不能用来形容歌曲的好听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "决策", "is_correct": true, "explanation": "正确。“对这次决策负全部责任”中，决策是承担责任的对象。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“负全部责任”只能用于能由人承担的事项，不能说对天气负全部责任。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，不是人可以承担责任的决定，句意不通。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是一段时间，不是可以负责的行为或判断，与句意冲突。"}], "explanations": {"决策": "正确。“对这次决策负全部责任”中，决策是承担责任的对象。", "天气": "搭配：“负全部责任”只能用于能由人承担的事项，不能说对天气负全部责任。", "地震": "语义：地震是自然灾害，不是人可以承担责任的决定，句意不通。", "节日": "语义：节日是一段时间，不是可以负责的行为或判断，与句意冲突。"}, "sentence_index": 6, "correct_answer": "决策"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他下定了决策要减肥。", "explanation": "这里应该用〈决心〉。“下定决心”表示意志，“决策”指对事情做选择和判断，不能用于此处。"}, {"text": "他做事很有决策。", "explanation": "这里应该用〈决断〉。“有决断”描述人做事果断，“决策”指做出的选择和判断本身，不能用来形容人的性格。"}, {"text": "这片海的决策很蓝。", "explanation": "这里应该用〈颜色〉。“决策”指对重要事情做选择和判断，不能用来形容颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些重大的决策们需要董事会批准。", "corrected_sentence": "这些重大的决策需要董事会批准。", "error_description": "错误：“们”只能加在指人的名词后面，“决策”是抽象名词，不能说“决策们”，应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "领导们做出了一只重大的决策。", "corrected_sentence": "领导们做出了一项重大的决策。", "error_description": "错误：量词“只”用于动物等，不能用于“决策”。正确的量词是“项”，应说“一项重大的决策”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
