INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19931, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指与标准或正确的情况不同的地方。", "primary_collocate": null, "pronunciation": "piān chā", "ipa": "pʰjɛn˥ ʈʂʰa˥", "syllable_count": 2, "sentences": [{"text": "其次，算法透明度并非要求公开源代码或核心商业机密，而是通过“可解释性报告”“影响评估文档”等形式，向监管机构与公众传达系统的关键决策逻辑、偏差缓解措施及风险控制机制。", "target_word": "偏差", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这次测量的结果有一点偏差。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这件事的理解有偏差。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器出现偏差，数字不太准。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发现我的发音有偏差。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数据和标准值的偏差很小。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "射击时，枪的方向有偏差，没打中。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你检查一下，看计划有没有偏差。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要及时改正工作中的偏差。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他算得很仔细，所以结果没有偏差。", "target_word": "偏差", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "标准偏差", "label": "复合"}, {"form": "偏差值", "label": "复合"}], "register": "中性", "sense_fingerprint": "与标准或正确情况不符的差距", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dfaf90dd-f4b7-4419-b579-a42415751b5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19931, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偏差", "is_correct": true, "explanation": "正确：“偏差”指与标准不符的地方，“偏差缓解措施”指减少这种不符的办法，与前文的算法决策相符。"}, {"text": "速度", "is_correct": false, "explanation": "语义：“速度”指快慢，与算法的决策和风险无关，“速度缓解措施”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的身体特征，与算法系统无关，不能说“身高缓解措施”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与决策逻辑和风险控制无关，“颜色缓解措施”说不通。"}], "explanations": {"偏差": "正确：“偏差”指与标准不符的地方，“偏差缓解措施”指减少这种不符的办法，与前文的算法决策相符。", "速度": "语义：“速度”指快慢，与算法的决策和风险无关，“速度缓解措施”说不通。", "身高": "体貌：“身高”是人的身体特征，与算法系统无关，不能说“身高缓解措施”。", "颜色": "语义：“颜色”与决策逻辑和风险控制无关，“颜色缓解措施”说不通。"}, "sentence_index": 0, "correct_answer": "偏差"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上喝一杯偏差。", "explanation": "这里把“偏差”当成了饮料，应该用〈牛奶〉之类的词。“偏差”指与标准不符的地方，不能喝。"}, {"text": "这份报告里有一座偏差。", "explanation": "这里应该用〈个〉或〈处〉。“座”多用于山、楼、桥等大型的东西，“偏差”不用“座”来数。"}, {"text": "我和他之间有个偏差。", "explanation": "这里应该用〈误会〉。“偏差”指与标准或事实不符的差异，人与人之间因理解不同产生的错会要说“误会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19931, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偏差", "is_correct": true, "explanation": "正确：“偏差”指与标准不符的地方，“枪的方向有偏差”说的是方向偏离目标，与“没打中”相符。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”指听到的声响，枪的方向不是声音，“方向有声音”说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，与射击的方向无关，“方向有味道”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“有”之后接“体重”多用于人或动物，不能说枪的方向有体重。"}], "explanations": {"偏差": "正确：“偏差”指与标准不符的地方，“枪的方向有偏差”说的是方向偏离目标，与“没打中”相符。", "声音": "语义：“声音”指听到的声响，枪的方向不是声音，“方向有声音”说不通。", "味道": "语义：“味道”指气味或滋味，与射击的方向无关，“方向有味道”说不通。", "体重": "搭配：“有”之后接“体重”多用于人或动物，不能说枪的方向有体重。"}, "sentence_index": 6, "correct_answer": "偏差"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个偏差很贵，我买不起。", "explanation": "这里把“偏差”当成了可以买卖的东西。“偏差”指与标准不符的地方，不能用〈贵〉来形容。"}, {"text": "我在公园里看见一个偏差在跑步。", "explanation": "这里把“偏差”当成了人或动物。“偏差”是抽象的“与标准不符”，不会跑步。"}, {"text": "他的偏差很高兴地笑了。", "explanation": "这里把“偏差”当成了会笑的人。“偏差”是抽象的“与标准不符”，不能作人的主语，也没有表情动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19931, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器有一把偏差。", "corrected_sentence": "这台机器有一点偏差。", "error_description": "量词错误：“偏差”不用“把”，应该用“点”。“把”多用于有柄的东西，如“一把伞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19931, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这组数据和标准值有一根偏差。", "corrected_sentence": "这组数据和标准值有一点偏差。", "error_description": "量词错误：“偏差”用“点”，不用“根”。“根”多用于细长的东西，如“一根绳子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e324d21-1ebc-4b3a-b369-c80e4dc6defb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
