INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19936, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "提交立法机关审议的法律草案。", "primary_collocate": null, "pronunciation": "fǎ àn", "ipa": "fa˨˩˦ an˥˩", "syllable_count": 2, "sentences": [{"text": "议会今天讨论了一项新法案。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项法案还没有通过。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统签署了新法案，内容与保护环境有关。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议员们对这个法案有不同意见。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府向国会提交了一项新法案，内容是调整税收。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个法案要经过三次投票。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "反对这项法案的人很多。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们修改了法案里的几条规定。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个法案提出降低企业税。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法案通过后，新规定下月开始。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}], "register": "正式", "sense_fingerprint": "法案|提交立法机关审议的法律草案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27fdbf91-5a57-494c-bcdf-8cffdfde2c0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19936, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "法案", "is_correct": true, "explanation": "法案 fǎ àn：提交立法机关审议的法律草案，即听到的词。"}, {"text": "方案", "is_correct": false, "explanation": "fāng（第一声）与 fǎ（第三声）韵母与声调都不同，fāng àn 意思是计划方案。"}, {"text": "发案", "is_correct": false, "explanation": "fā（第一声）与 fǎ（第三声）声调不同，fā àn 意思是案件发生。"}, {"text": "翻案", "is_correct": false, "explanation": "fān（第一声）与 fǎ（第三声）韵母与声调不同，fān àn 意思是推翻原来的判决。"}, {"text": "犯案", "is_correct": false, "explanation": "fàn（第四声）与 fǎ（第三声）韵母与声调不同，fàn àn 意思是作案。"}], "explanations": {"法案": "法案 fǎ àn：提交立法机关审议的法律草案，即听到的词。", "方案": "fāng（第一声）与 fǎ（第三声）韵母与声调都不同，fāng àn 意思是计划方案。", "发案": "fā（第一声）与 fǎ（第三声）声调不同，fā àn 意思是案件发生。", "翻案": "fān（第一声）与 fǎ（第三声）韵母与声调不同，fān àn 意思是推翻原来的判决。", "犯案": "fàn（第四声）与 fǎ（第三声）韵母与声调不同，fàn àn 意思是作案。"}, "sentence_index": null, "correct_answer": "法案"}, "level_3": {"options": [{"text": "法案", "is_correct": true, "explanation": "法案：提交立法机关审议的法律草案，符合“议会讨论”的语境。"}, {"text": "手术", "is_correct": false, "explanation": "语义：议会讨论的是法律草案，不会讨论手术。"}, {"text": "把戏", "is_correct": false, "explanation": "语义：“把戏”指花招或表演，不能成为议会讨论的对象。"}, {"text": "招", "is_correct": false, "explanation": "语域：“招”是口语说法，不能用于议会讨论正式文件的句子。"}], "explanations": {"法案": "法案：提交立法机关审议的法律草案，符合“议会讨论”的语境。", "手术": "语义：议会讨论的是法律草案，不会讨论手术。", "把戏": "语义：“把戏”指花招或表演，不能成为议会讨论的对象。", "招": "语域：“招”是口语说法，不能用于议会讨论正式文件的句子。"}, "sentence_index": 0, "correct_answer": "法案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "饭店的法案每个月都会更换。", "explanation": "这里应该用〈菜单〉。法案是提交立法机关审议的法律草案，饭店的菜单不属于法案。"}, {"text": "公司新法案要求员工准时上班。", "explanation": "这里应该用〈规定〉。法案只指立法机关审议的法律草案，公司内部的要求只能说规定。"}, {"text": "我们的旅行法案下周开始执行。", "explanation": "这里应该用〈计划〉。法案是提交立法机关的法律草案，个人的旅行安排只能说计划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19936, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法案", "is_correct": true, "explanation": "法案：可以被反对的法律草案，符合句意。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：“反对”的对象是提案或措施，不能说反对成绩。"}, {"text": "绝活", "is_correct": false, "explanation": "语域：“绝活”是口语，且“反对绝活”的搭配不成立，不适合正式语境。"}, {"text": "天赋", "is_correct": false, "explanation": "语义：天赋是个人的能力，不是可以被反对的政策或草案。"}], "explanations": {"法案": "法案：可以被反对的法律草案，符合句意。", "成绩": "搭配：“反对”的对象是提案或措施，不能说反对成绩。", "绝活": "语域：“绝活”是口语，且“反对绝活”的搭配不成立，不适合正式语境。", "天赋": "语义：天赋是个人的能力，不是可以被反对的政策或草案。"}, "sentence_index": 6, "correct_answer": "法案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈按照法案做了红烧肉。", "explanation": "这里应该用〈食谱〉。法案是提交立法机关审议的法律草案，做菜要依据食谱。"}, {"text": "公司这次的营销法案很有创意。", "explanation": "这里应该用〈方案〉。法案指立法机关审议的法律草案，公司的营销计划只能说方案。"}, {"text": "老师公布了期末考试的法案。", "explanation": "这里应该用〈名单〉。法案是立法机关审议的法律草案，期末考试的名单不叫法案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19936, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国会昨天通过了一只新法案。", "corrected_sentence": "国会昨天通过了一项新法案。", "error_description": "量词错误：“只”用于动物或成对的东西，法案应该用量词“项”。正确说法是“一项新法案”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国会上周通过着那项新法案。", "corrected_sentence": "国会上周通过了那项新法案。", "error_description": "错误在体标：“上周通过”是已完成的动作，动词后应用“了”；“着”表示持续的状态，不能用在这里。正确说法是“通过了那项新法案”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
