INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19939, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "追究责任，指对错误或事故的责任人进行问责。", "primary_collocate": null, "pronunciation": "zhuī zé", "ipa": "ʈʂweɪ̯˥ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "当前，欧盟《人工智能法案》与美国联邦贸易委员会（FTC）的执法指南均表明，监管趋势正从“事后追责”转向“前置性问责”，企业若未能建立可审计的合规证据链，将面临声誉折损与巨额罚款的双重风险。", "target_word": "追责", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工厂发生了事故，政府要追责。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次事故以后，公司开始追责相关负责人。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人说应该先追责，再谈赔偿。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁来为这件事负责，大家都要求追责。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了问题，我们不能只追责一个人。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "领导没有追责他，只是批评了几句。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府已经对这次火灾追责了。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事故调查结果出来了，下一步就是追责。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前没有人追责过这种错误。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "追责了", "label": "体标（了）"}, {"form": "追责过", "label": "体标（过）"}], "register": "正式", "sense_fingerprint": "追责：对错误或事故的责任人追究责任、进行问责（动词，正式）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27fdbf91-5a57-494c-bcdf-8cffdfde2c0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19939, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追责", "is_correct": true, "explanation": "追责：对事后出现的错误追究责任，符合“事后追责”的语境。"}, {"text": "预见", "is_correct": false, "explanation": "语义：“预见”指事先看到，与“事后”的时间语境矛盾。"}, {"text": "追求", "is_correct": false, "explanation": "语义：“追求”指努力争取目标，“事后追求”说不通，与“问责”的语境不合。"}, {"text": "催促", "is_correct": false, "explanation": "语义：“催促”指促使他人快些行动，与“事后”的监管转向语境不合。"}], "explanations": {"追责": "追责：对事后出现的错误追究责任，符合“事后追责”的语境。", "预见": "语义：“预见”指事先看到，与“事后”的时间语境矛盾。", "追求": "语义：“追求”指努力争取目标，“事后追求”说不通，与“问责”的语境不合。", "催促": "语义：“催促”指促使他人快些行动，与“事后”的监管转向语境不合。"}, "sentence_index": 0, "correct_answer": "追责"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "调查组正在追责事故的原因。", "explanation": "这里应该用〈追查〉。追责针对责任人，查找事故原因要用“追查”。"}, {"text": "他决定追责借给朋友的那笔钱。", "explanation": "这里应该用〈追回〉。追责针对人的过错，讨回财物要用“追回”。"}, {"text": "我们决定追责这次成绩突出的员工。", "explanation": "这里应该用〈奖励〉。追责只用于错误和事故，不能用于功劳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19939, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追责", "is_correct": true, "explanation": "追责：领导没有对他追究责任，只是批评，符合句子语境。"}, {"text": "追讨", "is_correct": false, "explanation": "搭配：“追讨”用于债务或财物，不能用于追究人的责任。"}, {"text": "追悼", "is_correct": false, "explanation": "语义：“追悼”指悼念死者，与领导处理犯错者的语境不合。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”与后面的“只是批评了几句”重复矛盾。"}], "explanations": {"追责": "追责：领导没有对他追究责任，只是批评，符合句子语境。", "追讨": "搭配：“追讨”用于债务或财物，不能用于追究人的责任。", "追悼": "语义：“追悼”指悼念死者，与领导处理犯错者的语境不合。", "批评": "语义：“批评”与后面的“只是批评了几句”重复矛盾。"}, "sentence_index": 6, "correct_answer": "追责"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直在追责自己的理想，从不放弃。", "explanation": "这里是〈追求〉的意思，但“追责”只表示追究责任，不表示执着地争取理想。"}, {"text": "老师追责了认真学习的学生。", "explanation": "这里应该用〈夸奖〉。追责针对过错，认真学习的学生应当夸奖。"}, {"text": "学校追责了这次获奖的同学。", "explanation": "这里应该用〈表彰〉。获奖的同学应当表彰，不能追责。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19939, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "调查结束后，公司决定追责了那位负责人。", "corrected_sentence": "调查结束后，公司决定追责那位负责人。", "error_description": "错误在“追责”后面加了“了”。“决定”引出的是尚未发生的行动，动词后加“了”使其像已完成的动作，句子不通；应说“决定追责那位负责人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19939, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "以前他没有追责了下属。", "corrected_sentence": "以前他没有追责过下属。", "error_description": "错误在“过”处换成了“了”。否定过去是否做过某事，要说“没有追责过”，“没有……了”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
