INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19940, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "放在前面，或者使事物处于优先位置。", "primary_collocate": null, "pronunciation": "qián zhì", "ipa": "tɕʰi̯ɛn˧˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "当前，欧盟《人工智能法案》与美国联邦贸易委员会（FTC）的执法指南均表明，监管趋势正从“事后追责”转向“前置性问责”，企业若未能建立可审计的合规证据链，将面临声誉折损与巨额罚款的双重风险。", "target_word": "前置", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司把安全检查前置到了设计阶段。", "target_word": "前置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院把检查前置了，病人可以早点治疗。", "target_word": "前置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师建议把复习前置，不要考试前才开始。", "target_word": "前置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目的审核要前置。", "target_word": "前置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定把风险管理前置。", "target_word": "前置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把服务前置了，在客人到达以前就准备好了。", "target_word": "前置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该把预防工作前置，而不是出事后再处理。", "target_word": "前置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把心理辅导前置到了入学第一周。", "target_word": "前置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府把环保评估前置了。", "target_word": "前置", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前置了", "label": "体标（了）"}, {"form": "前置性", "label": "复合"}], "register": "正式", "sense_fingerprint": "前置：把工作、环节等提前并放在优先位置（动词，正式）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27fdbf91-5a57-494c-bcdf-8cffdfde2c0c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19940, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前置", "is_correct": true, "explanation": "前置 qiánzhì：把工作或环节提前，放在优先位置。"}, {"text": "前肢", "is_correct": false, "explanation": "qiánzhī（第一声）与 qiánzhì（第四声）声调不同，前肢指动物的前腿。"}, {"text": "前室", "is_correct": false, "explanation": "声母 sh 与 zh 不同（qiánshì），前室指外间的房间。"}, {"text": "前世", "is_correct": false, "explanation": "声母 sh 与 zh 不同，“前世”指前生，与“前置”的声母不同。"}], "explanations": {"前置": "前置 qiánzhì：把工作或环节提前，放在优先位置。", "前肢": "qiánzhī（第一声）与 qiánzhì（第四声）声调不同，前肢指动物的前腿。", "前室": "声母 sh 与 zh 不同（qiánshì），前室指外间的房间。", "前世": "声母 sh 与 zh 不同，“前世”指前生，与“前置”的声母不同。"}, "sentence_index": null, "correct_answer": "前置"}, "level_3": {"options": [{"text": "前置", "is_correct": true, "explanation": "前置：提前并放在优先位置，与“事后追责”形成对照。"}, {"text": "布置", "is_correct": false, "explanation": "语义：“布置”指安排、摆放，与“性问责”的时间含义不符。"}, {"text": "设置", "is_correct": false, "explanation": "搭配：“设置”多指设立机构或设备，不能组成“设置性问责”。"}, {"text": "配置", "is_correct": false, "explanation": "配价：“配置”需要带受配的资源或设备，不能直接修饰“问责”。"}], "explanations": {"前置": "前置：提前并放在优先位置，与“事后追责”形成对照。", "布置": "语义：“布置”指安排、摆放，与“性问责”的时间含义不符。", "设置": "搭配：“设置”多指设立机构或设备，不能组成“设置性问责”。", "配置": "配价：“配置”需要带受配的资源或设备，不能直接修饰“问责”。"}, "sentence_index": 0, "correct_answer": "前置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把工作前置了，今天却一直在拖延。", "explanation": "这里是〈拖延〉的意思，但“前置”只表示提前或放到前面，不表示拖着不做。"}, {"text": "他把旧合同前置了，已经作废了。", "explanation": "这里是〈作废〉的意思，但“前置”只表示提前或放到前面，不表示宣布合同失效。"}, {"text": "他把孩子的意见前置了，完全不理睬。", "explanation": "这里是〈忽视〉的意思，但“前置”只表示提前或放到前面，不表示置之不理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19940, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "前置", "is_correct": true, "explanation": "前置 qiánzhì：把工作或环节提前，放在优先位置。"}, {"text": "前址", "is_correct": false, "explanation": "qiánzhǐ（第三声）与 qiánzhì（第四声）声调不同，前址指原来的地址。"}, {"text": "前翅", "is_correct": false, "explanation": "声母 ch 与 zh 不同，前翅指昆虫的前翅膀。"}, {"text": "前值", "is_correct": false, "explanation": "qiánzhí（第二声）与 qiánzhì（第四声）声调不同，前值指前一个数值。"}], "explanations": {"前置": "前置 qiánzhì：把工作或环节提前，放在优先位置。", "前址": "qiánzhǐ（第三声）与 qiánzhì（第四声）声调不同，前址指原来的地址。", "前翅": "声母 ch 与 zh 不同，前翅指昆虫的前翅膀。", "前值": "qiánzhí（第二声）与 qiánzhì（第四声）声调不同，前值指前一个数值。"}, "sentence_index": null, "correct_answer": "前置"}, "level_3": {"options": [{"text": "前置", "is_correct": true, "explanation": "前置：把服务提前，在客人到达之前完成准备。"}, {"text": "后置", "is_correct": false, "explanation": "语义：“后置”指放在后面，与“客人到达以前就准备好了”的时间顺序相反。"}, {"text": "搁置", "is_correct": false, "explanation": "搭配：“搁置”多用于问题或计划，不能用来说“搁置服务”，且与“准备好了”矛盾。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”指去掉，与“在客人到达以前就准备好了”矛盾。"}], "explanations": {"前置": "前置：把服务提前，在客人到达之前完成准备。", "后置": "语义：“后置”指放在后面，与“客人到达以前就准备好了”的时间顺序相反。", "搁置": "搭配：“搁置”多用于问题或计划，不能用来说“搁置服务”，且与“准备好了”矛盾。", "删除": "语义：“删除”指去掉，与“在客人到达以前就准备好了”矛盾。"}, "sentence_index": 6, "correct_answer": "前置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们把这个项目前置了，到明年再说。", "explanation": "这里应该用〈推迟〉。前置是提前，“到明年再说”是往后推，要用“推迟”。"}, {"text": "我们把这个方案前置了，马上就删掉了。", "explanation": "这里是〈删除〉的意思，但“前置”只表示提前或放到前面，不表示去掉。"}, {"text": "他们把旧楼前置了。", "explanation": "这里应该用〈拆除〉。前置是放到前面，不表示去掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司把安全检查前置着。", "corrected_sentence": "公司把安全检查前置了。", "error_description": "错误在“着”：“把”字句表示完成的处置，“前置”是一次性动作，不能加表示持续的“着”，应说“把安全检查前置了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们以前没有把服务前置了。", "corrected_sentence": "他们以前没有把服务前置过。", "error_description": "错误在“过”处用成了“了”。否定过去的经历要说“没有……过”，“没有”后不能用“了”，应说“没有把服务前置过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '021b7708-422e-43eb-844c-1e7609f00d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19941, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19941, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19941, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指追究某件事的责任，要求当事人说明情况或承担责任。", "primary_collocate": null, "pronunciation": "wèn zé", "ipa": "wən˥˩ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "当前，欧盟《人工智能法案》与美国联邦贸易委员会（FTC）的执法指南均表明，监管趋势正从“事后追责”转向“前置性问责”，企业若未能建立可审计的合规证据链，将面临声誉折损与巨额罚款的双重风险。", "target_word": "问责", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "出了事故，公司要对负责人问责。", "target_word": "问责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市民要求对这次错误的责任人问责。", "target_word": "问责", "complexity_tier": "T3", "furigana": "shì mín yāo qiú duì zhè cì cuò wù de zé rèn rén wèn zé", "sentence_source": "generated"}, {"text": "部门出了问题，上级会依法问责。", "target_word": "问责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "媒体可以对做出错误决定的官员问责。", "target_word": "问责", "complexity_tier": "T3", "furigana": "méi tǐ kě yǐ duì zuò chū cuò wù jué dìng de guān yuán wèn zé", "sentence_source": "generated"}, {"text": "学校没有及时处理，家长们要求问责。", "target_word": "问责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行违反规定，监管部门已经问责了相关人员。", "target_word": "问责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认为只有认真问责，才能避免同样的错误。", "target_word": "问责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "董事会决定对这次失误严肃问责。", "target_word": "问责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁该为这次污染负责，政府一定会问责。", "target_word": "问责", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "问责制", "label": "复合"}, {"form": "问责过", "label": "体标"}], "register": "正式", "sense_fingerprint": "追究责任，要求当事人说明并承担", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbcaf301-82fc-4b3d-abe8-64f62bf9c1e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19941, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "问责", "is_correct": true, "explanation": "正确。“问责”指追究责任，与句中的“事后追责”相对，符合“前置性问责”的语境。"}, {"text": "包庇", "is_correct": false, "explanation": "语义：包庇是袒护错误，与“追究责任”的监管意图完全相反，填入后句意荒谬。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：隐瞒是掩盖事实，与“要求说明情况”的方向相反，不能用来描述监管趋势。"}, {"text": "赔偿", "is_correct": false, "explanation": "搭配：“赔偿”针对损失或受害方，不能说“前置性赔偿”这种事前的监管方式。"}], "explanations": {"问责": "正确。“问责”指追究责任，与句中的“事后追责”相对，符合“前置性问责”的语境。", "包庇": "语义：包庇是袒护错误，与“追究责任”的监管意图完全相反，填入后句意荒谬。", "隐瞒": "语义：隐瞒是掩盖事实，与“要求说明情况”的方向相反，不能用来描述监管趋势。", "赔偿": "搭配：“赔偿”针对损失或受害方，不能说“前置性赔偿”这种事前的监管方式。"}, "sentence_index": 0, "correct_answer": "问责"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "经理问责了这份方案。", "explanation": "这里应该用〈同意〉。同意是表示赞成、认可，可以用于方案；问责是追究责任，不能以“方案”作对象。"}, {"text": "老师当场问责学生的原因，学生都不敢说话。", "explanation": "这里应该用〈追问〉。问责针对的是承担责任的人，要求其承认并承担；询问原因要用追问，不能以“原因”作问责的对象。"}, {"text": "这次能顺利完成，我非常问责他的帮助。", "explanation": "这里应该用〈感谢〉。感谢是表达谢意，可以用于帮助；问责是追究责任、要求对方承担过错，不表示感激。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19941, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "问责", "is_correct": true, "explanation": "正确。“问责”表示追究相关人员的责任，与“违反规定”的处理语境吻合。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是褒奖，与“违反规定”后的处理方向相反，不能用于违规人员。"}, {"text": "慰问", "is_correct": false, "explanation": "语义：“慰问”表示关怀，句中是监管部门对违规者的处理，不能用慰问。"}, {"text": "庆祝", "is_correct": false, "explanation": "搭配：“庆祝”多搭配事件或节日，不带“相关人员”这类被处理的对象。"}], "explanations": {"问责": "正确。“问责”表示追究相关人员的责任，与“违反规定”的处理语境吻合。", "表扬": "语义：“表扬”是褒奖，与“违反规定”后的处理方向相反，不能用于违规人员。", "慰问": "语义：“慰问”表示关怀，句中是监管部门对违规者的处理，不能用慰问。", "庆祝": "搭配：“庆祝”多搭配事件或节日，不带“相关人员”这类被处理的对象。"}, "sentence_index": 6, "correct_answer": "问责"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他向受伤的同学问责，说了一句对不起。", "explanation": "这里应该用〈道歉〉。道歉是向人认错致歉；问责是要求责任人承担责任，不能用来表示歉意。"}, {"text": "公司问责了客户的全部损失。", "explanation": "这里应该用〈赔偿〉。赔偿针对的是损失；问责的对象是责任人，不能以“损失”作宾语。"}, {"text": "大家一直问责他的勇气。", "explanation": "这里应该用〈赞美〉。赞美是称赞好的品质，可以用于勇气；问责是追究责任，不能表示称赞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19941, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "调查结束后，公司决定问责过他。", "corrected_sentence": "调查结束后，公司决定问责他。", "error_description": "错误：“决定”表示将来的打算，“问责过”用的是经历体，与将来的打算不符。正确应为“决定问责他”，动词后不加“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19941, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校没问责了班主任。", "corrected_sentence": "学校没问责班主任。", "error_description": "错误：“没”否定已经发生的动作时不能与“了”同用，“没问责了”不合语法。正确应为“没问责班主任”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19942, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19942, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19942, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用来证明某个事实或真相的材料或信息。", "primary_collocate": null, "pronunciation": "zhèng jù", "ipa": "ʈʂɤŋ˥˩ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "例如，在协助科研工作者梳理跨学科文献时，它不仅能提取关键假设与实验证据，还能识别不同领域的方法论冲突，并提出融合路径的试探性建议——这已超越传统信息检索工具的功能边界，趋近于认知协作者的角色。", "target_word": "证据", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "警察找到了新的证据。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有证据，不能说他有罪。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官要求律师拿出更多证据。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些照片是重要的证据。", "target_word": "证据", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "科学家用实验得到了可靠的证据。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们有证据证明他当时不在家。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把证据交给了警察。", "target_word": "证据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份证据能说明事情的真相。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "证据太少，案子还没有结论。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "證據", "label": "繁体"}], "register": "中性", "sense_fingerprint": "证据|名词|用来证明事实或真相的材料或信息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dab0c558-bacf-42b5-ac45-3bf523f0ba2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19942, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "证据", "is_correct": true, "explanation": "证据：zhèng jù，指能证明事实的材料或信息。"}, {"text": "整句", "is_correct": false, "explanation": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是完整的句子。"}, {"text": "正数", "is_correct": false, "explanation": "shù（第四声）与 jù 声母不同（sh／j），意思是大于零的数。"}, {"text": "正序", "is_correct": false, "explanation": "xù 与 jù 声母不同（x／j），意思是正常的顺序。"}], "explanations": {"证据": "证据：zhèng jù，指能证明事实的材料或信息。", "整句": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是完整的句子。", "正数": "shù（第四声）与 jù 声母不同（sh／j），意思是大于零的数。", "正序": "xù 与 jù 声母不同（x／j），意思是正常的顺序。"}, "sentence_index": null, "correct_answer": "证据"}, "level_3": {"options": [{"text": "证据", "is_correct": true, "explanation": "与前文“提取关键假设与实验证据”搭配，指可用于证明假设的材料，符合句意。"}, {"text": "工具", "is_correct": false, "explanation": "搭配：“提取”的对象是假设、证据这类信息，不能提取“工具”。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与这段书面、学术化的表述不协调。"}, {"text": "感情", "is_correct": false, "explanation": "语义：“感情”无法与“假设”并列作为“提取”的对象，句意不通。"}], "explanations": {"证据": "与前文“提取关键假设与实验证据”搭配，指可用于证明假设的材料，符合句意。", "工具": "搭配：“提取”的对象是假设、证据这类信息，不能提取“工具”。", "玩意儿": "语域：“玩意儿”是口语说法，与这段书面、学术化的表述不协调。", "感情": "语义：“感情”无法与“假设”并列作为“提取”的对象，句意不通。"}, "sentence_index": 0, "correct_answer": "证据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿着证据去银行取钱。", "explanation": "这里应该用〈存折〉或〈银行卡〉。取钱要用存折或银行卡；证据是证明事实的材料，不能用来取钱。"}, {"text": "他去派出所办理证据。", "explanation": "这里应该用〈证件〉。办理的是身份证、护照等证件；证据是证明事实的材料，不能办理。"}, {"text": "我们需要出示入场证据才能进去。", "explanation": "这里应该用〈凭证〉。进场时要出示的是门票或入场凭证；证据是证明事实的材料，不能拿来当作入场凭证。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19942, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "证据", "is_correct": true, "explanation": "证据：zhèng jù，指能证明事实的材料或信息。"}, {"text": "政局", "is_correct": false, "explanation": "jú（第二声）与 jù（第四声）声调不同，意思是政治局势。"}, {"text": "正路", "is_correct": false, "explanation": "lù 与 jù 声母不同（l／j），意思是正确的道路。"}, {"text": "整句", "is_correct": false, "explanation": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是完整的句子。"}], "explanations": {"证据": "证据：zhèng jù，指能证明事实的材料或信息。", "政局": "jú（第二声）与 jù（第四声）声调不同，意思是政治局势。", "正路": "lù 与 jù 声母不同（l／j），意思是正确的道路。", "整句": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是完整的句子。"}, "sentence_index": null, "correct_answer": "证据"}, "level_3": {"options": [{"text": "证据", "is_correct": true, "explanation": "“有证据证明……”是常见用法，指有能证明事实的材料，符合句意。"}, {"text": "答案", "is_correct": false, "explanation": "搭配：“答案”不能用来“证明他不在家”，“有答案证明”搭配不当。"}, {"text": "钱", "is_correct": false, "explanation": "语义：钱不能证明一个人当时在不在家，句意不通。"}, {"text": "谎言", "is_correct": false, "explanation": "语义：谎言本身是假话，不能用来证明事实，与“证明他不在家”的句意相矛盾。"}], "explanations": {"证据": "“有证据证明……”是常见用法，指有能证明事实的材料，符合句意。", "答案": "搭配：“答案”不能用来“证明他不在家”，“有答案证明”搭配不当。", "钱": "语义：钱不能证明一个人当时在不在家，句意不通。", "谎言": "语义：谎言本身是假话，不能用来证明事实，与“证明他不在家”的句意相矛盾。"}, "sentence_index": 6, "correct_answer": "证据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他找了一个证据不来上班。", "explanation": "这里应该用〈借口〉。借口是用来推托的说法；证据是证明事实的材料，不能拿来当借口。"}, {"text": "这道题的证据写在纸上了。", "explanation": "这里应该用〈答案〉。考题的解答称为答案；证据不能写在纸上当作解答。"}, {"text": "他被指控犯了证据。", "explanation": "这里应该用〈罪名〉。被指控的是罪名（如盗窃罪），证据不能说“犯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些证据们都很有用。", "corrected_sentence": "这些证据都很有用。", "error_description": "“们”只能加在指人的名词后面，“证据”是抽象名词，不能说“证据们”，应改为“这些证据”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察正在收集一只证据。", "corrected_sentence": "警察正在收集一份证据。", "error_description": "错误：量词“只”用于动物等，不能用于“证据”，应说“一份证据”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2324f598-67e9-4228-9439-eb703c9aa929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
