INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19945, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "形容人或事物处在别人前面，比别人更好、更快或更靠前。", "primary_collocate": null, "pronunciation": "lǐng xiān", "ipa": "liŋ˨˩ ɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "我们队在上半场领先两分。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的技术领先其他公司。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的成绩一直领先全班同学。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛结束时，我们领先对手三分。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国的高铁技术在世界上领先。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个手机的拍照功能领先同类产品。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王的英语水平领先了同组的人。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的服务一直领先别的店。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虽然现在领先，但我们不能放松。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哪个队现在领先？", "target_word": "领先", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "领先了", "label": "完成体（了）"}, {"form": "领先过", "label": "经历体（过）"}, {"form": "遥遥领先", "label": "复合"}], "register": "中性", "sense_fingerprint": "在比赛、成绩、技术等方面处于前列，比别人更强", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbcaf301-82fc-4b3d-abe8-64f62bf9c1e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19945, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "领先", "is_correct": true, "explanation": "正确：“领先”表示位置或成绩靠前，与“上半场”“两分”的比分语境相符。"}, {"text": "输给", "is_correct": false, "explanation": "配价：“输给”需要对手作宾语，不能直接带“两分”。"}, {"text": "晋升", "is_correct": false, "explanation": "搭配：“晋升”不能与分数搭配，比分语境中说不通。"}, {"text": "偷走", "is_correct": false, "explanation": "语义：比赛中“偷走两分”与正常比分语境不符，不是常规表达。"}], "explanations": {"领先": "正确：“领先”表示位置或成绩靠前，与“上半场”“两分”的比分语境相符。", "输给": "配价：“输给”需要对手作宾语，不能直接带“两分”。", "晋升": "搭配：“晋升”不能与分数搭配，比分语境中说不通。", "偷走": "语义：比赛中“偷走两分”与正常比分语境不符，不是常规表达。"}, "sentence_index": 0, "correct_answer": "领先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重领先了三公斤。", "explanation": "这里应该用〈增加〉。领先用于位置或成绩的靠前，体重的增加要说增加。"}, {"text": "班长领先了同学们的疑问。", "explanation": "这里应该用〈解答〉。领先指位置靠前或比别人更好，回答问题要说解答。"}, {"text": "这笔开销领先了预算。", "explanation": "这里应该用〈超过〉。领先不用于数额的超出，开销超出预算要说超过。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19945, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "领先", "is_correct": true, "explanation": "正确：“领先”表示水平或成绩超过他人，与“英语水平”和“同组的人”搭配通顺。"}, {"text": "掩盖", "is_correct": false, "explanation": "语义：“掩盖”表示遮住，不能用来比较“水平”与“同组的人”的高低。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：“修补”用于破损之物，不能用于“水平”。"}, {"text": "绘制", "is_correct": false, "explanation": "语义：“绘制”指画图，与“水平”和“同组的人”不搭。"}], "explanations": {"领先": "正确：“领先”表示水平或成绩超过他人，与“英语水平”和“同组的人”搭配通顺。", "掩盖": "语义：“掩盖”表示遮住，不能用来比较“水平”与“同组的人”的高低。", "修补": "搭配：“修补”用于破损之物，不能用于“水平”。", "绘制": "语义：“绘制”指画图，与“水平”和“同组的人”不搭。"}, "sentence_index": 6, "correct_answer": "领先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师领先了学生的错误。", "explanation": "这里应该用〈纠正〉。领先不用于错误的改正，改正错误要说纠正。"}, {"text": "妈妈领先了一件新衣服。", "explanation": "这里应该用〈购买〉。领先不表示买东西，买衣服要说购买。"}, {"text": "他的头发领先了很多。", "explanation": "这里应该用〈变长〉。领先不用于头发的生长，头发变长要说变长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19945, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "第二节开始时，我们队领先得三分。", "corrected_sentence": "第二节开始时，我们队领先三分。", "error_description": "错误形式：“领先得三分”。正确形式：“领先三分”。“领先”后不接“得”引出补语，数量直接作宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19945, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们队领先对手了三分。", "corrected_sentence": "他们队领先对手三分。", "error_description": "错误：“了”的位置不对，不能放在对象“对手”和数量“三分”之间。正确应为“领先对手三分”（或“领先了对手三分”）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
