INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19947, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19947, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "公众信任和认可的程度，指某个组织或个人在公众中享有的信誉。", "primary_collocate": null, "pronunciation": "gōng xìn lì", "ipa": "kʊŋ˥ ɕin˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "因此，领先的SaaS公司正将合规能力建设嵌入研发流程（DevOps to DevRelOps），在模型训练阶段即引入法律、伦理与社会影响（LESI）审查节点，并通过第三方认证增强公信力。", "target_word": "公信力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家报纸的公信力很高。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说谎会让政府失去公信力。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校需要提高自己的公信力。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公开账目能增强公信力。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有公信力的机构，大家才愿意相信。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次事件损害了医院的公信力。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "媒体的公信力来自真实的报道。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在学生中有很高的公信力。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公信力一旦没有了，就很难找回来。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "组织或个人在公众中获得的信任与认可程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbcaf301-82fc-4b3d-abe8-64f62bf9c1e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19947, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公信力", "is_correct": true, "explanation": "“增强公信力”指提高公众对机构的信任，与前文“通过第三方认证”的语境一致。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“增强”多用于能力、效果等抽象事物，体重应说“增加”，不能说“增强体重”。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“增强”一般不用于面积，面积多说“扩大”或“增加”。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔是地面的高度，不能被“增强”，句意不通。"}], "explanations": {"公信力": "“增强公信力”指提高公众对机构的信任，与前文“通过第三方认证”的语境一致。", "体重": "搭配：“增强”多用于能力、效果等抽象事物，体重应说“增加”，不能说“增强体重”。", "面积": "搭配：“增强”一般不用于面积，面积多说“扩大”或“增加”。", "海拔": "语义：海拔是地面的高度，不能被“增强”，句意不通。"}, "sentence_index": 0, "correct_answer": "公信力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班长的公信力很快，一眨眼就跑完了一圈操场。", "explanation": "这里应该用〈速度〉。速度说的是快慢，公信力指大家相信某人或机构的程度，不能用“快”来形容。"}, {"text": "这个月我的公信力增加了三公斤。", "explanation": "这里应该用〈体重〉。公信力是抽象的信任程度，不能用公斤计量，说体重增加才用“体重”。"}, {"text": "这家小公司的公信力很先进，大家都来参观它的生产线。", "explanation": "这里应该用〈实力〉。先进说的是技术、设备水平，属于实力，公信力指大家的信任程度，不能用“先进”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19947, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公信力", "is_correct": true, "explanation": "“损害”的对象是公信力这类抽象的信誉，与句意一致。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能被损害，句意不通。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“损害”后面多接利益、名誉、健康等，不能接“数量”。"}, {"text": "密度", "is_correct": false, "explanation": "语义：密度是物理属性，不能被损害，句意不通。"}], "explanations": {"公信力": "“损害”的对象是公信力这类抽象的信誉，与句意一致。", "颜色": "语义：颜色不能被损害，句意不通。", "数量": "搭配：“损害”后面多接利益、名誉、健康等，不能接“数量”。", "密度": "语义：密度是物理属性，不能被损害，句意不通。"}, "sentence_index": 6, "correct_answer": "公信力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的公信力很远，能看清十里外的东西。", "explanation": "这里应该用〈视力〉。能看清远处的东西说的是视力，公信力指大家的信任程度，不能用“远”来形容。"}, {"text": "这位歌手的公信力很好听，大家都喜欢。", "explanation": "这里应该用〈声音〉。“好听”形容声音，公信力是抽象的信任，不能用“好听”来描述。"}, {"text": "这幅画的公信力很鲜艳，大家都看呆了。", "explanation": "这里应该用〈颜色〉。“鲜艳”形容颜色，公信力是抽象的信任，不能用“鲜艳”来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19947, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家医院用新办法提高了公信力们，患者更愿意相信它。", "corrected_sentence": "这家医院用新办法提高了公信力，患者更愿意相信它。", "error_description": "错误：“们”只能加在指人的名词或代词后表示复数，不能加在抽象名词“公信力”后。正确是“提高了公信力”，不加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19947, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家医院有一只公信力，大家都相信它。", "corrected_sentence": "这家医院有一定的公信力，大家都相信它。", "error_description": "错误：“只”是量词，用于动物、手等，不能用来修饰抽象的“公信力”。这里应直接用“一定的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99170a0b-fcd3-4dc8-a365-086528c87822') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
