INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19948, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "司法是指国家司法机关依照法定职权和程序，运用法律处理案件的活动。", "primary_collocate": null, "pronunciation": "sī fǎ", "ipa": "sɨ˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个国家的司法很公正。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司法要按照法律办事。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作和司法有关系。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司法不能受别人的影响。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都希望司法更公开。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者写了一篇关于司法的文章。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司法的目的是保护每个人的权利。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的司法和行政是分开的。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校里有一门课专门讲司法的内容。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们相信司法会给他一个公平的结果。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "司法部", "label": "复合词"}, {"form": "司法机关", "label": "复合词"}], "register": "正式", "sense_fingerprint": "国家机关依法处理案件的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c6d0dad-2ddf-4382-b7de-80be2a8c3a9c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是电器，不能用“公正”来评价。"}, {"text": "司法", "is_correct": true, "explanation": "“司法”指司法机关依法处理案件的活动，可以被评价为公正，与句子相符。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不能被评价为公正与否。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是地点，不能被评价为公正与否。"}], "explanations": {"冰箱": "语义：冰箱是电器，不能用“公正”来评价。", "司法": "“司法”指司法机关依法处理案件的活动，可以被评价为公正，与句子相符。", "面包": "语义：面包是食物，不能被评价为公正与否。", "花园": "语义：花园是地点，不能被评价为公正与否。"}, "sentence_index": 0, "correct_answer": "司法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部司法是去年才通过的。", "explanation": "这里应该用〈法律〉。能被通过、按“部”计数的是法律；司法是依法处理案件的活动，不能被通过。"}, {"text": "他决定提起司法。", "explanation": "这里应该用〈诉讼〉。能够“提起”的是诉讼，司法指国家机关依法处理案件的活动，不能被提起。"}, {"text": "他每天早上都喝一杯司法。", "explanation": "这里应该用〈牛奶〉。能喝的是饮料；司法是依法处理案件的活动，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气没有目的，不能说“天气的目的是保护每个人的权利”。"}, {"text": "司法", "is_correct": true, "explanation": "“司法”是司法机关保护权利的活动，“目的”与之搭配，句子成立。"}, {"text": "饮食", "is_correct": false, "explanation": "语义：饮食不是保护权利的机构或制度，句子说不通。"}, {"text": "森林", "is_correct": false, "explanation": "搭配：“森林”可以被保护，但不能作保护权利的主体，句子不通。"}], "explanations": {"天气": "语义：天气没有目的，不能说“天气的目的是保护每个人的权利”。", "司法": "“司法”是司法机关保护权利的活动，“目的”与之搭配，句子成立。", "饮食": "语义：饮食不是保护权利的机构或制度，句子说不通。", "森林": "搭配：“森林”可以被保护，但不能作保护权利的主体，句子不通。"}, "sentence_index": 6, "correct_answer": "司法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法院作出了司法。", "explanation": "这里应该用〈判决〉。法院作出的是判决，司法是整个活动的名称，不能“作出”。"}, {"text": "国家颁布了司法。", "explanation": "这里应该用〈法规〉。颁布的是法规等法律文件，司法是依法处理案件的活动，不能被颁布。"}, {"text": "律师在法庭上提交了司法。", "explanation": "这里应该用〈证据〉。律师在法庭上提交的是证据，不是司法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条司法很公正。", "corrected_sentence": "这种司法很公正。", "error_description": "量词错误：“司法”是抽象的制度或活动，应用“种”。“条”指具体条文或细长的事物（如“一条法律”“一条河”），不适合指称“司法”这样的抽象活动。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个国家地司法非常独立。", "corrected_sentence": "那个国家的司法非常独立。", "error_description": "助词错误：“那个国家”修饰名词“司法”，应该用定语标记“的”，不能用状语标记“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83165e94-7919-4e31-9338-a38194427f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
