INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (19958, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容采取行动或措施，提前阻止可能的攻击或批评。", "primary_collocate": null, "pronunciation": "fáng yù xìng", "ipa": "fɑŋ˧˥ y˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "最终，合规不再仅是防御性策略，而成为塑造用户信任、构建市场差异化的核心竞争力。", "target_word": "防御性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "面对批评，他的第一反应常常是防御性的回答。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到别人提意见，她马上做出防御性的反应。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提前解释一切，这是一种防御性做法。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话很有防御性，好像别人都在批评他。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师发现这个孩子有防御性心理，不愿听建议。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队这场比赛踢得很保守，用了防御性打法。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把可能的批评都提前写进报告，这种防御性的写法让领导无话可说。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行加强防御性措施，提前挡住网络攻击。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问得很尖锐，部长的回答带着防御性。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防禦性", "label": "繁体"}, {"form": "防御性措施", "label": "复合"}, {"form": "防御性策略", "label": "复合"}], "register": "书面", "sense_fingerprint": "防御性：形容行动、措施、态度等提前阻止攻击或批评", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d88bcbd-fe2c-4dba-ab0f-04f6851766bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
